package com.runeglass.runelite;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Base64;
import java.util.List;
import java.util.Objects;
import net.runelite.api.Model;
import net.runelite.api.PlayerComposition;

final class AppearanceMeshEncoder
{
	static final int MAX_MESH_BYTES = 512 * 1_024;
	static final int MAX_VERTEX_COUNT = 25_000;
	static final int MAX_FACE_COUNT = 30_000;
	private static final int HEADER_BYTES = 16;
	private static final int VERTEX_BYTES = 12;
	private static final int FACE_BYTES = 22;

	private AppearanceMeshEncoder()
	{
	}

	static EncodedMesh encode(Model model, PlayerComposition composition)
	{
		return capture(model, composition).encode();
	}

	static CapturedAppearance capture(Model model, PlayerComposition composition)
	{
		Objects.requireNonNull(model, "model");
		Objects.requireNonNull(composition, "composition");
		int vertexCount = model.getVerticesCount();
		int faceCount = model.getFaceCount();
		return new CapturedAppearance(
			Arrays.copyOf(model.getVerticesX(), vertexCount),
			Arrays.copyOf(model.getVerticesY(), vertexCount),
			Arrays.copyOf(model.getVerticesZ(), vertexCount),
			Arrays.copyOf(model.getFaceIndices1(), faceCount),
			Arrays.copyOf(model.getFaceIndices2(), faceCount),
			Arrays.copyOf(model.getFaceIndices3(), faceCount),
			Arrays.copyOf(model.getFaceColors1(), faceCount),
			Arrays.copyOf(model.getFaceColors2(), faceCount),
			Arrays.copyOf(model.getFaceColors3(), faceCount),
			copyOf(model.getFaceTransparencies(), faceCount),
			copyOf(model.getFaceRenderPriorities(), faceCount),
			copyOf(model.getFaceTextures(), faceCount),
			composition.getEquipmentIds().clone(),
			composition.getColors().clone(),
			composition.getGender());
	}

	private static byte[] copyOf(byte[] values, int length)
	{
		return values == null ? null : Arrays.copyOf(values, length);
	}

	private static short[] copyOf(short[] values, int length)
	{
		return values == null ? null : Arrays.copyOf(values, length);
	}

	static EncodedMesh encode(
		float[] verticesX,
		float[] verticesY,
		float[] verticesZ,
		int[] faceIndices1,
		int[] faceIndices2,
		int[] faceIndices3,
		int[] faceColors1,
		int[] faceColors2,
		int[] faceColors3,
		byte[] faceTransparencies,
		byte[] facePriorities,
		short[] faceTextures,
		int[] equipment,
		int[] bodyColors,
		int gender)
	{
		int vertexCount = requireMatchingVertices(verticesX, verticesY, verticesZ);
		if (vertexCount < 3 || vertexCount > MAX_VERTEX_COUNT)
		{
			throw new IllegalArgumentException("Unsupported appearance vertex count");
		}
		if (equipment == null || equipment.length < 1 || equipment.length > 16)
		{
			throw new IllegalArgumentException("Unsupported appearance equipment count");
		}
		if (bodyColors == null || bodyColors.length != 5 || (gender != 0 && gender != 1))
		{
			throw new IllegalArgumentException("Unsupported player composition");
		}

		int sourceFaceCount = requireMatchingFaces(
			faceIndices1,
			faceIndices2,
			faceIndices3,
			faceColors1,
			faceColors2,
			faceColors3);
		List<Integer> includedFaces = new ArrayList<>(sourceFaceCount);
		boolean hasTextures = false;
		for (int face = 0; face < sourceFaceCount; face++)
		{
			if (faceColors3[face] == -2)
			{
				continue;
			}
			validateVertexIndex(faceIndices1[face], vertexCount);
			validateVertexIndex(faceIndices2[face], vertexCount);
			validateVertexIndex(faceIndices3[face], vertexCount);
			includedFaces.add(face);
			hasTextures |= faceTextures != null
				&& face < faceTextures.length
				&& faceTextures[face] != -1;
		}
		int faceCount = includedFaces.size();
		if (faceCount < 1 || faceCount > MAX_FACE_COUNT)
		{
			throw new IllegalArgumentException("Unsupported appearance face count");
		}
		long byteCount = (long) HEADER_BYTES
			+ (long) vertexCount * VERTEX_BYTES
			+ (long) faceCount * FACE_BYTES
			+ (long) equipment.length * Integer.BYTES;
		if (byteCount > MAX_MESH_BYTES)
		{
			throw new IllegalArgumentException("Appearance mesh exceeds upload limit");
		}

		ByteBuffer buffer = ByteBuffer.allocate((int) byteCount).order(ByteOrder.LITTLE_ENDIAN);
		buffer.put((byte) 'R');
		buffer.put((byte) 'G');
		buffer.put((byte) 'M');
		buffer.put((byte) '1');
		buffer.put((byte) 1);
		buffer.put((byte) (hasTextures ? 1 : 0));
		buffer.putShort((short) equipment.length);
		buffer.putInt(vertexCount);
		buffer.putInt(faceCount);
		for (int vertex = 0; vertex < vertexCount; vertex++)
		{
			buffer.putFloat(verticesX[vertex]);
			buffer.putFloat(verticesY[vertex]);
			buffer.putFloat(verticesZ[vertex]);
		}
		for (int face : includedFaces)
		{
			int firstColor = faceColors1[face];
			int secondColor = faceColors2[face];
			int thirdColor = faceColors3[face] == -1 ? firstColor : faceColors3[face];
			if (faceColors3[face] == -1)
			{
				secondColor = firstColor;
			}
			buffer.putInt(faceIndices1[face]);
			buffer.putInt(faceIndices2[face]);
			buffer.putInt(faceIndices3[face]);
			buffer.putShort((short) firstColor);
			buffer.putShort((short) secondColor);
			buffer.putShort((short) thirdColor);
			buffer.put(faceTransparencies != null && face < faceTransparencies.length
				? faceTransparencies[face]
				: (byte) 0);
			buffer.put(facePriorities != null && face < facePriorities.length
				? facePriorities[face]
				: (byte) 0);
			buffer.putShort(faceTextures != null && face < faceTextures.length
				? faceTextures[face]
				: (short) -1);
		}
		for (int equipmentId : equipment)
		{
			if (equipmentId < 0 || equipmentId > 100_000)
			{
				throw new IllegalArgumentException("Unsupported equipment identifier");
			}
			buffer.putInt(equipmentId);
		}
		byte[] bytes = buffer.array();
		return new EncodedMesh(
			Base64.getEncoder().encodeToString(bytes),
			sha256(bytes),
			vertexCount,
			faceCount,
			equipment.clone(),
			bodyColors.clone(),
			gender,
			hasTextures);
	}

	private static int requireMatchingVertices(float[] x, float[] y, float[] z)
	{
		if (x == null || y == null || z == null || x.length != y.length || x.length != z.length)
		{
			throw new IllegalArgumentException("Invalid appearance vertices");
		}
		return x.length;
	}

	private static int requireMatchingFaces(int[]... arrays)
	{
		if (arrays.length == 0 || arrays[0] == null)
		{
			throw new IllegalArgumentException("Invalid appearance faces");
		}
		int length = arrays[0].length;
		for (int[] array : arrays)
		{
			if (array == null || array.length != length)
			{
				throw new IllegalArgumentException("Invalid appearance faces");
			}
		}
		return length;
	}

	private static void validateVertexIndex(int index, int vertexCount)
	{
		if (index < 0 || index >= vertexCount)
		{
			throw new IllegalArgumentException("Invalid appearance face index");
		}
	}

	private static String sha256(byte[] bytes)
	{
		try
		{
			return Base64.getUrlEncoder().withoutPadding()
				.encodeToString(MessageDigest.getInstance("SHA-256").digest(bytes));
		}
		catch (NoSuchAlgorithmException exception)
		{
			throw new IllegalStateException("SHA-256 unavailable", exception);
		}
	}

	static final class EncodedMesh
	{
		private final String meshBase64;
		private final String modelHash;
		private final int vertexCount;
		private final int faceCount;
		private final int[] equipment;
		private final int[] bodyColors;
		private final int gender;
		private final boolean hasTextures;

		private EncodedMesh(
			String meshBase64,
			String modelHash,
			int vertexCount,
			int faceCount,
			int[] equipment,
			int[] bodyColors,
			int gender,
			boolean hasTextures)
		{
			this.meshBase64 = meshBase64;
			this.modelHash = modelHash;
			this.vertexCount = vertexCount;
			this.faceCount = faceCount;
			this.equipment = equipment;
			this.bodyColors = bodyColors;
			this.gender = gender;
			this.hasTextures = hasTextures;
		}

		String getMeshBase64()
		{
			return meshBase64;
		}

		String getModelHash()
		{
			return modelHash;
		}

		int getVertexCount()
		{
			return vertexCount;
		}

		int getFaceCount()
		{
			return faceCount;
		}

		int[] getEquipment()
		{
			return equipment.clone();
		}

		int[] getBodyColors()
		{
			return bodyColors.clone();
		}

		int getGender()
		{
			return gender;
		}

		boolean hasTextures()
		{
			return hasTextures;
		}
	}

	static final class CapturedAppearance
	{
		private final float[] verticesX;
		private final float[] verticesY;
		private final float[] verticesZ;
		private final int[] faceIndices1;
		private final int[] faceIndices2;
		private final int[] faceIndices3;
		private final int[] faceColors1;
		private final int[] faceColors2;
		private final int[] faceColors3;
		private final byte[] faceTransparencies;
		private final byte[] facePriorities;
		private final short[] faceTextures;
		private final int[] equipment;
		private final int[] bodyColors;
		private final int gender;

		private CapturedAppearance(
			float[] verticesX,
			float[] verticesY,
			float[] verticesZ,
			int[] faceIndices1,
			int[] faceIndices2,
			int[] faceIndices3,
			int[] faceColors1,
			int[] faceColors2,
			int[] faceColors3,
			byte[] faceTransparencies,
			byte[] facePriorities,
			short[] faceTextures,
			int[] equipment,
			int[] bodyColors,
			int gender)
		{
			this.verticesX = verticesX;
			this.verticesY = verticesY;
			this.verticesZ = verticesZ;
			this.faceIndices1 = faceIndices1;
			this.faceIndices2 = faceIndices2;
			this.faceIndices3 = faceIndices3;
			this.faceColors1 = faceColors1;
			this.faceColors2 = faceColors2;
			this.faceColors3 = faceColors3;
			this.faceTransparencies = faceTransparencies;
			this.facePriorities = facePriorities;
			this.faceTextures = faceTextures;
			this.equipment = equipment;
			this.bodyColors = bodyColors;
			this.gender = gender;
		}

		EncodedMesh encode()
		{
			return AppearanceMeshEncoder.encode(
				verticesX,
				verticesY,
				verticesZ,
				faceIndices1,
				faceIndices2,
				faceIndices3,
				faceColors1,
				faceColors2,
				faceColors3,
				faceTransparencies,
				facePriorities,
				faceTextures,
				equipment,
				bodyColors,
				gender);
		}
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

final class AppearanceSnapshot
{
	private final String snapshotId;
	private final String observedAt;
	private final AppearanceMeshEncoder.EncodedMesh mesh;

	AppearanceSnapshot(Instant observedAt, AppearanceMeshEncoder.EncodedMesh mesh)
	{
		this.snapshotId = UUID.randomUUID().toString();
		this.observedAt = Objects.requireNonNull(observedAt, "observedAt").toString();
		this.mesh = Objects.requireNonNull(mesh, "mesh");
	}

	String getSnapshotId()
	{
		return snapshotId;
	}

	String getObservedAt()
	{
		return observedAt;
	}

	AppearanceMeshEncoder.EncodedMesh getMesh()
	{
		return mesh;
	}
}

package com.runeglass.runelite;

import java.util.LinkedHashMap;
import java.util.Map;

final class AppearanceSnapshotPayload
{
	private AppearanceSnapshotPayload()
	{
	}

	static Map<String, Object> create(
		SyncContext context,
		String connectionId,
		AppearanceSnapshot snapshot)
	{
		AppearanceMeshEncoder.EncodedMesh mesh = snapshot.getMesh();
		Map<String, Object> appearance = new LinkedHashMap<>();
		appearance.put("meshFormat", "runeglass-mesh-v1");
		appearance.put("modelHash", mesh.getModelHash());
		appearance.put("vertexCount", mesh.getVertexCount());
		appearance.put("faceCount", mesh.getFaceCount());
		appearance.put("equipment", mesh.getEquipment());
		appearance.put("bodyColors", mesh.getBodyColors());
		appearance.put("gender", mesh.getGender());
		appearance.put("hasTextures", mesh.hasTextures());
		appearance.put("meshBase64", mesh.getMeshBase64());

		Map<String, Object> payload = SemanticSnapshotPayload.create(
			context,
			connectionId,
			snapshot.getSnapshotId(),
			snapshot.getObservedAt(),
			"appearance",
			appearance);
		payload.put("consentVersion", 1);
		return payload;
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.Objects;

final class BirdHouseObservation
{
	private final String space;
	private final String state;
	private final String tier;
	private final String startedAt;
	private final String readyAt;

	BirdHouseObservation(
		BirdHouseSpace space,
		BirdHouseState state,
		BirdHouseTier tier,
		Instant startedAt,
		Instant readyAt)
	{
		this.space = Objects.requireNonNull(space, "space").wireValue();
		this.state = Objects.requireNonNull(state, "state").wireValue();
		this.tier = tier == null ? null : tier.wireValue();
		this.startedAt = startedAt == null ? null : startedAt.toString();
		this.readyAt = readyAt == null ? null : readyAt.toString();
	}

	String getSpace()
	{
		return space;
	}

	String getState()
	{
		return state;
	}

	String getTier()
	{
		return tier;
	}

	String getStartedAt()
	{
		return startedAt;
	}

	String getReadyAt()
	{
		return readyAt;
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

final class BirdHouseSnapshot
{
	private final String snapshotId;
	private final String observedAt;
	private final List<BirdHouseObservation> houses;

	BirdHouseSnapshot(Instant observedAt, List<BirdHouseObservation> houses)
	{
		this(UUID.randomUUID().toString(), observedAt, houses);
	}

	BirdHouseSnapshot(
		String snapshotId,
		Instant observedAt,
		List<BirdHouseObservation> houses)
	{
		this.snapshotId = Objects.requireNonNull(snapshotId, "snapshotId");
		this.observedAt = Objects.requireNonNull(observedAt, "observedAt").toString();
		if (houses.size() != BirdHouseSpace.values().length)
		{
			throw new IllegalArgumentException("A bird house snapshot requires four spaces");
		}
		this.houses = Collections.unmodifiableList(new ArrayList<>(houses));
	}

	String getSnapshotId()
	{
		return snapshotId;
	}

	String getObservedAt()
	{
		return observedAt;
	}

	List<BirdHouseObservation> getHouses()
	{
		return houses;
	}
}

package com.runeglass.runelite;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

final class BirdHouseSnapshotReducer
{
	private static final int MAX_VARP = BirdHouseTier.values().length * 3;
	private static final Duration READY_AFTER = Duration.ofMinutes(50);
	private static final Set<Integer> FOSSIL_ISLAND_REGIONS = Set.of(
		14650,
		14651,
		14652,
		14906,
		14907,
		15162,
		15163);

	private final Map<BirdHouseSpace, StoredObservation> observations =
		new EnumMap<>(BirdHouseSpace.class);
	private int[] initialCandidate;

	Optional<BirdHouseSnapshot> observe(
		int regionId,
		int plane,
		int[] varps,
		Instant observedAt)
	{
		if (!FOSSIL_ISLAND_REGIONS.contains(regionId) || plane != 0)
		{
			return Optional.empty();
		}
		if (varps == null || varps.length != BirdHouseSpace.values().length)
		{
			throw new IllegalArgumentException("Expected four bird house varps");
		}
		for (int varp : varps)
		{
			if (varp < 0 || varp > MAX_VARP)
			{
				return Optional.empty();
			}
		}
		if (observations.isEmpty())
		{
			if (!Arrays.equals(initialCandidate, varps))
			{
				initialCandidate = varps.clone();
				return Optional.empty();
			}
			initialCandidate = null;
		}

		int removalCount = 0;
		for (int index = 0; index < varps.length; index++)
		{
			StoredObservation previous = observations.get(BirdHouseSpace.values()[index]);
			if (previous != null && previous.varp > 0 && varps[index] == 0)
			{
				removalCount++;
			}
		}
		if (removalCount > 2)
		{
			return Optional.empty();
		}

		boolean changed = observations.isEmpty();
		Map<BirdHouseSpace, StoredObservation> next =
			new EnumMap<>(BirdHouseSpace.class);
		List<BirdHouseObservation> semantic = new ArrayList<>();
		for (int index = 0; index < varps.length; index++)
		{
			BirdHouseSpace space = BirdHouseSpace.values()[index];
			int varp = varps[index];
			BirdHouseState state = BirdHouseState.fromVarp(varp);
			BirdHouseTier tier = varp == 0 ? null : BirdHouseTier.fromVarp(varp);
			StoredObservation previous = observations.get(space);
			Instant startedAt = null;
			if (state == BirdHouseState.SEEDED)
			{
				if (previous != null
					&& previous.state == BirdHouseState.SEEDED
					&& previous.tier == tier)
				{
					startedAt = previous.startedAt;
				}
				else if (previous != null)
				{
					startedAt = observedAt;
				}
			}
			StoredObservation current = new StoredObservation(
				varp,
				state,
				tier,
				startedAt);
			next.put(space, current);
			changed = changed || !current.sameSemanticValue(previous);
			semantic.add(new BirdHouseObservation(
				space,
				state,
				tier,
				startedAt,
				startedAt == null ? null : startedAt.plus(READY_AFTER)));
		}

		observations.clear();
		observations.putAll(next);
		return changed
			? Optional.of(new BirdHouseSnapshot(observedAt, semantic))
			: Optional.empty();
	}

	void reset()
	{
		observations.clear();
		initialCandidate = null;
	}

	private static final class StoredObservation
	{
		private final int varp;
		private final BirdHouseState state;
		private final BirdHouseTier tier;
		private final Instant startedAt;

		private StoredObservation(
			int varp,
			BirdHouseState state,
			BirdHouseTier tier,
			Instant startedAt)
		{
			this.varp = varp;
			this.state = state;
			this.tier = tier;
			this.startedAt = startedAt;
		}

		private boolean sameSemanticValue(StoredObservation other)
		{
			return other != null
				&& state == other.state
				&& tier == other.tier
				&& java.util.Objects.equals(startedAt, other.startedAt);
		}
	}
}

package com.runeglass.runelite;

import net.runelite.api.gameval.VarPlayerID;

enum BirdHouseSpace
{
	MEADOW_NORTH("meadow_north", VarPlayerID.BIRDHOUSE_TRANSMIT_A),
	MEADOW_SOUTH("meadow_south", VarPlayerID.BIRDHOUSE_TRANSMIT_B),
	VALLEY_NORTH("valley_north", VarPlayerID.BIRDHOUSE_TRANSMIT_C),
	VALLEY_SOUTH("valley_south", VarPlayerID.BIRDHOUSE_TRANSMIT_D);

	private final String wireValue;
	private final int varpId;

	BirdHouseSpace(String wireValue, int varpId)
	{
		this.wireValue = wireValue;
		this.varpId = varpId;
	}

	String wireValue()
	{
		return wireValue;
	}

	int getVarpId()
	{
		return varpId;
	}
}

package com.runeglass.runelite;

enum BirdHouseState
{
	EMPTY("empty"),
	BUILT("built"),
	SEEDED("seeded");

	private final String wireValue;

	BirdHouseState(String wireValue)
	{
		this.wireValue = wireValue;
	}

	String wireValue()
	{
		return wireValue;
	}

	static BirdHouseState fromVarp(int varp)
	{
		if (varp == 0)
		{
			return EMPTY;
		}
		return varp % 3 == 0 ? SEEDED : BUILT;
	}
}

package com.runeglass.runelite;

enum BirdHouseTier
{
	NORMAL("normal"),
	OAK("oak"),
	WILLOW("willow"),
	TEAK("teak"),
	MAPLE("maple"),
	MAHOGANY("mahogany"),
	YEW("yew"),
	MAGIC("magic"),
	REDWOOD("redwood");

	private final String wireValue;

	BirdHouseTier(String wireValue)
	{
		this.wireValue = wireValue;
	}

	String wireValue()
	{
		return wireValue;
	}

	static BirdHouseTier fromVarp(int varp)
	{
		return values()[(varp - 1) / 3];
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import java.util.Objects;
import java.util.Optional;
import java.util.regex.Pattern;
import net.runelite.client.util.Filepath;

final class ConnectionStateStore
{
	static final String FILE_NAME = "connection-state-v1.json";
	static final String TEMP_PREFIX = "connection-state-v1.";
	static final String LEGACY_CONFIG_KEY = "connectionStateV1";

	private static final int FORMAT_VERSION = 1;
	private static final int MAX_FILE_BYTES = 1_024;
	private static final Pattern CONNECTION_ID = Pattern.compile("^pcn_[A-Za-z0-9_-]{43}$");
	private static final Pattern CREDENTIAL = Pattern.compile("^[A-Za-z0-9_-]{43}$");
	private static final Pattern SEQUENCE = Pattern.compile("^[1-9][0-9]{0,19}$");

	static final class State
	{
		private final PairingClient.Credentials credentials;
		private final BigInteger nextSequence;

		private State(
			PairingClient.Credentials credentials,
			BigInteger nextSequence)
		{
			this.credentials = credentials;
			this.nextSequence = nextSequence;
		}

		PairingClient.Credentials getCredentials()
		{
			return credentials;
		}

		BigInteger getNextSequence()
		{
			return nextSequence;
		}
	}

	private static final class StoredState
	{
		private final int version = FORMAT_VERSION;
		private final String connectionId;
		private final String credential;
		private final String nextSequence;

		private StoredState(
			PairingClient.Credentials credentials,
			BigInteger nextSequence)
		{
			this.connectionId = credentials.getConnectionId();
			this.credential = credentials.getRawCredential();
			this.nextSequence = nextSequence.toString();
		}
	}

	private final Filepath directory;
	private final Filepath stateFile;
	private final Gson gson;

	ConnectionStateStore(Filepath profilesDirectory, String profileKey, Gson gson)
	{
		Objects.requireNonNull(profilesDirectory, "profilesDirectory");
		Objects.requireNonNull(profileKey, "profileKey");
		if (profileKey.isEmpty())
		{
			throw new IllegalArgumentException("RuneLite profile key is required");
		}
		this.directory = profilesDirectory.joinSegment(hashProfileKey(profileKey));
		this.stateFile = directory.joinSegment(FILE_NAME);
		this.gson = Objects.requireNonNull(gson, "gson");
	}

	Optional<State> load()
	{
		try
		{
			PrivateFiles.deleteTemporaryFiles(directory, TEMP_PREFIX);
			if (!stateFile.exists() || stateFile.size() > MAX_FILE_BYTES)
			{
				return Optional.empty();
			}
			JsonObject body = new JsonParser().parse(PrivateFiles.readUtf8(stateFile)).getAsJsonObject();
			if (!ProtocolJson.hasExactKeys(
				body,
				"version",
				"connectionId",
				"credential",
				"nextSequence")
				|| ProtocolJson.intValue(body, "version") != FORMAT_VERSION)
			{
				throw new IllegalArgumentException("Unsupported RuneGlass connection state");
			}
			String connectionId = ProtocolJson.stringValue(body, "connectionId");
			String credential = ProtocolJson.stringValue(body, "credential");
			String nextSequence = ProtocolJson.stringValue(body, "nextSequence");
			validate(connectionId, credential, nextSequence);
			return Optional.of(new State(
				new PairingClient.Credentials(connectionId, credential),
				new BigInteger(nextSequence)));
		}
		catch (IOException | RuntimeException exception)
		{
			clear();
			return Optional.empty();
		}
	}

	boolean save(PairingClient.Credentials credentials, BigInteger nextSequence)
	{
		Objects.requireNonNull(credentials, "credentials");
		Objects.requireNonNull(nextSequence, "nextSequence");
		validate(
			credentials.getConnectionId(),
			credentials.getRawCredential(),
			nextSequence.toString());
		byte[] serialized = gson.toJson(new StoredState(credentials, nextSequence))
			.getBytes(StandardCharsets.UTF_8);
		if (serialized.length > MAX_FILE_BYTES)
		{
			return false;
		}
		try
		{
			PrivateFiles.createDirectory(directory);
			PrivateFiles.write(stateFile, TEMP_PREFIX, serialized);
			return true;
		}
		catch (IOException | RuntimeException exception)
		{
			return false;
		}
	}

	boolean clear()
	{
		try
		{
			PrivateFiles.deleteTemporaryFiles(directory, TEMP_PREFIX);
			stateFile.deleteIfExists();
			directory.deleteIfExists();
			return true;
		}
		catch (IOException | RuntimeException exception)
		{
			return false;
		}
	}

	Filepath getStateFile()
	{
		return stateFile;
	}

	private static void validate(String connectionId, String credential, String nextSequence)
	{
		if (!CONNECTION_ID.matcher(connectionId).matches()
			|| !CREDENTIAL.matcher(credential).matches()
			|| !SEQUENCE.matcher(nextSequence).matches())
		{
			throw new IllegalArgumentException("Invalid RuneGlass connection state");
		}
	}

	private static String hashProfileKey(String profileKey)
	{
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] hash = digest.digest(
				("runeglass-profile-state-v1:" + profileKey).getBytes(StandardCharsets.UTF_8));
			return Base64.getUrlEncoder().withoutPadding().encodeToString(hash);
		}
		catch (NoSuchAlgorithmException exception)
		{
			throw new IllegalStateException("SHA-256 is unavailable", exception);
		}
	}
}

package com.runeglass.runelite;

import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.ArrayList;
import java.lang.ref.WeakReference;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.UUID;
import java.util.function.IntFunction;
import java.util.function.IntToLongFunction;

import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

final class DropCapture
{
	static final Set<String> EVENTS = DropPolicy.REWARD_EVENTS;
	private final List<WeakReference<LootReceived>> observed = new ArrayList<>();

	DropCaptureResult capture(LootReceived loot, ItemManager itemManager, UUID sessionId, Instant now)
	{
		return capture(loot, itemManager::getItemComposition, id -> itemManager.getItemPriceWithSource(id, true), sessionId, now);
	}

	DropCaptureResult capture(LootReceived loot, IntFunction<ItemComposition> definitions,
		IntToLongFunction prices, UUID sessionId, Instant now)
	{
		if (loot.getMetadata() instanceof java.util.Collection)
		{
			return DropCaptureResult.filtered(DropCaptureResult.Reason.PLUGIN_INJECTION, null);
		}
		String sourceType;
		if (loot.getType() == LootRecordType.NPC) sourceType = "npc";
		else if (loot.getType() == LootRecordType.PICKPOCKET) sourceType = "pickpocket";
		else if (loot.getType() == LootRecordType.EVENT && EVENTS.contains(loot.getName())) sourceType = "event";
		else return DropCaptureResult.filtered(DropCaptureResult.Reason.UNSUPPORTED_SOURCE, null);
		if (!DropEvent.saneLabel(loot.getName()) || loot.getAmount() < 1 || loot.getAmount() > 10_000)
		{
			throw new IllegalArgumentException("Unsupported reward shape");
		}
		observed.removeIf(reference -> reference.get() == null);
		if (observed.stream().anyMatch(reference -> reference.get() == loot))
		{
			return DropCaptureResult.filtered(DropCaptureResult.Reason.ALREADY_HANDLED, sourceType);
		}
		if (observed.size() == 1_024) observed.remove(0);
		observed.add(new WeakReference<>(loot));
		Map<Integer, Integer> quantities = new TreeMap<>();
		for (ItemStack stack : loot.getItems())
		{
			if (stack.getId() <= 0 || stack.getQuantity() <= 0)
			{
				throw new IllegalArgumentException("Invalid reward quantity");
			}
			quantities.merge(stack.getId(), stack.getQuantity(), Math::addExact);
		}
		if (quantities.isEmpty()) return DropCaptureResult.filtered(DropCaptureResult.Reason.NO_ITEMS, sourceType);
		if (quantities.size() > 64) throw new IllegalArgumentException("Too many reward items");
		List<JsonObject> items = new ArrayList<>();
		long total = 0;
		boolean retained = false;
		boolean notable = false;
		int valuedStacks = 0;
		Long highestStackGp = null;
		for (Map.Entry<Integer, Integer> stack : quantities.entrySet())
		{
			int itemId = stack.getKey();
			ItemComposition composition = definitions.apply(itemId);
			if (composition == null || !DropEvent.saneLabel(composition.getMembersName()))
			{
				throw new IllegalArgumentException("Unavailable reward definition");
			}
			ItemComposition valuationComposition = composition;
			if (composition.getNote() != -1 && composition.getLinkedNoteId() > 0)
			{
				valuationComposition = definitions.apply(composition.getLinkedNoteId());
			}
			JsonObject value = new JsonObject();
			int marketItemId = 0;
			Long capturedStackGp = null;
			if (itemId == 995)
			{
				value.addProperty("kind", "coins");
				capturedStackGp = (long) stack.getValue();
			}
			else if (valuationComposition == null || valuationComposition.getId() <= 0 || valuationComposition.getId() == 995)
			{
				value.addProperty("kind", "unknown");
			}
			else if (!valuationComposition.isTradeable()) value.addProperty("kind", "untradeable");
			else
			{
				marketItemId = valuationComposition.getId();
				long price = prices.applyAsLong(marketItemId);
				if (price > Integer.MAX_VALUE) price = 0;
				value.addProperty("kind", price > 0 ? "ge" : "unknown");
				if (price > 0)
				{
					value.addProperty("unitPrice", price);
					capturedStackGp = price * stack.getValue();
				}
			}
			if (capturedStackGp != null)
			{
				total += capturedStackGp;
				valuedStacks++;
				highestStackGp = highestStackGp == null ? capturedStackGp : Math.max(highestStackGp, capturedStackGp);
			}
			if (total > 9_007_199_254_740_991L) throw new IllegalArgumentException("Reward value overflow");
			JsonObject item = new JsonObject();
			item.addProperty("itemId", itemId);
			if (marketItemId > 0) item.addProperty("marketItemId", marketItemId);
			item.addProperty("itemName", composition.getMembersName());
			item.addProperty("quantity", stack.getValue());
			item.add("value", value);
			items.add(item);
			retained |= DropPolicy.qualifies(sourceType, loot.getName(), itemId, capturedStackGp);
			notable |= DropPolicy.isNotableReward(sourceType, loot.getName(), itemId);
		}
		return DropCaptureResult.observed(sourceType, items.size(), valuedStacks, highestStackGp, notable,
			new DropEvent(UUID.randomUUID(), sessionId, now, sourceType, loot.getName(), loot.getAmount(), items,
				loot.getMetadata() instanceof net.runelite.api.NPCComposition ? ((net.runelite.api.NPCComposition) loot.getMetadata()).getId() : null), retained);
	}
}

package com.runeglass.runelite;

import java.util.Optional;

final class DropCaptureResult
{
	enum Stage
	{
		BLOCKED,
		FILTERED,
		INVALID,
		ELIGIBLE,
		SUBMITTED,
		NOT_SUBMITTED
	}

	enum Reason
	{
		PLUGIN_STOPPED(Stage.BLOCKED),
		SYNC_OFF(Stage.BLOCKED),
		DROP_SYNC_OFF(Stage.BLOCKED),
		LOOT_TRACKER_OFF(Stage.BLOCKED),
		LOGGED_OUT(Stage.BLOCKED),
		SESSION_INACTIVE(Stage.BLOCKED),
		BASELINE_PENDING(Stage.BLOCKED),
		PROFILE_CHANGED(Stage.BLOCKED),
		NOT_PAIRED(Stage.BLOCKED),
		UNSUPPORTED_PROFILE(Stage.BLOCKED),
		TRANSPORT_NOT_READY(Stage.BLOCKED),
		PLUGIN_INJECTION(Stage.FILTERED),
		UNSUPPORTED_SOURCE(Stage.FILTERED),
		ALREADY_HANDLED(Stage.FILTERED),
		NO_ITEMS(Stage.FILTERED),
		BELOW_THRESHOLD(Stage.FILTERED),
		INVALID_REWARD(Stage.INVALID),
		ELIGIBLE(Stage.ELIGIBLE),
		SUBMITTED_FOR_LOCAL_SAVE(Stage.SUBMITTED),
		LOCAL_SAVE_UNAVAILABLE(Stage.NOT_SUBMITTED);

		private final Stage stage;

		Reason(Stage stage)
		{
			this.stage = stage;
		}

		Stage stage()
		{
			return stage;
		}
	}

	private final Reason reason;
	private final String sourceType;
	private final int itemStacks;
	private final int valuedStacks;
	private final Long highestStackGp;
	private final boolean notable;
	private final DropEvent event;
	private final DropEvent observation;

	private DropCaptureResult(Reason reason, String sourceType, int itemStacks, int valuedStacks,
		Long highestStackGp, boolean notable, DropEvent event)
	{
		this(reason, sourceType, itemStacks, valuedStacks, highestStackGp, notable, event, event);
	}

	private DropCaptureResult(Reason reason, String sourceType, int itemStacks, int valuedStacks,
		Long highestStackGp, boolean notable, DropEvent event, DropEvent observation)
	{
		this.observation = observation;
		this.reason = reason;
		this.sourceType = sourceType;
		this.itemStacks = itemStacks;
		this.valuedStacks = valuedStacks;
		this.highestStackGp = highestStackGp;
		this.notable = notable;
		this.event = event;
	}

	static DropCaptureResult blocked(Reason reason)
	{
		if (reason.stage() != Stage.BLOCKED) throw new IllegalArgumentException("Not a guard reason");
		return new DropCaptureResult(reason, null, 0, 0, null, false, null);
	}

	static DropCaptureResult filtered(Reason reason, String sourceType)
	{
		if (reason.stage() != Stage.FILTERED) throw new IllegalArgumentException("Not a filter reason");
		return new DropCaptureResult(reason, sourceType, 0, 0, null, false, null);
	}

	static DropCaptureResult invalid()
	{
		return new DropCaptureResult(Reason.INVALID_REWARD, null, 0, 0, null, false, null);
	}

	static DropCaptureResult evaluated(String sourceType, int itemStacks, int valuedStacks,
		Long highestStackGp, boolean notable, DropEvent event)
	{
		return new DropCaptureResult(event == null ? Reason.BELOW_THRESHOLD : Reason.ELIGIBLE,
			sourceType, itemStacks, valuedStacks, highestStackGp, notable, event);
	}

	static DropCaptureResult observed(String sourceType, int itemStacks, int valuedStacks,
		Long highestStackGp, boolean notable, DropEvent observation, boolean retained)
	{
		return new DropCaptureResult(retained ? Reason.ELIGIBLE : Reason.BELOW_THRESHOLD,
			sourceType, itemStacks, valuedStacks, highestStackGp, notable, retained ? observation : null, observation);
	}

	Optional<DropEvent> observation() { return Optional.ofNullable(observation); }

	DropCaptureResult submitted(boolean accepted)
	{
		if (event == null) throw new IllegalStateException("No eligible drop");
		return new DropCaptureResult(accepted ? Reason.SUBMITTED_FOR_LOCAL_SAVE : Reason.LOCAL_SAVE_UNAVAILABLE,
			sourceType, itemStacks, valuedStacks, highestStackGp, notable, event);
	}

	Reason reason()
	{
		return reason;
	}

	Stage stage()
	{
		return reason.stage();
	}

	Optional<String> sourceType()
	{
		return Optional.ofNullable(sourceType);
	}

	int itemStacks()
	{
		return itemStacks;
	}

	int valuedStacks()
	{
		return valuedStacks;
	}

	Optional<Long> highestStackGp()
	{
		return Optional.ofNullable(highestStackGp);
	}

	boolean notable()
	{
		return notable;
	}

	Optional<DropEvent> event()
	{
		return Optional.ofNullable(event);
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.util.Filepath;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

final class DropClient
{
	interface Listener
	{
		void onStatus(String status);
		void onInvalidConnection(PairingClient.Credentials credentials, boolean bindingMismatch);
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final HttpUrl endpoint;
	private final Filepath root;
	private final Listener listener;
	private final ArrayDeque<Runnable> work = new ArrayDeque<>();
	private final AtomicInteger capturesWaiting = new AtomicInteger();
	private boolean running;
	private volatile boolean purgeFailed;
	private volatile boolean countCleanupFailed;
	private final Set<State> pendingStates = java.util.Collections.newSetFromMap(new java.util.concurrent.ConcurrentHashMap<>());
	private volatile State active;

	static DropClient create(OkHttpClient http, Gson gson, ScheduledExecutorService executor, Filepath root, Listener listener)
	{
		return new DropClient(http, gson, executor,
			Objects.requireNonNull(HttpUrl.parse(PairingClient.BASE_URL)).resolve("runelite/v1/drops"), root, listener);
	}

	DropClient(OkHttpClient http, Gson gson, ScheduledExecutorService executor, HttpUrl endpoint, Filepath root, Listener listener)
	{
		this.http = http;
		this.gson = gson;
		this.executor = executor;
		this.endpoint = endpoint;
		this.root = root;
		this.listener = listener;
	}

	void connect(PairingClient.Credentials credentials, SyncContext context)
	{
		connect(credentials, context, credentials.getConnectionId(), false);
	}

	void connect(PairingClient.Credentials credentials, SyncContext context, String profileKey, boolean shareCounts)
	{
		if (!shareCounts) revokeCountSharing();
		pause();
		State state = new State(credentials, context);
		state.shareCounts = shareCounts;
		pendingStates.add(state);
		active = state;
		submit(() ->
		{
			if (state.revoked) return;
			if (DurableDropQueue.discardMarker(root).exists()) purge(root);
			if (DurableDropQueue.discardMarker(root.joinSegment(credentials.getConnectionId())).exists())
			{
				purge(root.joinSegment(credentials.getConnectionId()));
			}
			if (DurableDropQueue.countRevocationMarker(root).exists()) stripCountEvidence();
			if (countCleanupFailed) return;
			if (purgeFailed)
			{
				status(state, "Drops paused: local deletion failed. Turn drop sync off to retry deletion.");
				return;
			}
			if (!"standard".equals(context.getProfileType()))
			{
				status(state, "Drops paused: only standard-profile worlds are supported.");
				return;
			}
			try
			{
				state.queue = new DurableDropQueue(root, credentials.getConnectionId(), gson);
				if (state.shareCounts)
				{
					state.continuity = new DropContinuityStore(root.joinSegment(credentials.getConnectionId()), gson, profileKey);
					if (state.continuity.damaged()) state.missed = true;
				}
				status(state, queueStatus(state));
				dispatch(state);
			}
			catch (IOException | RuntimeException exception)
			{
				state.paused = true;
				status(state, "Drops paused: local storage could not be opened. No new drops are saved.");
			}
		});
	}

	boolean isConnected()
	{
		State state = active;
		return state != null && !state.revoked && !state.paused && !purgeFailed && !countCleanupFailed && "standard".equals(state.context.getProfileType());
	}

	void captureFailed()
	{
		State state = active;
		if (state == null) return;
		state.missed = true;
		submit(() -> invalidateContinuity(state));
		status(state, "A drop could not be captured safely. Previously saved drops remain queued.");
	}

	boolean publish(DropEvent event)
	{
		return save(event, true, null);
	}

	boolean observe(DropCorrelator.Completed completed)
	{
		return save(completed.result.observation().get(), completed.result.event().isPresent(), completed);
	}

	private boolean save(DropEvent event, boolean retained, DropCorrelator.Completed completed)
	{
		State state = active;
		if (state == null || state.revoked || state.paused || !"standard".equals(state.context.getProfileType())) return false;
		if (capturesWaiting.incrementAndGet() > 256)
		{
			capturesWaiting.decrementAndGet();
			state.missed = true;
			submit(() -> invalidateContinuity(state));
			status(state, "Drop not saved: local storage is busy. Previously saved drops remain queued.");
			return false;
		}
		if (submit(() ->
		{
			try
			{
				if (state.revoked || purgeFailed || countCleanupFailed || state.paused) return;
				if (state.queue == null) throw new IOException("Queue unavailable");
				DropEvent frozen = state.shareCounts ? event : event.withoutCountEvidence();
				boolean counterObserved = state.shareCounts && completed != null && (completed.count != null || DropCounterRegistry.COUNTERS.stream()
					.anyMatch(counter -> counter.matches(event.sourceType(), event.sourceName())));
				if (state.shareCounts && completed != null)
				{
					JsonObject evidence = null;
					if (completed.count == null) state.continuity.invalidate(event.sourceType(), event.sourceName());
					else evidence = state.continuity.observe(completed.count);
					frozen = event.freeze(completed.count, evidence, completed.collectionLog, completed.newSlots);
				}
				if (retained) state.queue.append(frozen.envelope(state.context, state.credentials.getConnectionId()));
				if (counterObserved) state.continuity.save();
				status(state, queueStatus(state));
				dispatch(state);
			}
			catch (DurableDropQueue.CapacityException exception)
			{
				invalidateContinuity(state);
				state.missed = true;
				status(state, "Drop not saved: local queue is full (5 MiB / 10,000 events). Existing drops remain queued.");
				dispatch(state);
			}
			catch (IOException | RuntimeException exception)
			{
				invalidateContinuity(state);
				state.missed = true;
				state.paused = true;
				status(state, "Drops paused: local persistence failed. New drops cannot be saved; previously saved drops remain queued.");
			}
			finally { capturesWaiting.decrementAndGet(); }
		})) return true;
		capturesWaiting.decrementAndGet();
		return false;
	}

	private void invalidateContinuity(State state)
	{
		if (state.revoked || !state.shareCounts || state.continuity == null) return;
		state.continuity.invalidateAll();
		try { state.continuity.save(); }
		catch (IOException | RuntimeException exception) { state.paused = true; }
	}

	void pause()
	{
		State previous = active;
		active = null;
		if (previous != null)
		{
			cancel(previous);
			listener.onStatus("Drop sync paused. Saved pending drops remain on disk for this connection.");
			submit(() -> pendingStates.remove(previous));
		}
	}

	void revokeCountSharing()
	{
		pendingStates.forEach(state -> state.shareCounts = false);
		pause();
		submit(this::stripCountEvidence);
	}

	private void stripCountEvidence()
	{
		try
		{
			DurableDropQueue.stripCountEvidence(root, gson);
			pendingStates.forEach(state -> state.continuity = null);
			countCleanupFailed = false;
		}
		catch (IOException | RuntimeException exception)
		{
			countCleanupFailed = true;
			listener.onStatus("Drops stopped: count evidence could not be removed locally. Turn count sharing off to retry cleanup; uploads are blocked.");
		}
	}

	void discardAll()
	{
		pendingStates.forEach(state -> state.revoked = true);
		pause();
		submit(() -> purge(root));
	}

	void discardConnection(String connectionId)
	{
		pendingStates.stream().filter(state -> state.credentials.getConnectionId().equals(connectionId))
			.forEach(state -> state.revoked = true);
		State previous = active;
		if (previous != null && previous.credentials.getConnectionId().equals(connectionId))
		{
			previous.revoked = true;
			pause();
		}
		if (connectionId.matches("[A-Za-z0-9_-]{1,128}")) submit(() -> purge(root.joinSegment(connectionId)));
	}

	private void purge(Filepath path)
	{
		try
		{
			if (path.exists() || DurableDropQueue.discardMarker(path).exists())
			{
				DurableDropQueue.markDiscard(path);
				DurableDropQueue.purge(path);
				DurableDropQueue.discardMarker(path).deleteIfExists();
			}
			if (path.equals(root))
			{
				DurableDropQueue.countRevocationMarker(root).deleteIfExists();
				countCleanupFailed = false;
			}
			purgeFailed = DurableDropQueue.discardMarker(root).exists();
			if (active == null) listener.onStatus("Drop sync is off. Pending drops have been removed; synced history remains until deletion.");
		}
		catch (IOException | RuntimeException exception)
		{
			purgeFailed = true;
			listener.onStatus("Drops stopped: local deletion failed. Pending files remain on disk; uploads are blocked.");
		}
	}

	private void dispatch(State state)
	{
		if (!current(state) || purgeFailed || countCleanupFailed || state.queue == null || state.paused || state.call != null || state.retry != null) return;
		List<DurableDropQueue.Entry> batch = state.queue.batch(state.individual);
		if (batch.isEmpty()) return;
		Call call = http.newCall(new Request.Builder().url(endpoint)
			.header("Accept", "application/json")
			.header("Authorization", "Bearer " + state.credentials.getRawCredential())
			.post(RequestBody.create(MediaType.parse("application/json; charset=utf-8"), gson.toJson(DurableDropQueue.payload(batch))))
			.build());
		state.call = call;
		if (!current(state)) { call.cancel(); return; }
		try
		{
			call.enqueue(new Callback()
			{
				@Override public void onFailure(Call ignored, IOException exception)
				{
					submit(() -> retry(state, null));
				}
				@Override public void onResponse(Call ignored, Response response)
				{
					try (Response closed = response)
					{
						int code = closed.code();
						String retryAfter = closed.header("Retry-After");
						JsonObject body = code == 429 || code >= 500 ? null : ProtocolJson.readObject(closed, 8 * 1_024);
						submit(() -> response(state, batch, code, body, retryAfter));
					}
					catch (IOException | RuntimeException exception)
					{
						submit(() -> retry(state, null));
					}
				}
			});
		}
		catch (RuntimeException exception) { retry(state, null); }
	}

	private void response(State state, List<DurableDropQueue.Entry> batch, int code, JsonObject body, String retryAfter)
	{
		if (!current(state)) return;
		state.call = null;
		if (code == 429 || code >= 500) { retry(state, retryAfter); return; }
		try
		{
			if (code == 200)
			{
				if (!ProtocolJson.hasExactKeys(body, "protocolVersion", "status", "acceptedEventIds", "serverTime", "nextUploadAfterSeconds")
					|| ProtocolJson.intValue(body, "protocolVersion") != 1
					|| !Set.of("accepted", "duplicate").contains(ProtocolJson.stringValue(body, "status"))) throw new IOException("Invalid acknowledgement");
				Instant.parse(ProtocolJson.stringValue(body, "serverTime"));
				int delay = ProtocolJson.intValue(body, "nextUploadAfterSeconds");
				if (delay < 1 || delay > 3_600) throw new IOException("Invalid interval");
				Set<String> expected = new HashSet<>();
				batch.forEach(entry -> expected.add(entry.id()));
				Set<String> accepted = new HashSet<>();
				for (JsonElement id : body.getAsJsonArray("acceptedEventIds"))
				{
					if (!id.isJsonPrimitive() || !id.getAsJsonPrimitive().isString()
						|| !expected.contains(id.getAsString()) || !accepted.add(id.getAsString())) throw new IOException("Unmatched acknowledgement");
				}
				if (accepted.isEmpty()) throw new IOException("Empty acknowledgement");
				state.queue.acknowledge(batch, accepted);
				state.attempt = 0;
				status(state, queueStatus(state));
				schedule(state, delay * 1_000L);
				return;
			}
			if (!ProtocolJson.hasExactKeys(body, "protocolVersion", "error")
				|| ProtocolJson.intValue(body, "protocolVersion") != 1) throw new IOException("Invalid error");
			String error = ProtocolJson.stringValue(body, "error");
			if ((code == 401 && "invalid_connection_credential".equals(error))
				|| (code == 403 && Set.of("binding_mismatch", "scope_denied").contains(error)))
			{
				if (code == 401)
				{
					discardConnection(state.credentials.getConnectionId());
					listener.onInvalidConnection(state.credentials, false);
				}
				else
				{
					state.paused = true;
					status(state, "Drops paused: character binding or consent does not match. Saved pending drops are retained.");
				}
				return;
			}
			if (code == 422 && "unsupported_profile".equals(error))
			{
				state.paused = true;
				status(state, "Drops paused: unsupported profile. Saved pending drops are retained.");
				return;
			}
			if ((code == 400 && "invalid_payload".equals(error)) || (code == 409 && "event_conflict".equals(error)))
			{
				if (batch.size() == 1) state.queue.block(batch.get(0));
				state.individual = true;
				status(state, "Drops need attention: rejected records remain locally; other saved drops continue syncing.");
				schedule(state, 5_000);
				return;
			}
			throw new IOException("Unexpected response");
		}
		catch (IOException | RuntimeException exception)
		{
			retry(state, null);
		}
	}

	private void retry(State state, String retryAfter)
	{
		if (!current(state)) return;
		state.call = null;
		long seconds = Math.min(300, 5L << Math.min(state.attempt++, 6));
		if (retryAfter != null)
		{
			try { seconds = Math.max(seconds, Math.min(86_400L, Long.parseLong(retryAfter))); }
			catch (NumberFormatException ignored)
			{
				try { seconds = Math.max(seconds, Math.min(86_400L, java.time.Duration.between(Instant.now(),
					java.time.ZonedDateTime.parse(retryAfter, java.time.format.DateTimeFormatter.RFC_1123_DATE_TIME).toInstant()).getSeconds())); }
				catch (RuntimeException invalidDate) { seconds = Math.max(5, seconds); }
			}
		}
		status(state, "Drops waiting to retry. " + queueStatus(state));
		schedule(state, seconds * 1_000L);
	}

	private void schedule(State state, long millis)
	{
		if (!current(state)) return;
		state.retry = executor.schedule(() ->
		{
			submit(() ->
			{
				state.retry = null;
				dispatch(state);
			});
		}, millis, TimeUnit.MILLISECONDS);
	}

	private boolean current(State state) { return active == state && !state.revoked; }
	private void status(State state, String value) { if (current(state)) listener.onStatus(value); }
	private String queueStatus(State state)
	{
		return (state.queue.size() == 0 ? "Drop tracking ready. No saved events waiting to sync."
			: state.queue.size() + " drop events saved locally, waiting to sync.")
			+ (state.queue.hasDamagedRecords() ? " Some local records need attention and have not been uploaded." : "")
			+ (state.missed ? " Some drops in this session could not be saved." : "");
	}

	private static void cancel(State state)
	{
		Call call = state.call;
		if (call != null) call.cancel();
		ScheduledFuture<?> retry = state.retry;
		if (retry != null) retry.cancel(false);
	}

	private boolean submit(Runnable task)
	{
		synchronized (work)
		{
			work.add(task);
			if (running) return true;
			running = true;
			try { executor.execute(this::drain); return true; }
			catch (RuntimeException exception)
			{
				work.clear();
				running = false;
				listener.onStatus("Drops stopped: background storage is unavailable. New drops cannot be saved.");
				return false;
			}
		}
	}

	private void drain()
	{
		while (true)
		{
			Runnable task;
			synchronized (work)
			{
				task = work.poll();
				if (task == null) { running = false; return; }
			}
			try { task.run(); }
			catch (RuntimeException exception)
			{
				listener.onStatus("Drops paused: background processing failed. Existing saved records are retained.");
			}
		}
	}

	private static final class State
	{
		final PairingClient.Credentials credentials;
		final SyncContext context;
		volatile boolean revoked;
		volatile boolean shareCounts;
		volatile boolean missed;
		volatile Call call;
		volatile ScheduledFuture<?> retry;
		DurableDropQueue queue;
		DropContinuityStore continuity;
		boolean individual;
		volatile boolean paused;
		int attempt;
		State(PairingClient.Credentials credentials, SyncContext context) { this.credentials = credentials; this.context = context; }
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.UUID;
import net.runelite.client.util.Filepath;

final class DropContinuityStore
{
	static final String FILE = "continuity-v1.json";
	private final Filepath file;
	private final Gson gson;
	private final String profileKey;
	private JsonObject counters = new JsonObject();
	private boolean damaged;

	DropContinuityStore(Filepath directory, Gson gson, String profileKey) throws IOException
	{
		this.file = directory.joinSegment(FILE);
		this.gson = gson;
		this.profileKey = profileKey;
		if (profileKey == null || profileKey.isEmpty() || profileKey.length() > 256) throw new IOException("Invalid continuity scope");
		PrivateFiles.createDirectory(directory);
		if (!file.exists()) return;
		try
		{
			if (file.size() > 64 * 1024) throw new IOException("Oversized continuity");
			JsonObject body = gson.fromJson(PrivateFiles.readUtf8(file), JsonObject.class);
			if (!ProtocolJson.hasExactKeys(body, "version", "profile", "counters")
				|| ProtocolJson.intValue(body, "version") != 1) throw new IOException("Invalid continuity");
			if (!profileKey.equals(ProtocolJson.stringValue(body, "profile"))) return;
			JsonObject restored = body.getAsJsonObject("counters");
			if (restored.size() > DropCounterRegistry.COUNTERS.size()) throw new IOException("Too many counters");
			for (java.util.Map.Entry<String, JsonElement> entry : restored.entrySet())
			{
				JsonObject state = entry.getValue().getAsJsonObject();
				if (DropCounterRegistry.byKey(entry.getKey()) == null || !ProtocolJson.hasExactKeys(state, "id", "from", "last")
					|| !ProtocolJson.stringValue(state, "id").matches("[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}")
					|| ProtocolJson.intValue(state, "from") < 1 || ProtocolJson.intValue(state, "last") < ProtocolJson.intValue(state, "from"))
					throw new IOException("Invalid continuity state");
			}
			counters = restored;
		}
		catch (IOException | RuntimeException exception)
		{
			damaged = true;
			counters = new JsonObject();
		}
	}

	JsonObject observe(DropCountParser.Count count)
	{
		JsonObject previous = counters.getAsJsonObject(count.counter.key);
		int last = previous == null ? 0 : ProtocolJson.intValue(previous, "last");
		boolean reset = previous == null || count.value <= last;
		JsonObject next = new JsonObject();
		next.addProperty("id", reset ? UUID.randomUUID().toString() : ProtocolJson.stringValue(previous, "id"));
		next.addProperty("from", !reset && (long) last + 1 == count.value ? ProtocolJson.intValue(previous, "from") : count.value);
		next.addProperty("last", count.value);
		counters.add(count.counter.key, next);
		JsonObject evidence = next.deepCopy();
		evidence.remove("last");
		return evidence;
	}

	void invalidate(String type, String name)
	{
		for (DropCounterRegistry.Counter counter : DropCounterRegistry.COUNTERS)
			if (counter.matches(type, name)) counters.remove(counter.key);
	}

	void invalidateAll() { counters = new JsonObject(); }
	boolean damaged() { return damaged; }

	void save() throws IOException
	{
		JsonObject body = new JsonObject();
		body.addProperty("version", 1);
		body.addProperty("profile", profileKey);
		body.add("counters", counters);
		PrivateFiles.write(file, FILE + ".", gson.toJson(body).getBytes(StandardCharsets.UTF_8));
	}
}

package com.runeglass.runelite;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.function.Consumer;

final class DropCorrelator
{
	static final int WINDOW = 5;
	static final int LIMIT = 64;
	static final long ORDINARY_NANOS = 12_000_000_000L;
	static final long RAID_NANOS = 30 * 60_000_000_000L;
	private final List<Pending> drops = new ArrayList<>();
	private final List<CounterMessage> counts = new ArrayList<>();
	private final List<LogMessage> logs = new ArrayList<>();
	private String setting = "unknown";
	private long settingFrom;
	private String encounter;
	private long uncertainUntil = Long.MIN_VALUE;

	void context(long tick, String nextSetting, String nextEncounter)
	{
		if (!Objects.equals(setting, nextSetting))
		{
			setting = nextSetting;
			settingFrom = tick;
			for (Pending drop : drops) drop.setting = "unknown";
		}
		if (!Objects.equals(encounter, nextEncounter))
		{
			counts.removeIf(message -> message.count.counter.raid());
			for (Pending drop : drops) if (drop.encounter != null) drop.countAmbiguous = true;
			encounter = nextEncounter;
		}
	}

	void count(DropCountParser.Count count, long tick, long nanos, String raidEncounter)
	{
		if (count == null || (count.counter.raid() && (raidEncounter == null || !raidEncounter.startsWith(count.counter.raidFamily() + ":")))) return;
		if (counts.stream().anyMatch(m -> m.tick == tick && m.count.value == count.value && m.count.counter.key.equals(count.counter.key))) return;
		if (counts.size() == LIMIT)
		{
			counts.clear();
			uncertainUntil = tick + 2 * WINDOW;
			for (Pending drop : drops) drop.countAmbiguous = true;
		}
		counts.add(new CounterMessage(count, tick, nanos, raidEncounter));
		markAmbiguities();
	}

	void collection(String name, long tick, long nanos)
	{
		if (name == null) return;
		if (logs.stream().anyMatch(m -> m.tick == tick && m.name.equals(name))) return;
		if (logs.size() == LIMIT)
		{
			logs.clear();
			uncertainUntil = tick + 2 * WINDOW;
			for (Pending drop : drops) { drop.logAmbiguous = true; drop.setting = "unknown"; }
		}
		logs.add(new LogMessage(name, tick, nanos));
		markAmbiguities();
	}

	void loot(DropCaptureResult result, long tick, long nanos, String raidEncounter, Consumer<Completed> publish)
	{
		if (!result.observation().isPresent()) return;
		if (drops.size() == LIMIT)
		{
			flush(publish);
			uncertainUntil = tick + 2 * WINDOW;
		}
		Pending drop = new Pending(result, tick, nanos, raidEncounter,
			tick - settingFrom >= WINDOW ? setting : "unknown");
		if (tick <= uncertainUntil) { drop.countAmbiguous = true; drop.logAmbiguous = true; drop.setting = "unknown"; }
		drops.add(drop);
		markAmbiguities();
	}

	void advance(long tick, long nanos, Consumer<Completed> publish)
	{
		markAmbiguities();
		for (Pending drop : new ArrayList<>(drops))
		{
			if (tick - drop.tick > 2 * WINDOW || nanos - drop.nanos > ORDINARY_NANOS)
			{
				publish.accept(tick - drop.tick > 2 * WINDOW ? finish(drop) : new Completed(drop.result, null, "unknown", Set.of()));
				drops.remove(drop);
			}
		}
		counts.removeIf(m -> m.count.counter.raid()
			? nanos - m.nanos > RAID_NANOS
			: tick - m.tick > 3 * WINDOW + 1 || nanos - m.nanos > 2 * ORDINARY_NANOS);
		logs.removeIf(m -> tick - m.tick > 3 * WINDOW + 1 || nanos - m.nanos > 2 * ORDINARY_NANOS);
	}

	void flush(Consumer<Completed> publish)
	{
		for (Pending drop : drops) publish.accept(new Completed(drop.result, null, "unknown", Set.of()));
		clear();
	}

	void clear()
	{
		drops.clear(); counts.clear(); logs.clear(); encounter = null; setting = "unknown"; uncertainUntil = Long.MIN_VALUE;
	}

	private Completed finish(Pending drop)
	{
		List<CounterMessage> candidates = candidates(drop);
		CounterMessage candidate = candidates.size() == 1 ? candidates.get(0) : null;
		DropCountParser.Count count = null;
		if (!drop.countAmbiguous && candidate != null && !candidate.ambiguous && !candidate.consumed)
		{
			candidate.consumed = true;
			count = candidate.count;
		}
		Set<Integer> newSlots = new HashSet<>();
		boolean uncertainLog = drop.logAmbiguous;
		for (LogMessage log : logs)
		{
			if (!matches(drop, log)) continue;
			List<Integer> ids = drop.event().itemIdsNamed(log.name);
			if (!log.ambiguous && !log.consumed && !drop.logAmbiguous && ids.size() == 1)
			{
				newSlots.add(ids.get(0)); log.consumed = true;
			}
			else uncertainLog = true;
		}
		return new Completed(drop.result, count, uncertainLog ? "unknown" : drop.setting, newSlots);
	}

	private void markAmbiguities()
	{
		for (Pending drop : drops)
		{
			List<CounterMessage> matches = candidates(drop);
			if (matches.size() > 1)
			{
				drop.countAmbiguous = true;
				for (CounterMessage message : matches) message.ambiguous = true;
			}
		}
		for (CounterMessage message : counts)
		{
			List<Pending> matches = new ArrayList<>();
			for (Pending drop : drops) if (matches(drop, message)) matches.add(drop);
			if (matches.size() > 1)
			{
				message.ambiguous = true;
				for (Pending drop : matches) drop.countAmbiguous = true;
			}
		}
		for (LogMessage log : logs)
		{
			List<Pending> matches = new ArrayList<>();
			for (Pending drop : drops) if (matches(drop, log)) matches.add(drop);
			if (matches.size() > 1 || logs.stream().anyMatch(other -> other != log && other.name.equals(log.name) && Math.abs(other.tick - log.tick) <= 2 * WINDOW))
			{
				log.ambiguous = true;
				for (Pending drop : matches) { drop.logAmbiguous = true; drop.setting = "unknown"; }
			}
		}
	}

	private List<CounterMessage> candidates(Pending drop)
	{
		List<CounterMessage> matches = new ArrayList<>();
		for (CounterMessage message : counts) if (matches(drop, message)) matches.add(message);
		return matches;
	}

	private boolean matches(Pending drop, CounterMessage message)
	{
		DropEvent event = drop.event();
		if (event.rollCount() != 1 || !message.count.counter.matches(event.sourceType(), event.sourceName())) return false;
		if (message.count.counter.raid()) return drop.encounter != null && drop.encounter.equals(message.encounter)
			&& drop.nanos - message.nanos <= RAID_NANOS && message.tick - drop.tick <= WINDOW
			&& message.nanos - drop.nanos <= ORDINARY_NANOS;
		return Math.abs(drop.tick - message.tick) <= WINDOW && Math.abs(drop.nanos - message.nanos) <= ORDINARY_NANOS;
	}

	private boolean matches(Pending drop, LogMessage log)
	{
		return Math.abs(drop.tick - log.tick) <= WINDOW && Math.abs(drop.nanos - log.nanos) <= ORDINARY_NANOS
			&& !drop.event().itemIdsNamed(log.name).isEmpty();
	}

	static final class Completed
	{
		final DropCaptureResult result;
		final DropCountParser.Count count;
		final String collectionLog;
		final Set<Integer> newSlots;
		Completed(DropCaptureResult result, DropCountParser.Count count, String collectionLog, Set<Integer> newSlots)
		{
			this.result = result; this.count = count; this.collectionLog = collectionLog; this.newSlots = Set.copyOf(newSlots);
		}
	}

	private static final class Pending
	{
		final DropCaptureResult result;
		final long tick;
		final long nanos;
		final String encounter;
		String setting;
		boolean countAmbiguous;
		boolean logAmbiguous;
		Pending(DropCaptureResult result, long tick, long nanos, String encounter, String setting)
		{ this.result = result; this.tick = tick; this.nanos = nanos; this.encounter = encounter; this.setting = setting; }
		DropEvent event() { return result.observation().get(); }
	}
	private static final class CounterMessage
	{
		final DropCountParser.Count count;
		final long tick;
		final long nanos;
		final String encounter;
		boolean ambiguous;
		boolean consumed;
		CounterMessage(DropCountParser.Count count, long tick, long nanos, String encounter)
		{ this.count = count; this.tick = tick; this.nanos = nanos; this.encounter = encounter; }
	}
	private static final class LogMessage
	{
		final String name;
		final long tick;
		final long nanos;
		boolean ambiguous;
		boolean consumed;
		LogMessage(String name, long tick, long nanos) { this.name = name; this.tick = tick; this.nanos = nanos; }
	}
}

package com.runeglass.runelite;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class DropCountParser
{
	private static final String NUMBER = "([0-9]+|[1-9][0-9]{0,2}(?:,[0-9]{3})+)";
	private static final Pattern COUNT = Pattern.compile("^Your (?:(completed|completion count for|subdued) )?(.+?)(?: (kill|completion|chest|harvest|success))? count is:\\s*" + NUMBER + "\\.?$", Pattern.CASE_INSENSITIVE);
	private static final Pattern PREFIX_COUNT = Pattern.compile("^Your completion count for (.+?) is:\\s*" + NUMBER + "\\.?$", Pattern.CASE_INSENSITIVE);
	private static final Pattern CLUE = Pattern.compile("^You have completed " + NUMBER + " (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.?$", Pattern.CASE_INSENSITIVE);
	private static final String LOG_PREFIX = "New item added to your collection log: ";

	private DropCountParser() { }

	static String plain(String text)
	{
		if (text == null || text.length() > 1024) return "";
		return text.replaceAll("<[^>]*>", "").replaceAll("@[a-zA-Z0-9_]{1,40}@", "").replace('\u00a0', ' ').trim();
	}

	static Count parse(String message)
	{
		String text = plain(message);
		Matcher clue = CLUE.matcher(text);
		if (clue.matches()) return result(DropCounterRegistry.byChatName("Clue Scrolls (" + clue.group(2) + ")"), clue.group(1));
		Matcher prefix = PREFIX_COUNT.matcher(text);
		if (prefix.matches()) return result(DropCounterRegistry.byChatName(prefix.group(1)), prefix.group(2));
		Matcher kc = COUNT.matcher(text);
		if (!kc.matches() || (kc.group(1) == null && kc.group(3) == null)) return null;
		return result(DropCounterRegistry.byChatName(kc.group(2)), kc.group(4));
	}

	static String collectionItem(String message)
	{
		String text = plain(message);
		if (!text.startsWith(LOG_PREFIX)) return null;
		String name = text.substring(LOG_PREFIX.length());
		return DropEvent.saneLabel(name) ? name : null;
	}

	private static Count result(DropCounterRegistry.Counter counter, String number)
	{
		if (counter == null) return null;
		try
		{
			int value = Integer.parseInt(number.replace(",", ""));
			return value > 0 ? new Count(counter, value) : null;
		}
		catch (NumberFormatException exception) { return null; }
	}

	static final class Count
	{
		final DropCounterRegistry.Counter counter;
		final int value;
		Count(DropCounterRegistry.Counter counter, int value) { this.counter = counter; this.value = value; }
	}
}

package com.runeglass.runelite;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import java.util.Set;
import java.util.ArrayList;

final class DropEvent
{
	private final JsonObject json;

	DropEvent(UUID eventId, UUID sessionId, Instant occurredAt, String sourceType,
		String sourceName, int rollCount, List<JsonObject> items)
	{
		this(eventId, sessionId, occurredAt, sourceType, sourceName, rollCount, items, null);
	}

	DropEvent(UUID eventId, UUID sessionId, Instant occurredAt, String sourceType,
		String sourceName, int rollCount, List<JsonObject> items, Integer npcId)
	{
		json = new JsonObject();
		json.addProperty("eventId", eventId.toString());
		json.addProperty("sessionId", sessionId.toString());
		json.addProperty("occurredAt", occurredAt.toString());
		JsonObject source = new JsonObject();
		source.addProperty("type", sourceType);
		source.addProperty("name", sourceName);
		if ("npc".equals(sourceType) && npcId != null && npcId > 0) source.addProperty("npcId", npcId);
		json.add("source", source);
		json.addProperty("rollCount", rollCount);
		JsonArray rewards = new JsonArray();
		items.forEach(item -> rewards.add(item.deepCopy()));
		json.add("items", rewards);
	}

	private DropEvent(JsonObject json) { this.json = json.deepCopy(); }

	String sourceType() { return json.getAsJsonObject("source").get("type").getAsString(); }
	String sourceName() { return json.getAsJsonObject("source").get("name").getAsString(); }
	int rollCount() { return json.get("rollCount").getAsInt(); }
	List<Integer> itemIdsNamed(String name)
	{
		List<Integer> ids = new ArrayList<>();
		json.getAsJsonArray("items").forEach(element ->
		{
			JsonObject item = element.getAsJsonObject();
			if (name.equals(item.get("itemName").getAsString())) ids.add(item.get("itemId").getAsInt());
		});
		return ids;
	}

	DropEvent freeze(DropCountParser.Count count, JsonObject continuity, String collectionLog, Set<Integer> newSlots)
	{
		if (json.has("collectionLog")) throw new IllegalStateException("Drop already frozen");
		JsonObject frozen = json.deepCopy();
		if (count != null)
		{
			JsonObject sourceCount = new JsonObject();
			sourceCount.addProperty("value", count.value);
			sourceCount.addProperty("unit", count.counter.unit);
			sourceCount.addProperty("counterKey", count.counter.key);
			sourceCount.addProperty("evidence", "game-message");
			frozen.add("sourceCount", sourceCount);
			if (continuity != null) frozen.add("continuity", continuity.deepCopy());
		}
		frozen.addProperty("collectionLog", collectionLog);
		frozen.getAsJsonArray("items").forEach(element ->
		{
			JsonObject item = element.getAsJsonObject();
			if (newSlots.contains(item.get("itemId").getAsInt())) item.addProperty("newCollectionLogSlot", true);
		});
		return new DropEvent(frozen);
	}

	static boolean removeCountEvidence(JsonObject event)
	{
		boolean changed = event.getAsJsonObject("source").remove("npcId") != null;
		changed |= event.remove("sourceCount") != null;
		changed |= event.remove("continuity") != null;
		changed |= event.remove("collectionLog") != null;
		for (com.google.gson.JsonElement element : event.getAsJsonArray("items"))
			changed |= element.getAsJsonObject().remove("newCollectionLogSlot") != null;
		return changed;
	}

	DropEvent withoutCountEvidence()
	{
		JsonObject plain = json.deepCopy();
		removeCountEvidence(plain);
		return new DropEvent(plain);
	}

	String eventId()
	{
		return json.get("eventId").getAsString();
	}

	JsonObject envelope(SyncContext context, String connectionId)
	{
		JsonObject batch = new JsonObject();
		batch.addProperty("protocolVersion", 1);
		batch.addProperty("consentVersion", 1);
		batch.addProperty("connectionId", connectionId);
		JsonObject client = new JsonObject();
		client.addProperty("pluginVersion", context.getPluginVersion());
		client.addProperty("runeliteVersion", context.getRuneLiteVersion());
		client.addProperty("gameRevision", context.getGameRevision());
		batch.add("client", client);
		JsonObject character = new JsonObject();
		character.addProperty("displayName", context.getDisplayName());
		character.addProperty("accountType", context.getAccountType());
		character.addProperty("profileType", context.getProfileType());
		batch.add("character", character);
		JsonArray events = new JsonArray();
		events.add(json.deepCopy());
		batch.add("events", events);
		return batch;
	}

	static boolean saneLabel(String label)
	{
		return label != null && !label.trim().isEmpty() && label.length() <= 120
			&& label.matches("[^<>\\x00-\\x1f\\x7f]+");
	}
}

package com.runeglass.runelite;

import java.util.Objects;
import java.util.UUID;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;

final class DropGameContext
{
	static final int COLLECTION_LOG_NOTIFICATION = VarbitID.OPTION_COLLECTION_NEW_ITEM;
	private String family;
	private String encounter;

	static String collectionLogSetting(int value)
	{
		if (value == 1 || value == 3) return "enabled";
		if (value == 0 || value == 2) return "disabled";
		return "unknown";
	}

	static String collectionLogSetting(Client client)
	{
		try { return collectionLogSetting(client.getVarbitValue(COLLECTION_LOG_NOTIFICATION)); }
		catch (RuntimeException exception) { return "unknown"; }
	}

	private static final Set<Integer> COX_REGIONS = Set.of(12889, 13136, 13137, 13138, 13139, 13140, 13141, 13145, 13393, 13394, 13395, 13396, 13397, 13401);
	private static final Set<Integer> TOB_REGIONS = Set.of(12611, 12612, 12613, 12867, 12869, 13122, 13123, 13125, 13379);
	private static final Set<Integer> TOA_REGIONS = Set.of(14160, 14162, 14164, 14674, 14676, 15184, 15186, 15188, 15696, 15698, 15700);

	String raidEncounter(Client client)
	{
		if (client.getTopLevelWorldView() == null || !client.getTopLevelWorldView().isInstance() || client.getLocalPlayer() == null)
			return update(null);
		int region = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation()).getRegionID();
		String next = raidFamily(region, client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON),
			client.getVarbitValue(VarbitID.RAIDS_CLIENT_PROGRESS), client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS),
			client.getVarbitValue(VarbitID.TOA_CLIENT_PARTYSTATUS));
		return update(next);
	}

	static String raidFamily(int region, int inCox, int coxProgress, int tobStatus, int toaStatus)
	{
		if (COX_REGIONS.contains(region) && inCox > 0 && coxProgress > 0) return "Chambers of Xeric";
		if (TOB_REGIONS.contains(region) && tobStatus >= 2) return "Theatre of Blood";
		if (TOA_REGIONS.contains(region) && toaStatus >= 2) return "Tombs of Amascut";
		return null;
	}

	String update(String next)
	{
		if (!Objects.equals(family, next))
		{
			family = next;
			encounter = next == null ? null : next + ":" + UUID.randomUUID();
		}
		return encounter;
	}

	void clear() { family = null; encounter = null; }
}

