final class PairingClient
{
	static final String BASE_URL = "https://fast-duck-448.eu-west-1.convex.site/";
	static final String VERIFICATION_URI = "https://runeglass.app/settings/runelite";

	private static final String START_PATH = "runelite/v1/pairing/start";
	private static final String TOKEN_PATH = "runelite/v1/pairing/token";
	private static final String CREDENTIAL_HASH_PREFIX = "runelite-connection-credential-v1:";
	private static final int RAW_CREDENTIAL_BYTES = 32;
	private static final int MAX_RESPONSE_CHARACTERS = 8 * 1_024;
	private static final int MAX_PAIRING_LIFETIME_SECONDS = 15 * 60;
	private static final int MAX_POLL_INTERVAL_SECONDS = 30;
	private static final int MAX_RETRY_AFTER_SECONDS = 300;
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final Pattern OPAQUE_VALUE = Pattern.compile("^[A-Za-z0-9_-]{43}$");
	private static final Pattern USER_CODE = Pattern.compile(
		"^[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{5}-[ABCDEFGHJKLMNPQRSTUVWXYZ23456789]{5}$");
	private static final Pattern CONNECTION_ID = Pattern.compile("^pcn_[A-Za-z0-9_-]{43}$");

	interface Listener
	{
		void onCode(String userCode, Instant expiresAt);

		void onConnected();

		void onFailure(Failure failure);
	}

	enum Failure
	{
		AUTHORIZATION_DENIED,
		CONNECTION_LIMIT,
		EXPIRED,
		PROTOCOL_ERROR,
		TEMPORARILY_UNAVAILABLE
	}

	static final class Credentials
	{
		private final String connectionId;
		private final String rawCredential;

		Credentials(String connectionId, String rawCredential)
		{
			this.connectionId = connectionId;
			this.rawCredential = rawCredential;
		}

		String getConnectionId()
		{
			return connectionId;
		}

		String getRawCredential()
		{
			return rawCredential;
		}

		boolean sameConnection(Credentials other)
		{
			return other != null
				&& connectionId.equals(other.connectionId)
				&& rawCredential.equals(other.rawCredential);
		}
	}

	private final Object lock = new Object();
	private final OkHttpClient httpClient;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final HttpUrl baseUrl;
	private final Clock clock;
	private final SecureRandom secureRandom = new SecureRandom();

	private long generation;
	private Call activeCall;
	private ScheduledFuture<?> scheduledPoll;
	private String deviceCode;
	private String rawCredential;
	private Instant expiresAt;
	private int pollIntervalSeconds;
	private Credentials credentials;

	static PairingClient create(
		OkHttpClient httpClient,
		Gson gson,
		ScheduledExecutorService executor)
	{
		return new PairingClient(
			httpClient,
			gson,
			executor,
			Objects.requireNonNull(HttpUrl.parse(BASE_URL), "RuneGlass base URL"),
			Clock.systemUTC());
	}

	PairingClient(
		OkHttpClient httpClient,
		Gson gson,
		ScheduledExecutorService executor,
		HttpUrl baseUrl,
		Clock clock)
	{
		this.httpClient = Objects.requireNonNull(httpClient, "httpClient");
		this.gson = Objects.requireNonNull(gson, "gson");
		this.executor = Objects.requireNonNull(executor, "executor");
		this.baseUrl = Objects.requireNonNull(baseUrl, "baseUrl");
		this.clock = Objects.requireNonNull(clock, "clock");
	}

	Optional<Credentials> getCredentials()
	{
		synchronized (lock)
		{
			return Optional.ofNullable(credentials);
		}
	}

	void start(Listener listener)
	{
		Objects.requireNonNull(listener, "listener");
		final long requestGeneration;
		final String nextCredential = generateOpaqueValue();
		synchronized (lock)
		{
			cancelNetworkLocked();
			generation++;
			requestGeneration = generation;
			credentials = null;
			rawCredential = nextCredential;
		}

		JsonObject payload = new JsonObject();
		payload.addProperty("connectionCredentialHash", hashConnectionCredential(nextCredential));
		Request request = jsonRequest(START_PATH, payload);
		enqueue(requestGeneration, request, listener, this::handleStartResponse);
	}

	void cancel()
	{
		synchronized (lock)
		{
			generation++;
			cancelNetworkLocked();
			credentials = null;
		}
	}

	void cancelPending()
	{
		synchronized (lock)
		{
			generation++;
			cancelNetworkLocked();
		}
	}

	private void handleStartResponse(long requestGeneration, Response response, Listener listener)
		throws IOException
	{
		if (response.code() != 201)
		{
			fail(requestGeneration, listener, failureForResponse(response));
			return;
		}

		JsonObject body = ProtocolJson.readObject(response, MAX_RESPONSE_CHARACTERS);
		if (!ProtocolJson.hasExactKeys(
			body,
			"protocolVersion",
			"deviceCode",
			"userCode",
			"verificationUri",
			"expiresInSeconds",
			"pollIntervalSeconds")
			|| ProtocolJson.intValue(body, "protocolVersion") != 1)
		{
			fail(requestGeneration, listener, Failure.PROTOCOL_ERROR);
			return;
		}

		String nextDeviceCode = ProtocolJson.stringValue(body, "deviceCode");
		String userCode = ProtocolJson.stringValue(body, "userCode");
		String verificationUri = ProtocolJson.stringValue(body, "verificationUri");
		int expiresInSeconds = ProtocolJson.intValue(body, "expiresInSeconds");
		int nextPollInterval = ProtocolJson.intValue(body, "pollIntervalSeconds");
		if (!OPAQUE_VALUE.matcher(nextDeviceCode).matches()
			|| !USER_CODE.matcher(userCode).matches()
			|| !VERIFICATION_URI.equals(verificationUri)
			|| expiresInSeconds <= 0
			|| expiresInSeconds > MAX_PAIRING_LIFETIME_SECONDS
			|| nextPollInterval <= 0
			|| nextPollInterval > MAX_POLL_INTERVAL_SECONDS)
		{
			fail(requestGeneration, listener, Failure.PROTOCOL_ERROR);
			return;
		}

		Instant nextExpiry = clock.instant().plusSeconds(expiresInSeconds);
		synchronized (lock)
		{
			if (requestGeneration != generation)
			{
				return;
			}
			activeCall = null;
			deviceCode = nextDeviceCode;
			expiresAt = nextExpiry;
			pollIntervalSeconds = nextPollInterval;
		}
		listener.onCode(userCode, nextExpiry);
		schedulePoll(requestGeneration, listener, nextPollInterval);
	}

	private void poll(long requestGeneration, Listener listener)
	{
		final String currentDeviceCode;
		synchronized (lock)
		{
			if (requestGeneration != generation)
			{
				return;
			}
			scheduledPoll = null;
			if (expiresAt == null || !clock.instant().isBefore(expiresAt))
			{
				currentDeviceCode = null;
			}
			else
			{
				currentDeviceCode = deviceCode;
			}
		}
		if (currentDeviceCode == null)
		{
			fail(requestGeneration, listener, Failure.EXPIRED);
			return;
		}

		JsonObject payload = new JsonObject();
		payload.addProperty("deviceCode", currentDeviceCode);
		enqueue(requestGeneration, jsonRequest(TOKEN_PATH, payload), listener, this::handleTokenResponse);
	}

	private void handleTokenResponse(long requestGeneration, Response response, Listener listener)
		throws IOException
	{
		if (response.code() == 429)
		{
			JsonObject body = ProtocolJson.readObject(response, MAX_RESPONSE_CHARACTERS);
			Integer retryAfterSeconds = retryAfterSeconds(response);
			if (!isError(body, "rate_limited") || retryAfterSeconds == null)
			{
				fail(requestGeneration, listener, Failure.PROTOCOL_ERROR);
				return;
			}
			synchronized (lock)
			{
				if (requestGeneration != generation)
				{
					return;
				}
				activeCall = null;
			}
			schedulePoll(requestGeneration, listener, retryAfterSeconds);
			return;
		}

		if (response.code() == 202)
		{
			JsonObject body = ProtocolJson.readObject(response, MAX_RESPONSE_CHARACTERS);
			if (!isError(body, "authorization_pending"))
			{
				fail(requestGeneration, listener, Failure.PROTOCOL_ERROR);
				return;
			}
			final int nextPollInterval;
			synchronized (lock)
			{
				if (requestGeneration != generation)
				{
					return;
				}
				activeCall = null;
				nextPollInterval = pollIntervalSeconds;
			}
			schedulePoll(requestGeneration, listener, nextPollInterval);
			return;
		}

		if (response.code() != 200)
		{
			fail(requestGeneration, listener, failureForResponse(response));
			return;
		}

		JsonObject body = ProtocolJson.readObject(response, MAX_RESPONSE_CHARACTERS);
		if (!ProtocolJson.hasExactKeys(
			body,
			"protocolVersion",
			"status",
			"connectionId",
			"credentialType",
			"scope")
			|| ProtocolJson.intValue(body, "protocolVersion") != 1
			|| !"issued".equals(ProtocolJson.stringValue(body, "status"))
			|| !"Bearer".equals(ProtocolJson.stringValue(body, "credentialType"))
			|| !"skills:write".equals(ProtocolJson.stringValue(body, "scope")))
		{
			fail(requestGeneration, listener, Failure.PROTOCOL_ERROR);
			return;
		}

		String connectionId = ProtocolJson.stringValue(body, "connectionId");
		if (!CONNECTION_ID.matcher(connectionId).matches())
		{
			fail(requestGeneration, listener, Failure.PROTOCOL_ERROR);
			return;
		}

		synchronized (lock)
		{
			if (requestGeneration != generation || rawCredential == null)
			{
				return;
			}
			activeCall = null;
			credentials = new Credentials(connectionId, rawCredential);
			deviceCode = null;
			rawCredential = null;
			expiresAt = null;
			pollIntervalSeconds = 0;
		}
		listener.onConnected();
	}

	private void enqueue(
		long requestGeneration,
		Request request,
		Listener listener,
		ResponseHandler responseHandler)
	{
		Call call = httpClient.newCall(request);
		synchronized (lock)
		{
			if (requestGeneration != generation)
			{
				call.cancel();
				return;
			}
			activeCall = call;
		}
		call.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call ignored, IOException exception)
			{
				fail(requestGeneration, listener, Failure.TEMPORARILY_UNAVAILABLE);
			}

			@Override
			public void onResponse(Call ignored, Response response)
			{
				try (Response closedResponse = response)
				{
					responseHandler.handle(requestGeneration, closedResponse, listener);
				}
				catch (IOException | RuntimeException exception)
				{
					fail(requestGeneration, listener, Failure.PROTOCOL_ERROR);
				}
			}
		});
	}

	private void schedulePoll(long requestGeneration, Listener listener, int delaySeconds)
	{
		try
		{
			ScheduledFuture<?> next = executor.schedule(
				() -> poll(requestGeneration, listener),
				delaySeconds,
				TimeUnit.SECONDS);
			synchronized (lock)
			{
				if (requestGeneration != generation)
				{
					next.cancel(false);
					return;
				}
				scheduledPoll = next;
			}
		}
		catch (RuntimeException exception)
		{
			fail(requestGeneration, listener, Failure.TEMPORARILY_UNAVAILABLE);
		}
	}

	private void fail(long requestGeneration, Listener listener, Failure failure)
	{
		synchronized (lock)
		{
			if (requestGeneration != generation)
			{
				return;
			}
			generation++;
			cancelNetworkLocked();
			credentials = null;
		}
		listener.onFailure(failure);
	}

	private void cancelNetworkLocked()
	{
		if (activeCall != null)
		{
			activeCall.cancel();
			activeCall = null;
		}
		if (scheduledPoll != null)
		{
			scheduledPoll.cancel(false);
			scheduledPoll = null;
		}
		deviceCode = null;
		rawCredential = null;
		expiresAt = null;
		pollIntervalSeconds = 0;
	}

	private Request jsonRequest(String path, JsonObject payload)
	{
		HttpUrl url = Objects.requireNonNull(baseUrl.resolve(path), "RuneGlass route");
		return new Request.Builder()
			.url(url)
			.header("Accept", "application/json")
			.post(RequestBody.create(JSON, gson.toJson(payload)))
			.build();
	}

	private static Failure failureForResponse(Response response)
	{
		try
		{
			JsonObject body = ProtocolJson.readObject(response, MAX_RESPONSE_CHARACTERS);
			if (response.code() == 409 && isError(body, "connection_limit"))
			{
				return Failure.CONNECTION_LIMIT;
			}
			if (isError(body, "authorization_denied"))
			{
				return Failure.AUTHORIZATION_DENIED;
			}
			if (isError(body, "expired_device_code"))
			{
				return Failure.EXPIRED;
			}
		}
		catch (IOException | RuntimeException ignored)
		{
			return Failure.TEMPORARILY_UNAVAILABLE;
		}
		return Failure.TEMPORARILY_UNAVAILABLE;
	}

	private static boolean isError(JsonObject body, String error)
	{
		return ProtocolJson.hasExactKeys(body, "protocolVersion", "error")
			&& ProtocolJson.intValue(body, "protocolVersion") == 1
			&& error.equals(ProtocolJson.stringValue(body, "error"));
	}

	private static Integer retryAfterSeconds(Response response)
	{
		String header = response.header("Retry-After");
		if (header == null || !header.matches("^[1-9][0-9]{0,2}$"))
		{
			return null;
		}
		try
		{
			int value = Integer.parseInt(header);
			return value <= MAX_RETRY_AFTER_SECONDS ? value : null;
		}
		catch (NumberFormatException exception)
		{
			return null;
		}
	}

	private String generateOpaqueValue()
	{
		byte[] bytes = new byte[RAW_CREDENTIAL_BYTES];
		secureRandom.nextBytes(bytes);
		return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
	}

	static String hashConnectionCredential(String rawCredential)
	{
		Objects.requireNonNull(rawCredential, "rawCredential");
		try
		{
			MessageDigest digest = MessageDigest.getInstance("SHA-256");
			byte[] hash = digest.digest(
				(CREDENTIAL_HASH_PREFIX + rawCredential).getBytes(StandardCharsets.UTF_8));
			return Base64.getUrlEncoder().withoutPadding().encodeToString(hash);
		}
		catch (NoSuchAlgorithmException exception)
		{
			throw new IllegalStateException("SHA-256 is unavailable", exception);
		}
	}

	@FunctionalInterface
	private interface ResponseHandler
	{
		void handle(long requestGeneration, Response response, Listener listener) throws IOException;
	}
}

package com.runeglass.runelite;

import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;

final class PrivateFiles
{
	static final String TEMPORARY_SUFFIX = ".tmp";

	private PrivateFiles()
	{
	}

	static synchronized void createDirectory(Filepath directory) throws IOException
	{
		if (directory.isDirectory())
		{
			return;
		}
		if (directory.isRoot())
		{
			directory.createDirectories();
			return;
		}
		Filepath parent = directory.getParent();
		createDirectory(parent);
		Filepath staged = parent.createTempDir(directory.getFileName() + ".");
		try
		{
			staged.moveTo(directory);
		}
		catch (IOException exception)
		{
			staged.deleteIfExists();
			directory.createDirectories();
		}
	}

	static void write(Filepath target, String temporaryPrefix, byte[] data) throws IOException
	{
		Filepath temporary = target.getParent().createTempFile(temporaryPrefix, TEMPORARY_SUFFIX);
		try
		{
			try (FileChannel channel = temporary.openFileChannel(StandardOpenOption.WRITE))
			{
				ByteBuffer buffer = ByteBuffer.wrap(data);
				while (buffer.hasRemaining())
				{
					channel.write(buffer);
				}
				channel.force(true);
			}
			temporary.moveTo(
				target,
				StandardCopyOption.ATOMIC_MOVE,
				StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException | RuntimeException exception)
		{
			try
			{
				temporary.deleteIfExists();
			}
			catch (IOException cleanup)
			{
				exception.addSuppressed(cleanup);
			}
			throw exception;
		}
	}

	static String readUtf8(Filepath file) throws IOException
	{
		try (InputStream input = file.openInputStream())
		{
			return StandardCharsets.UTF_8.newDecoder()
				.decode(ByteBuffer.wrap(input.readAllBytes()))
				.toString();
		}
	}

	static void deleteTemporaryFiles(Filepath directory, String temporaryPrefix) throws IOException
	{
		if (!directory.isDirectory())
		{
			return;
		}
		List<Filepath> temporaryFiles;
		try (Stream<Filepath> files = directory.walk(1))
		{
			temporaryFiles = files
				.filter(file -> !file.equals(directory)
					&& file.getFileName().startsWith(temporaryPrefix)
					&& file.getFileName().endsWith(TEMPORARY_SUFFIX)
					&& file.isFile())
				.collect(Collectors.toList());
		}
		for (Filepath file : temporaryFiles)
		{
			file.deleteIfExists();
		}
	}
}

package com.runeglass.runelite;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.io.Reader;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import okhttp3.Response;
import okhttp3.ResponseBody;

final class ProtocolJson
{
	private ProtocolJson()
	{
	}

	static JsonObject readObject(Response response, int maximumCharacters) throws IOException
	{
		ResponseBody responseBody = response.body();
		if (maximumCharacters <= 0
			|| responseBody == null
			|| responseBody.contentLength() > maximumCharacters)
		{
			throw new IOException("Invalid RuneGlass response");
		}

		StringBuilder text = new StringBuilder();
		try (Reader reader = responseBody.charStream())
		{
			char[] buffer = new char[1_024];
			int count;
			while ((count = reader.read(buffer)) != -1)
			{
				if (text.length() + count > maximumCharacters)
				{
					throw new IOException("RuneGlass response is too large");
				}
				text.append(buffer, 0, count);
			}
		}

		JsonElement parsed = new JsonParser().parse(text.toString());
		if (!parsed.isJsonObject())
		{
			throw new IOException("RuneGlass response must be an object");
		}
		return parsed.getAsJsonObject();
	}

	static boolean hasExactKeys(JsonObject body, String... keys)
	{
		Set<String> actual = new HashSet<>();
		body.entrySet().forEach(entry -> actual.add(entry.getKey()));
		return actual.equals(new HashSet<>(Arrays.asList(keys)));
	}

	static boolean hasKeys(JsonObject body, Set<String> required, Set<String> optional)
	{
		Set<String> actual = new HashSet<>(body.keySet());
		if (!actual.containsAll(required)) return false;
		actual.removeAll(required);
		return optional.containsAll(actual);
	}

	static String stringValue(JsonObject body, String key)
	{
		JsonElement value = body.get(key);
		if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isString())
		{
			return "";
		}
		return value.getAsString();
	}

	static int intValue(JsonObject body, String key)
	{
		JsonElement value = body.get(key);
		if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber())
		{
			return -1;
		}
		String serialized = value.toString();
		if (!serialized.matches("^(0|[1-9][0-9]{0,9})$"))
		{
			return -1;
		}
		try
		{
			return Integer.parseInt(serialized);
		}
		catch (NumberFormatException exception)
		{
			return -1;
		}
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

final class QuestSnapshot
{
	private final String snapshotId = UUID.randomUUID().toString();
	private final String observedAt;
	private final Map<String, Object> progress;

	QuestSnapshot(Instant observedAt, int questPoints, Map<Integer, String> states)
	{
		if (questPoints < 0 || questPoints > 10_000 || states.isEmpty())
		{
			throw new IllegalArgumentException("Invalid semantic quest snapshot");
		}
		this.observedAt = observedAt.toString();
		List<Map<String, Object>> quests = new ArrayList<>();
		for (int id : QuestCatalog.ids())
		{
			String state = states.get(id);
			if (state == null) continue;
			if (!("not_started".equals(state) || "in_progress".equals(state) || "completed".equals(state)))
			{
				throw new IllegalArgumentException("Invalid quest state");
			}
			Map<String, Object> entry = new LinkedHashMap<>();
			entry.put("id", id);
			entry.put("state", state);
			quests.add(Collections.unmodifiableMap(entry));
		}
		if (quests.size() != states.size()) throw new IllegalArgumentException("Unknown quest ID");
		Map<String, Object> value = new LinkedHashMap<>();
		value.put("catalogVersion", QuestCatalog.VERSION);
		value.put("coverage", states.size() == QuestCatalog.ids().length ? "complete" : "partial");
		value.put("questPoints", questPoints);
		value.put("quests", Collections.unmodifiableList(quests));
		progress = Collections.unmodifiableMap(value);
	}

	String getSnapshotId() { return snapshotId; }
	String getObservedAt() { return observedAt; }
	Map<String, Object> getProgress() { return progress; }
}

package com.runeglass.runelite;

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.VarPlayerID;

final class QuestSnapshotReader
{
	static Map<Integer, String> readStates(Client client)
	{
		Map<Integer, String> states = new LinkedHashMap<>();
		for (int id : QuestCatalog.ids())
		{
			try
			{
				client.runScript(ScriptID.QUEST_STATUS_GET, id);
				int status = client.getIntStack()[0];
				if (status == 2)
				{
					states.put(id, "completed");
				}
				else if (status == 1)
				{
					states.put(id, "not_started");
				}
				else if (status == 0)
				{
					states.put(id, "in_progress");
				}
			}
			catch (RuntimeException exception)
			{
			}
		}
		return states;
	}

	static int readQuestPoints(Client client)
	{
		return client.getVarpValue(VarPlayerID.QP);
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.Map;
import java.util.Optional;

final class QuestSnapshotReducer
{
	private static final long MIN_CAPTURE_TICKS = 50;
	private static final long QUIET_TICKS = 3;
	private static final long MAX_DIRTY_TICKS = 10;
	private long tick;
	private long lastCapture = -MIN_CAPTURE_TICKS;
	private long dirtySince;
	private long lastChange;
	private boolean dirty = true;
	private Map<String, Object> lastProgress;

	void markDirty()
	{
		if (!dirty) dirtySince = tick;
		dirty = true;
		lastChange = tick;
	}

	boolean shouldCapture()
	{
		tick++;
		if (!dirty || tick - lastCapture < MIN_CAPTURE_TICKS
			|| (tick - lastChange < QUIET_TICKS && tick - dirtySince < MAX_DIRTY_TICKS)) return false;
		dirty = false;
		lastCapture = tick;
		return true;
	}

	Optional<QuestSnapshot> observe(Instant observedAt, int questPoints, Map<Integer, String> states)
	{
		QuestSnapshot snapshot = new QuestSnapshot(observedAt, questPoints, states);
		if (snapshot.getProgress().equals(lastProgress)) return Optional.empty();
		lastProgress = snapshot.getProgress();
		return Optional.of(snapshot);
	}

	QuestSnapshot observeManual(Instant observedAt, int questPoints, Map<Integer, String> states)
	{
		QuestSnapshot snapshot = new QuestSnapshot(observedAt, questPoints, states);
		lastProgress = snapshot.getProgress();
		return snapshot;
	}

	void reset()
	{
		tick = 0;
		lastCapture = -MIN_CAPTURE_TICKS;
		dirtySince = 0;
		lastChange = 0;
		dirty = true;
		lastProgress = null;
	}
}

