	void showFailure(PairingClient.Failure failure)
	{
		Objects.requireNonNull(failure, "failure");
		String detail;
		switch (failure)
		{
			case CONNECTION_LIMIT:
				detail = "The RuneLite connection limit has been reached. Open RuneGlass Settings → RuneLite Sync, disconnect an unused client, then generate a new code. If this continues, contact RuneGlass support.";
				break;
			case AUTHORIZATION_DENIED:
				detail = "RuneGlass denied this pairing request. Generate a new code to try again.";
				break;
			case EXPIRED:
				detail = "The pairing code expired. Generate a new code to try again.";
				break;
			case PROTOCOL_ERROR:
				detail = "RuneGlass returned an unexpected response. Pairing stopped safely.";
				break;
			default:
				detail = "RuneGlass could not complete pairing. Check your connection and try again.";
				break;
		}
		String finalDetail = detail;
		onEdt(() -> update(
			"Pairing stopped",
			"—",
			finalDetail,
			"Generate code",
			true,
			false,
			false,
			false));
	}

	private void update(
		String status,
		String code,
		String detail,
		String action,
		boolean enabled,
		boolean actionStops,
		boolean manualVisible,
		boolean manualEnabled)
	{
		statusLabel.setText(status);
		codeLabel.setText(code);
		detailText.setText(detail);
		actionButton.setText(action);
		actionButton.setEnabled(enabled);
		manualButton.setVisible(manualVisible);
		manualButton.setEnabled(manualEnabled);
		stopAction = actionStops;
		revalidate();
		repaint();
	}

	private static JTextArea textArea(String text, int rows)
	{
		JTextArea area = new JTextArea(text);
		area.setEditable(false);
		area.setFocusable(false);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setOpaque(false);
		area.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		area.setFont(FontManager.getDefaultFont());
		area.setBorder(null);
		area.setRows(rows);
		area.setColumns(1);
		area.setAlignmentX(LEFT_ALIGNMENT);
		int preferredHeight = area.getPreferredSize().height;
		area.setMinimumSize(new Dimension(0, preferredHeight));
		area.setPreferredSize(new Dimension(0, preferredHeight));
		area.setMaximumSize(new Dimension(Integer.MAX_VALUE, preferredHeight));
		return area;
	}

	private static void onEdt(Runnable update)
	{
		if (SwingUtilities.isEventDispatchThread())
		{
			update.run();
		}
		else
		{
			SwingUtilities.invokeLater(update);
		}
	}
}

