		private final String profileType;

		private CharacterMetadata(SyncContext context)
		{
			this.displayName = context.getDisplayName();
			this.accountType = context.getAccountType();
			this.profileType = context.getProfileType();
		}
	}
}

package com.runeglass.runelite;

import java.util.EnumSet;
import java.util.Objects;
import java.util.UUID;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.RuneLiteProperties;

final class SyncContext
{
	static final String PLUGIN_VERSION = "1.2.0";

	private static final Pattern DISPLAY_NAME = Pattern.compile("^[A-Za-z0-9 _-]{1,12}$");

	private final String sessionId;
	private final String displayName;
	private final String accountType;
	private final String profileType;
	private final String pluginVersion;
	private final String runeLiteVersion;
	private final int gameRevision;

	static SyncContext capture(Client client, UUID sessionId)
	{
		Objects.requireNonNull(client, "client");
		Objects.requireNonNull(sessionId, "sessionId");
		Player localPlayer = Objects.requireNonNull(client.getLocalPlayer(), "local player");
		String name = Objects.requireNonNull(localPlayer.getName(), "display name")
			.replace('\u00a0', ' ');
		if (!DISPLAY_NAME.matcher(name).matches())
		{
			throw new IllegalStateException("Unsupported display name");
		}

		return new SyncContext(
			sessionId.toString(),
			name,
			accountType(client.getVarbitValue(VarbitID.IRONMAN)),
			profileType(client.getWorldType()),
			PLUGIN_VERSION,
			RuneLiteProperties.getVersion(),
			client.getRevision());
	}

	SyncContext(
		String sessionId,
		String displayName,
		String accountType,
		String profileType,
		String pluginVersion,
		String runeLiteVersion,
		int gameRevision)
	{
		this.sessionId = Objects.requireNonNull(sessionId, "sessionId");
		this.displayName = Objects.requireNonNull(displayName, "displayName");
		this.accountType = Objects.requireNonNull(accountType, "accountType");
		this.profileType = Objects.requireNonNull(profileType, "profileType");
		this.pluginVersion = Objects.requireNonNull(pluginVersion, "pluginVersion");
		this.runeLiteVersion = Objects.requireNonNull(runeLiteVersion, "runeLiteVersion");
		this.gameRevision = gameRevision;
	}

	String getSessionId()
	{
		return sessionId;
	}

	String getDisplayName()
	{
		return displayName;
	}

	String getAccountType()
	{
		return accountType;
	}

	String getProfileType()
	{
		return profileType;
	}

	String getPluginVersion()
	{
		return pluginVersion;
	}

	String getRuneLiteVersion()
	{
		return runeLiteVersion;
	}

	int getGameRevision()
	{
		return gameRevision;
	}

	static String accountType(int accountType)
	{
		switch (accountType)
		{
			case 0:
				return "regular";
			case 1:
			case 4:
				return "ironman";
			case 2:
				return "ultimate";
			case 3:
			case 5:
				return "hardcore";
			default:
				throw new IllegalStateException("Unsupported account type");
		}
	}

	static String profileType(EnumSet<WorldType> worldTypes)
	{
		if (worldTypes != null && worldTypes.contains(WorldType.DEADMAN))
		{
			return "deadman";
		}
		if (worldTypes != null && worldTypes.contains(WorldType.SEASONAL))
		{
			return "league";
		}
		return "standard";
	}
}

package com.runeglass.runelite;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.Base64;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

public class AppearanceMeshEncoderTest
{
	@Test
	public void encodesVersionedMeshAndOmitsHiddenFaces()
	{
		AppearanceMeshEncoder.EncodedMesh mesh = AppearanceMeshEncoder.encode(
			new float[]{-10, 10, 0},
			new float[]{0, 0, -20},
			new float[]{0, 0, 5},
			new int[]{0, 0},
			new int[]{1, 1},
			new int[]{2, 2},
			new int[]{4_000, 4_100},
			new int[]{4_001, 4_101},
			new int[]{4_002, -2},
			new byte[]{0, 0},
			new byte[]{1, 1},
			new short[]{-1, -1},
			new int[]{0, 512, 768},
			new int[]{0, 1, 2, 3, 4},
			0);

		assertEquals(3, mesh.getVertexCount());
		assertEquals(1, mesh.getFaceCount());
		assertArrayEquals(new int[]{0, 512, 768}, mesh.getEquipment());
		assertFalse(mesh.hasTextures());
		assertEquals(43, mesh.getModelHash().length());

		byte[] bytes = Base64.getDecoder().decode(mesh.getMeshBase64());
		ByteBuffer buffer = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);
		assertEquals('R', buffer.get());
		assertEquals('G', buffer.get());
		assertEquals('M', buffer.get());
		assertEquals('1', buffer.get());
		assertEquals(1, buffer.get());
		assertEquals(0, buffer.get());
		assertEquals(3, buffer.getShort());
		assertEquals(3, buffer.getInt());
		assertEquals(1, buffer.getInt());
	}

	@Test
	public void recordsTexturedFacesWithoutEmbeddingGameTextures()
	{
		AppearanceMeshEncoder.EncodedMesh mesh = AppearanceMeshEncoder.encode(
			new float[]{0, 10, 0},
			new float[]{0, 0, -10},
			new float[]{0, 0, 0},
			new int[]{0},
			new int[]{1},
			new int[]{2},
			new int[]{1},
			new int[]{1},
			new int[]{1},
			null,
			null,
			new short[]{42},
			new int[]{0},
			new int[]{0, 0, 0, 0, 0},
			1);

		assertTrue(mesh.hasTextures());
	}

	@Test
	public void rejectsOutOfBoundsGeometryAndComposition()
	{
		assertThrows(IllegalArgumentException.class, () -> AppearanceMeshEncoder.encode(
			new float[]{0, 10, 0},
			new float[]{0, 0, -10},
			new float[]{0, 0, 0},
			new int[]{0},
			new int[]{1},
			new int[]{3},
			new int[]{1},
			new int[]{1},
			new int[]{1},
			null,
			null,
			null,
			new int[]{0},
			new int[]{0, 0, 0, 0, 0},
			0));
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BirdHouseClientTest
{
	private static final String RAW_CREDENTIAL = "rrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrr";
	private static final String CONNECTION_ID = "pcn_ccccccccccccccccccccccccccccccccccccccccccc";
	private static final Instant OBSERVED_AT = Instant.parse("2026-08-28T10:00:00Z");
	private static final String SESSION_ID = "0b54873e-c169-4de7-9bd0-abc879f84d2f";

	private MockWebServer server;
	private ScheduledExecutorService executor;
	private SemanticSnapshotClient<BirdHouseSnapshot> client;

	@Before
	public void setUp() throws IOException
	{
		server = new MockWebServer();
		server.start();
		executor = Executors.newSingleThreadScheduledExecutor();
		client = new SemanticSnapshotClient<>(
			new OkHttpClient(),
			new Gson(),
			executor,
			server.url("/"),
			Clock.fixed(OBSERVED_AT, ZoneOffset.UTC),
			1,
			() -> 0L,
			"runelite/v1/bird-houses",
			(context, connectionId, snapshot) -> SemanticSnapshotPayload.create(
				context,
				connectionId,
				snapshot.getSnapshotId(),
				snapshot.getObservedAt(),
				"houses",
				snapshot.getHouses()));
	}

	@After
	public void tearDown() throws IOException
	{
		client.discard();
		executor.shutdownNow();
		server.shutdown();
	}

	@Test
	public void sendsAnExactAuthenticatedSemanticSnapshot() throws Exception
	{
		server.enqueue(accepted());
		CountDownLatch accepted = new CountDownLatch(1);
		AtomicReference<SemanticSnapshotClient.Failure> failure = new AtomicReference<>();
		client.connect(credentials(), context(), listener(accepted, failure));
		assertTrue(client.publish(snapshot()));

		RecordedRequest request = server.takeRequest(3, TimeUnit.SECONDS);
		assertEquals("/runelite/v1/bird-houses", request.getPath());
		assertEquals("Bearer " + RAW_CREDENTIAL, request.getHeader("Authorization"));
		String bodyText = request.getBody().readUtf8();
		assertFalse(bodyText.contains(RAW_CREDENTIAL));
		JsonObject body = new JsonParser().parse(bodyText).getAsJsonObject();
		assertExactKeys(
			body,
			"protocolVersion",
			"snapshotId",
			"connectionId",
			"sessionId",
			"observedAt",
			"client",
			"character",
			"houses");
		assertEquals(CONNECTION_ID, body.get("connectionId").getAsString());
		assertEquals(4, body.getAsJsonArray("houses").size());
		JsonObject empty = body.getAsJsonArray("houses").get(0).getAsJsonObject();
		assertExactKeys(empty, "space", "state");
		JsonObject seeded = body.getAsJsonArray("houses").get(2).getAsJsonObject();
		assertExactKeys(seeded, "space", "state", "tier", "startedAt", "readyAt");

		assertTrue(accepted.await(3, TimeUnit.SECONDS));
		assertNull(failure.get());
	}

	@Test
	public void suspensionRetriesWithTheSameCredentialWithoutDisconnecting() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(503).setHeader("Retry-After", "1")
			.setBody("{\"protocolVersion\":1,\"error\":\"account_suspended\"}"));
		server.enqueue(accepted());
		CountDownLatch accepted = new CountDownLatch(1);
		AtomicReference<SemanticSnapshotClient.Failure> failure = new AtomicReference<>();
		client.connect(credentials(), context(), listener(accepted, failure));
		assertTrue(client.publish(snapshot()));
		RecordedRequest first = server.takeRequest(3, TimeUnit.SECONDS);
		RecordedRequest retry = server.takeRequest(3, TimeUnit.SECONDS);
		assertEquals("Bearer " + RAW_CREDENTIAL, first.getHeader("Authorization"));
		assertEquals(first.getHeader("Authorization"), retry.getHeader("Authorization"));
		assertEquals(first.getBody().readUtf8(), retry.getBody().readUtf8());
		assertTrue(accepted.await(3, TimeUnit.SECONDS));
		assertTrue(client.isConnected());
		assertNull(failure.get());
	}

	@Test
	public void discardDropsAnUnsentObservation()
	{
		client.connect(credentials(), context(), listener(new CountDownLatch(0), new AtomicReference<>()));
		client.discard();
		assertFalse(client.publish(snapshot()));
	}

	private static PairingClient.Credentials credentials()
	{
		return new PairingClient.Credentials(CONNECTION_ID, RAW_CREDENTIAL);
	}

	private static SyncContext context()
	{
		return new SyncContext(
			SESSION_ID,
			"Iron Jeromey",
			"ironman",
			"standard",
			"1.1.0",
			"1.12.36",
			231);
	}

	private static BirdHouseSnapshot snapshot()
	{
		return new BirdHouseSnapshot(
			"018f35d8-29e4-7cc2-8a58-f9a76b1f3d91",
			OBSERVED_AT,
			Arrays.asList(
				new BirdHouseObservation(BirdHouseSpace.MEADOW_NORTH, BirdHouseState.EMPTY, null, null, null),
				new BirdHouseObservation(BirdHouseSpace.MEADOW_SOUTH, BirdHouseState.BUILT, BirdHouseTier.YEW, null, null),
				new BirdHouseObservation(
					BirdHouseSpace.VALLEY_NORTH,
					BirdHouseState.SEEDED,
					BirdHouseTier.REDWOOD,
					OBSERVED_AT,
					OBSERVED_AT.plusSeconds(50 * 60)),
				new BirdHouseObservation(BirdHouseSpace.VALLEY_SOUTH, BirdHouseState.SEEDED, BirdHouseTier.MAGIC, null, null)));
	}

	private static SemanticSnapshotClient.Listener listener(
		CountDownLatch accepted,
		AtomicReference<SemanticSnapshotClient.Failure> failure)
	{
		return new SemanticSnapshotClient.Listener()
		{
			@Override
			public void onAccepted(Instant serverTime)
			{
				accepted.countDown();
			}

			@Override
			public void onRetryScheduled()
			{
			}

			@Override
			public void onFailure(SemanticSnapshotClient.Failure value)
			{
				failure.set(value);
			}
		};
	}

	private static MockResponse accepted()
	{
		return new MockResponse()
			.setResponseCode(200)
			.setHeader("Content-Type", "application/json")
			.setBody("{\"protocolVersion\":1,\"status\":\"accepted\","
				+ "\"serverTime\":\"2026-08-28T10:00:01Z\","
				+ "\"nextUploadAfterSeconds\":5}");
	}

	private static void assertExactKeys(JsonObject body, String... keys)
	{
		assertEquals(keys.length, body.size());
		for (String key : keys)
		{
			assertTrue(body.has(key));
		}
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.Optional;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BirdHouseSnapshotReducerTest
{
	private static final Instant OBSERVED_AT = Instant.parse("2026-08-28T10:00:00Z");

	@Test
	public void emitsOnlySemanticStateForAllFourSpaces()
	{
		BirdHouseSnapshotReducer reducer = new BirdHouseSnapshotReducer();
		int[] states = new int[]{0, 20, 27, 24};
		reducer.observe(14650, 0, states, OBSERVED_AT);
		BirdHouseSnapshot snapshot = reducer
			.observe(14650, 0, states, OBSERVED_AT.plusSeconds(1))
			.orElseThrow(AssertionError::new);

		assertEquals(4, snapshot.getHouses().size());
		assertEquals("meadow_north", snapshot.getHouses().get(0).getSpace());
		assertEquals("empty", snapshot.getHouses().get(0).getState());
		assertNull(snapshot.getHouses().get(0).getTier());
		assertEquals("built", snapshot.getHouses().get(1).getState());
		assertEquals("yew", snapshot.getHouses().get(1).getTier());
		assertEquals("seeded", snapshot.getHouses().get(2).getState());
		assertEquals("redwood", snapshot.getHouses().get(2).getTier());
		assertNull(snapshot.getHouses().get(2).getReadyAt());
	}

	@Test
	public void estimatesReadinessOnlyWhenTheSeededTransitionWasObserved()
	{
		BirdHouseSnapshotReducer reducer = new BirdHouseSnapshotReducer();
		reducer.observe(14650, 0, new int[]{0, 20, 26, 23}, OBSERVED_AT);
		reducer.observe(14650, 0, new int[]{0, 20, 26, 23}, OBSERVED_AT.plusSeconds(1));

		Instant seededAt = OBSERVED_AT.plusSeconds(10);
		BirdHouseSnapshot snapshot = reducer
			.observe(14650, 0, new int[]{0, 20, 27, 24}, seededAt)
			.orElseThrow(AssertionError::new);

		assertEquals(seededAt.toString(), snapshot.getHouses().get(2).getStartedAt());
		assertEquals(
			seededAt.plusSeconds(50 * 60).toString(),
			snapshot.getHouses().get(2).getReadyAt());
		assertEquals(seededAt.toString(), snapshot.getHouses().get(3).getStartedAt());
	}

	@Test
	public void ignoresUnchangedOffIslandAndLikelyUninitializedObservations()
	{
		BirdHouseSnapshotReducer reducer = new BirdHouseSnapshotReducer();
		int[] built = new int[]{20, 20, 20, 20};
		assertFalse(reducer.observe(12850, 0, built, OBSERVED_AT).isPresent());
		assertFalse(reducer.observe(14650, 0, built, OBSERVED_AT).isPresent());
		assertTrue(reducer.observe(14650, 0, built, OBSERVED_AT.plusSeconds(1)).isPresent());
		assertFalse(reducer.observe(14650, 0, built, OBSERVED_AT.plusSeconds(2)).isPresent());
		assertFalse(reducer.observe(
			14650,
			0,
			new int[]{0, 0, 0, 0},
			OBSERVED_AT.plusSeconds(3)).isPresent());
	}

	@Test
	public void requiresAStableInitialObservationBeforePublishing()
	{
		BirdHouseSnapshotReducer reducer = new BirdHouseSnapshotReducer();
		assertFalse(reducer.observe(
			14650,
			0,
			new int[]{16, 16, 16, 16},
			OBSERVED_AT).isPresent());
		assertFalse(reducer.observe(
			14650,
			0,
			new int[]{15, 15, 15, 15},
			OBSERVED_AT.plusSeconds(1)).isPresent());

		BirdHouseSnapshot snapshot = reducer.observe(
			14650,
			0,
			new int[]{15, 15, 15, 15},
			OBSERVED_AT.plusSeconds(2))
			.orElseThrow(AssertionError::new);
		for (BirdHouseObservation house : snapshot.getHouses())
		{
			assertEquals("seeded", house.getState());
			assertNull(house.getStartedAt());
			assertNull(house.getReadyAt());
		}
	}

	@Test
	public void rejectsUnknownVarpsWithoutReplacingTheLastValidState()
	{
		BirdHouseSnapshotReducer reducer = new BirdHouseSnapshotReducer();
		reducer.observe(14650, 0, new int[]{20, 20, 20, 20}, OBSERVED_AT);
		reducer.observe(14650, 0, new int[]{20, 20, 20, 20}, OBSERVED_AT.plusSeconds(1));
		Optional<BirdHouseSnapshot> invalid = reducer.observe(
			14650,
			0,
			new int[]{28, 20, 20, 20},
			OBSERVED_AT.plusSeconds(2));

		assertFalse(invalid.isPresent());
		assertFalse(reducer.observe(
			14650,
			0,
			new int[]{20, 20, 20, 20},
			OBSERVED_AT.plusSeconds(3)).isPresent());
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;

public class ConnectionStateStoreTest
{
	private static final String CONNECTION_ID = "pcn_ccccccccccccccccccccccccccccccccccccccccccc";
	private static final String CREDENTIAL = "rrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrr";

	@Rule
	public final TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void savesAndRestoresOneProfileScopedState() throws Exception
	{
		Filepath profiles = profiles();
		ConnectionStateStore store = new ConnectionStateStore(profiles, "profile-one", new Gson());
		assertTrue(store.save(
			new PairingClient.Credentials(CONNECTION_ID, CREDENTIAL),
			BigInteger.valueOf(42)));

		ConnectionStateStore.State state = store.load().orElseThrow(AssertionError::new);
		assertEquals(CONNECTION_ID, state.getCredentials().getConnectionId());
		assertEquals(CREDENTIAL, state.getCredentials().getRawCredential());
		assertEquals(BigInteger.valueOf(42), state.getNextSequence());
		Path stateFile = TestStorage.path(store.getStateFile());
		assertTrue(Files.exists(stateFile));
		assertEquals(List.of(ConnectionStateStore.FILE_NAME), names(stateFile.getParent()));
		assertEquals(List.of(stateFile.getParent().getFileName().toString()), names(TestStorage.path(profiles)));
	}

	@Test
	public void separatesProfilesWithoutUsingRawProfileKeys() throws Exception
	{
		Filepath profiles = profiles();
		ConnectionStateStore first = new ConnectionStateStore(profiles, "profile-one", new Gson());
		ConnectionStateStore second = new ConnectionStateStore(profiles, "profile-two", new Gson());

		assertTrue(first.save(
			new PairingClient.Credentials(CONNECTION_ID, CREDENTIAL),
			BigInteger.ONE));

		assertNotEquals(first.getStateFile(), second.getStateFile());
		assertFalse(first.getStateFile().toString().contains("profile-one"));
		assertFalse(second.load().isPresent());
	}

	@Test
	public void malformedStateIsDiscarded() throws Exception
	{
		ConnectionStateStore store = new ConnectionStateStore(profiles(), "profile-one", new Gson());
		Path stateFile = TestStorage.path(store.getStateFile());
		Files.createDirectories(stateFile.getParent());
		Files.write(
			stateFile,
			"{\"version\":1,\"connectionId\":\"wrong\",\"credential\":\"wrong\",\"nextSequence\":\"1\"}"
				.getBytes(StandardCharsets.UTF_8));

		assertFalse(store.load().isPresent());
		assertFalse(Files.exists(stateFile));
	}

	@Test
	public void appliesOwnerOnlyPermissionsWhenSupported() throws Exception
	{
		assumeTrue(TestStorage.posix());
		ConnectionStateStore store = new ConnectionStateStore(profiles(), "profile-one", new Gson());
		assertTrue(store.save(
			new PairingClient.Credentials(CONNECTION_ID, CREDENTIAL),
			BigInteger.ONE));
		Path stateFile = TestStorage.path(store.getStateFile());
		assertEquals("rw-------", TestStorage.permissions(stateFile));
		assertEquals("rwx------", TestStorage.permissions(stateFile.getParent()));

		assertTrue(store.save(
			new PairingClient.Credentials(CONNECTION_ID, CREDENTIAL),
			BigInteger.TEN));
		assertEquals("rw-------", TestStorage.permissions(stateFile));
		assertEquals(BigInteger.TEN, store.load().orElseThrow(AssertionError::new).getNextSequence());
	}

	@Test
	public void loadAndClearRemoveOrphanedCredentialTemporaryFiles() throws Exception
	{
		ConnectionStateStore store = new ConnectionStateStore(profiles(), "profile-one", new Gson());
		assertTrue(store.save(
			new PairingClient.Credentials(CONNECTION_ID, CREDENTIAL),
			BigInteger.valueOf(5)));
		Path directory = TestStorage.path(store.getStateFile()).getParent();
		writeOrphans(directory);

		assertEquals(BigInteger.valueOf(5), store.load().orElseThrow(AssertionError::new).getNextSequence());
		assertEquals(List.of(ConnectionStateStore.FILE_NAME), names(directory));

		writeOrphans(directory);
		assertTrue(store.clear());
		assertFalse(Files.exists(directory));
	}

	private Filepath profiles() throws Exception
	{
		return TestStorage.rooted(temporaryFolder.newFolder("profiles").toPath());
	}

	private static void writeOrphans(Path directory) throws Exception
	{
		byte[] partial = ("{\"credential\":\"" + CREDENTIAL + "\"").getBytes(StandardCharsets.UTF_8);
		Files.write(directory.resolve("connection-state-v1.tmp"), partial);
		Files.write(directory.resolve("connection-state-v1.8231475.tmp"), partial);
	}

	private static List<String> names(Path directory) throws Exception
	{
		try (Stream<Path> files = Files.list(directory))
		{
			return files.map(file -> file.getFileName().toString()).sorted().collect(Collectors.toList());
		}
	}
}

