	private MockResponse accepted(RecordedRequest request, boolean partial)
	{
		JsonObject body = gson.fromJson(body(request), JsonObject.class);
		JsonArray ids = new JsonArray();
		for (com.google.gson.JsonElement event : body.getAsJsonArray("events"))
		{
			ids.add(event.getAsJsonObject().get("eventId"));
			if (partial) break;
		}
		JsonObject result = new JsonObject(); result.addProperty("protocolVersion", 1);
		result.addProperty("status", "accepted"); result.add("acceptedEventIds", ids);
		result.addProperty("serverTime", "2026-10-11T12:00:00Z"); result.addProperty("nextUploadAfterSeconds", 5);
		return new MockResponse().setBody(gson.toJson(result));
	}

	private static MockResponse error(int code, String error)
	{
		return new MockResponse().setResponseCode(code).setBody("{\"protocolVersion\":1,\"error\":\"" + error + "\"}");
	}
	private static final long WAIT_SECONDS = 10;
	private RecordedRequest take() throws InterruptedException
	{
		RecordedRequest request = server.takeRequest(WAIT_SECONDS, TimeUnit.SECONDS); assertNotNull(statuses.toString() + executor.delays.toString(), request); return request;
	}
	private static String body(RecordedRequest request)
	{
		synchronized (request) { return request.getBody().clone().readUtf8(); }
	}
	private int queueSize(String connectionId)
	{
		try
		{
			if (!Files.exists(root.resolve(connectionId))) return 0;
			return new DurableDropQueue(storage, connectionId, gson).size();
		}
		catch (Exception exception) { return -1; }
	}
	private DropClient transport(Filepath dropRoot)
	{
		return new DropClient(new OkHttpClient(), gson, executor, server.url("/runelite/v1/drops"), dropRoot, new DropClient.Listener()
		{
			@Override public void onStatus(String status) { statuses.add(status); progress.add(status); }
			@Override public void onInvalidConnection(PairingClient.Credentials ignored, boolean mismatch) { invalid.incrementAndGet(); progress.add("invalid"); }
		});
	}
	private void await(BooleanSupplier condition) throws InterruptedException
	{
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(WAIT_SECONDS);
		while (!condition.getAsBoolean())
		{
			long remaining = deadline - System.nanoTime();
			assertTrue("Drop transport made no further progress: " + statuses, remaining > 0);
			progress.poll(Math.min(remaining, TimeUnit.MILLISECONDS.toNanos(20)), TimeUnit.NANOSECONDS);
		}
	}
	private static final class FastScheduler extends ScheduledThreadPoolExecutor
	{
		final List<Long> delays = new CopyOnWriteArrayList<>();
		FastScheduler() { super(1); }
		@Override public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
		{
			delays.add(unit.toMillis(delay));
			return super.schedule(command, Math.min(150, unit.toMillis(delay)), TimeUnit.MILLISECONDS);
		}
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class DropContinuityStoreTest
{
	@Rule public TemporaryFolder temporary = new TemporaryFolder();
	private final Gson gson = new Gson();

	@Test public void restartPreservesConsecutiveRunAndJumpsOnlyChangeItsCompleteness() throws Exception
	{
		Filepath directory = TestStorage.rooted(temporary.newFolder().toPath());
		DropContinuityStore store = new DropContinuityStore(directory, gson, "profile-a");
		JsonObject first = store.observe(count(1200)); store.save();
		store = new DropContinuityStore(directory, gson, "profile-a");
		JsonObject afterRestart = store.observe(count(1201));
		assertEquals(first, afterRestart);
		JsonObject gap = store.observe(count(1250)); store.save();
		assertEquals(first.get("id"), gap.get("id")); assertEquals(1250, gap.get("from").getAsInt());
		assertEquals(gap, new DropContinuityStore(directory, gson, "profile-a").observe(count(1251)));
		if (TestStorage.posix()) assertEquals("rw-------", TestStorage.permissions(TestStorage.path(directory.joinSegment(DropContinuityStore.FILE))));
	}

	@Test public void counterRollbackAndProfileChangeStartNewStreams() throws Exception
	{
		Filepath directory = TestStorage.rooted(temporary.newFolder().toPath());
		DropContinuityStore store = new DropContinuityStore(directory, gson, "profile-a");
		JsonObject original = store.observe(count(100)); store.save();
		JsonObject different = new DropContinuityStore(directory, gson, "profile-b").observe(count(101));
		assertNotEquals(original.get("id"), different.get("id"));
		assertEquals(101, different.get("from").getAsInt());
		assertNotEquals(original.get("id"), store.observe(count(99)).get("id"));
	}

	@Test public void invalidationCorruptionAndPurgeCannotClaimContinuity() throws Exception
	{
		Path path = temporary.newFolder().toPath(); Filepath directory = TestStorage.rooted(path);
		DropContinuityStore store = new DropContinuityStore(directory, gson, "profile-a");
		JsonObject first = store.observe(count(100)); store.save();
		store.invalidate("npc", "Vorkath"); store.save();
		assertNotEquals(first.get("id"), new DropContinuityStore(directory, gson, "profile-a").observe(count(101)).get("id"));
		Files.writeString(path.resolve(DropContinuityStore.FILE), "{\"corrupt\":true}", StandardCharsets.UTF_8);
		store = new DropContinuityStore(directory, gson, "profile-a");
		assertTrue(store.damaged()); assertEquals(102, store.observe(count(102)).get("from").getAsInt());
		store.save(); DurableDropQueue.purge(directory);
		assertFalse(Files.exists(path.resolve(DropContinuityStore.FILE)));
	}

	private static DropCountParser.Count count(int value) { return new DropCountParser.Count(DropCounterRegistry.byKey("vorkath"), value); }
}

