public class DropCorrelatorTest
{
	private final DropCorrelator correlator = new DropCorrelator();
	private final List<DropCorrelator.Completed> completed = new ArrayList<>();
	private static final long SECOND = 1_000_000_000L;

	@Test public void reviewedLootSourceNamesCorrelateWithTheirOwnCounters()
	{
		for (String[] pair : new String[][]{
			{"Obor (Chest)", "obor", "chest"}, {"Bryophyta (Chest)", "bryophyta", "chest"},
			{"Dusk", "grotesque-guardians", "kill"}, {"Shellbane gryphon", "shellbane-gryphon", "kill"},
			{"Crazy archaeologist", "crazy-archaeologist", "kill"}, {"Deranged archaeologist", "deranged-archaeologist", "kill"},
			{"Thermonuclear smoke devil", "thermonuclear-smoke-devil", "kill"}})
		{
			correlator.clear(); completed.clear();
			count(pair[1], 123, 10, null);
			correlator.loot(drop("npc", pair[0], true), 10, 10 * SECOND, null, completed::add);
			correlator.advance(21, 21 * SECOND, completed::add);
			assertEquals(1, completed.size());
			assertNotNull(pair[0], completed.get(0).count);
			assertEquals(pair[1], completed.get(0).count.counter.key);
			assertEquals(pair[2], completed.get(0).count.counter.unit);
		}
	}

	@Test public void countAndCollectionSlotMatchBothEventOrdersAndFreezeOriginalFacts()
	{
		for (boolean countFirst : new boolean[]{true, false})
		{
			correlator.clear(); completed.clear(); correlator.context(0, "enabled", null);
			DropCaptureResult drop = drop("npc", "Vorkath", true);
			if (countFirst)
			{
				count("vorkath", 1200, 10, null);
				correlator.collection("Skeletal visage", 10, 10 * SECOND);
			}
			correlator.loot(drop, 10, 10 * SECOND, null, completed::add);
			if (!countFirst)
			{
				correlator.collection("Skeletal visage", 11, 11 * SECOND);
				count("vorkath", 1200, 11, null);
			}
			correlator.advance(20, 20 * SECOND, completed::add);
			assertTrue(completed.isEmpty());
			correlator.advance(21, 21 * SECOND, completed::add);
			DropCorrelator.Completed result = completed.get(0);
			assertEquals(1200, result.count.value); assertEquals("enabled", result.collectionLog); assertEquals(Set.of(22006), result.newSlots);
			DropEvent frozen = drop.event().get().freeze(result.count, null, result.collectionLog, result.newSlots);
			assertEquals(drop.event().get().eventId(), frozen.eventId());
			JsonObject event = DropCaptureTest.event(frozen.envelope(DropCaptureTest.CONTEXT, "connection"));
			assertEquals(DropCaptureTest.NOW.toString(), event.get("occurredAt").getAsString());
			assertTrue(event.getAsJsonArray("items").get(0).getAsJsonObject().get("newCollectionLogSlot").getAsBoolean());
			assertThrows(IllegalStateException.class, () -> frozen.freeze(null, null, "unknown", Set.of()));
		}
	}

	@Test public void lateCompetitorKeepsBothCountsUnknownInsteadOfGreedyMatching()
	{
		correlator.context(0, "enabled", null);
		correlator.loot(drop("npc", "Vorkath", true), 10, 10 * SECOND, null, completed::add);
		count("vorkath", 100, 15, null);
		correlator.advance(16, 16 * SECOND, completed::add);
		assertTrue(completed.isEmpty());
		correlator.loot(drop("npc", "Vorkath", true), 20, 20 * SECOND, null, completed::add);
		correlator.advance(21, 21 * SECOND, completed::add);
		correlator.advance(31, 31 * SECOND, completed::add);
		assertEquals(2, completed.size());
		completed.forEach(result -> assertNull(result.count));
	}

	@Test public void multipleCountsAreAmbiguousButDifferentBossesStayIndependent()
	{
		correlator.loot(drop("npc", "Vorkath", true), 10, 10 * SECOND, null, completed::add);
		count("vorkath", 100, 10, null); count("vorkath", 101, 11, null);
		correlator.loot(drop("npc", "Zulrah", true), 10, 10 * SECOND, null, completed::add);
		count("zulrah", 42, 10, null); count("zulrah", 42, 10, null);
		correlator.advance(21, 21 * SECOND, completed::add);
		assertNull(completed.get(0).count); assertEquals(42, completed.get(1).count.value);
	}

	@Test public void delayedRaidTokenRequiresSameEncounterModeAndIsConsumedOnce()
	{
		String encounter = "Chambers of Xeric:encounter-one";
		correlator.context(0, "enabled", encounter);
		count("chambers-of-xeric-challenge-mode", 13, 10, encounter);
		correlator.advance(500, 500 * SECOND, completed::add);
		correlator.loot(drop("event", "Chambers of Xeric", true), 500, 500 * SECOND, encounter, completed::add);
		correlator.advance(511, 511 * SECOND, completed::add);
		assertEquals("chambers-of-xeric-challenge-mode", completed.get(0).count.counter.key);
		correlator.loot(drop("event", "Chambers of Xeric", true), 520, 520 * SECOND, encounter, completed::add);
		correlator.advance(531, 531 * SECOND, completed::add);
		assertNull(completed.get(1).count);
		correlator.context(532, "enabled", null);
		correlator.context(533, "enabled", "Chambers of Xeric:encounter-two");
		correlator.loot(drop("event", "Chambers of Xeric", true), 534, 534 * SECOND, "Chambers of Xeric:encounter-two", completed::add);
		correlator.advance(545, 545 * SECOND, completed::add);
		assertNull(completed.get(2).count);
	}

	@Test public void raidAfterLootIsSupportedAndMissingContextCannotBorrowACount()
	{
		String encounter = "Tombs of Amascut:run";
		correlator.context(0, "enabled", encounter);
		correlator.loot(drop("event", "Tombs of Amascut", true), 10, 10 * SECOND, encounter, completed::add);
		count("tombs-of-amascut-expert-mode", 42, 11, encounter);
		correlator.advance(21, 21 * SECOND, completed::add);
		assertEquals(42, completed.get(0).count.value);
		correlator.clear(); completed.clear();
		count("tombs-of-amascut", 1, 10, null);
		correlator.loot(drop("event", "Tombs of Amascut", true), 10, 10 * SECOND, null, completed::add);
		correlator.advance(21, 21 * SECOND, completed::add);
		assertNull(completed.get(0).count);
	}

	@Test public void barrowsAndClueTiersUseIndependentCountersAndLowRewardsStillObserveCounts()
	{
		for (String key : new String[]{"barrows-chests", "clue-scrolls-medium", "clue-scrolls-hard"})
		{
			DropCounterRegistry.Counter counter = DropCounterRegistry.byKey(key);
			String source = key.startsWith("clue") ? counter.sources.get(1) : "Barrows";
			count(key, 12, 10, null);
			correlator.loot(drop("event", source, false), 11, 11 * SECOND, null, completed::add);
		}
		correlator.advance(22, 22 * SECOND, completed::add);
		assertEquals(3, completed.size());
		for (DropCorrelator.Completed result : completed) { assertEquals(12, result.count.value); assertFalse(result.result.event().isPresent()); }
	}

	@Test public void expiredRaidTokensAndInsufficientTicksCannotProduceEvidence()
	{
		String encounter = "Theatre of Blood:run";
		correlator.context(0, "enabled", encounter);
		count("theatre-of-blood-hard-mode", 50, 10, encounter);
		correlator.loot(drop("event", "Theatre of Blood", true), 1811, 1811 * SECOND, encounter, completed::add);
		correlator.advance(1822, 1822 * SECOND, completed::add);
		assertNull(completed.get(0).count);
		correlator.clear(); completed.clear(); correlator.context(0, "enabled", null);
		count("vorkath", 100, 10, null);
		correlator.collection("Skeletal visage", 10, 10 * SECOND);
		correlator.loot(drop("npc", "Vorkath", true), 10, 10 * SECOND, null, completed::add);
		correlator.advance(11, 23 * SECOND, completed::add);
		assertNull(completed.get(0).count);
		assertTrue(completed.get(0).newSlots.isEmpty());
		assertEquals("unknown", completed.get(0).collectionLog);
	}

	@Test public void aggregatedRewardsCannotBorrowASingleAttemptCount()
	{
		DropEvent original = drop("event", "Barrows", true).event().get();
		JsonObject item = DropCaptureTest.event(original.envelope(DropCaptureTest.CONTEXT, "connection"))
			.getAsJsonArray("items").get(0).getAsJsonObject();
		DropEvent aggregate = new DropEvent(UUID.randomUUID(), DropCaptureTest.SESSION, DropCaptureTest.NOW,
			"event", "Barrows", 2, List.of(item));
		count("barrows-chests", 100, 10, null);
		correlator.loot(DropCaptureResult.observed("event", 1, 0, null, true, aggregate, true),
			10, 10 * SECOND, null, completed::add);
		correlator.advance(21, 21 * SECOND, completed::add);
		assertNull(completed.get(0).count);
	}

	@Test public void missingMessageTimeoutLogoutAndAmbiguousLogDoNotInventEvidence()
	{
		correlator.context(0, "enabled", null);
		correlator.loot(drop("npc", "Vorkath", true), 10, 10 * SECOND, null, completed::add);
		correlator.loot(drop("npc", "Zulrah", true), 10, 10 * SECOND, null, completed::add);
		correlator.collection("Skeletal visage", 10, 10 * SECOND);
		correlator.advance(21, 21 * SECOND, completed::add);
		for (DropCorrelator.Completed result : completed) { assertNull(result.count); assertTrue(result.newSlots.isEmpty()); assertEquals("unknown", result.collectionLog); }
		correlator.loot(drop("npc", "Vorkath", true), 30, 30 * SECOND, null, completed::add);
		count("vorkath", 123, 30, null);
		correlator.flush(completed::add);
		assertNull(completed.get(2).count); assertEquals("unknown", completed.get(2).collectionLog);
	}

	@Test public void settingChangesAndOverflowWithholdNegativeEvidence()
	{
		correlator.context(0, "enabled", null);
		correlator.loot(drop("npc", "Vorkath", true), 10, 10 * SECOND, null, completed::add);
		correlator.context(11, "disabled", null);
		correlator.advance(21, 21 * SECOND, completed::add);
		assertEquals("unknown", completed.get(0).collectionLog);
		for (int i = 0; i < 65; i++) correlator.loot(drop("npc", "Vorkath", true), 30, 30 * SECOND, null, completed::add);
		correlator.advance(41, 41 * SECOND, completed::add);
		assertEquals(66, completed.size());
		completed.forEach(result -> assertNull(result.count));
	}

	private void count(String key, int value, int tick, String encounter)
	{ correlator.count(new DropCountParser.Count(DropCounterRegistry.byKey(key), value), tick, tick * SECOND, encounter); }

	static DropCaptureResult drop(String type, String source, boolean retained)
	{
		JsonObject item = new JsonObject(); item.addProperty("itemId", 22006); item.addProperty("itemName", "Skeletal visage"); item.addProperty("quantity", 1);
		JsonObject value = new JsonObject(); value.addProperty("kind", "unknown"); item.add("value", value);
		DropEvent event = new DropEvent(UUID.randomUUID(), DropCaptureTest.SESSION, DropCaptureTest.NOW, type, source, 1, List.of(item));
		return DropCaptureResult.observed(type, 1, 0, null, retained, event, retained);
	}
}

package com.runeglass.runelite;

import com.google.gson.JsonObject;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.game.ItemStack;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class DropCountConsentTest
{
	@Rule public TemporaryFolder temporary = new TemporaryFolder();
	private DropHandlerFixture fixture;
	private Path root;

	@Before public void setUp() throws Exception
	{
		root = temporary.newFolder().toPath();
		fixture = new DropHandlerFixture(root);
	}

	@After public void tearDown() throws Exception { fixture.close(); }

	@Test public void existingDropConsentDoesNotSubscribeReadSettingsOrAddEvidence() throws Exception
	{
		assertFalse((Boolean) DropHandlerFixture.getField(fixture.plugin, "dropChatSubscribed"));
		fixture.plugin.onChatMessage(null);
		fixture.eventBus.post(count(100));
		fixture.eventBus.post(newItem());
		fixture.plugin.onVarbitChanged(new VarbitChanged());
		fixture.plugin.onLootReceived(DropLootHandlerTest.loot("Vorkath", new ItemStack(21907, 1)));
		assertLegacy(fixture.takeUpload());
		assertEquals(0, fixture.evidenceReads.get());
		assertFalse(Files.exists(continuity()));
	}

	@Test public void dropMasterAndPairingGatesPreventChatReadsEvenWithCountConsent() throws Exception
	{
		fixture.dropCountSyncEnabled = true;
		fixture.dropSyncEnabled = false;
		fixture.plugin.onChatMessage(null);
		fixture.plugin.advanceDropEvidence();
		fixture.dropSyncEnabled = true;
		fixture.syncEnabled = false;
		fixture.plugin.onChatMessage(null);
		fixture.plugin.advanceDropEvidence();
		fixture.syncEnabled = true;
		DropHandlerFixture.setField(fixture.plugin, "activeCredentials", null);
		fixture.plugin.onChatMessage(null);
		fixture.plugin.advanceDropEvidence();
		assertFalse((Boolean) DropHandlerFixture.getField(fixture.plugin, "dropChatSubscribed"));
		assertEquals(0, fixture.evidenceReads.get());
		assertFalse(Files.exists(continuity()));
		assertNull(fixture.server.takeRequest(100, TimeUnit.MILLISECONDS));
	}

	@Test public void revocationUnsubscribesDeletesContinuityAndKeepsBufferedDropWithoutEvidence() throws Exception
	{
		fixture.enableCounts();
		assertTrue((Boolean) DropHandlerFixture.getField(fixture.plugin, "dropChatSubscribed"));
		fixture.eventBus.post(count(100));
		fixture.plugin.onLootReceived(DropLootHandlerTest.loot("Vorkath", new ItemStack(21907, 1)));
		fixture.eventBus.post(newItem());
		assertTrue(fixture.takeUpload().has("sourceCount"));
		fixture.drainTransport();
		assertTrue(Files.exists(continuity()));
		fixture.eventBus.post(count(101));
		DropCaptureResult buffered = fixture.plugin.handleLoot(DropLootHandlerTest.loot("Vorkath", new ItemStack(21907, 1)));
		fixture.eventBus.post(newItem());
		int reads = fixture.evidenceReads.get();
		fixture.changeCountConsent(false);
		assertFalse((Boolean) DropHandlerFixture.getField(fixture.plugin, "dropChatSubscribed"));
		assertFalse(Files.exists(continuity()));
		fixture.plugin.onChatMessage(null);
		fixture.eventBus.post(count(102));
		fixture.eventBus.post(newItem());
		fixture.plugin.onVarbitChanged(new VarbitChanged());
		JsonObject uploaded = fixture.takeUpload();
		assertEquals(buffered.event().get().eventId(), uploaded.get("eventId").getAsString());
		assertLegacy(uploaded);
		assertEquals(reads, fixture.evidenceReads.get());
		assertFalse(Files.exists(continuity()));
		fixture.changeCountConsent(true);
		assertTrue((Boolean) DropHandlerFixture.getField(fixture.plugin, "dropChatSubscribed"));
		fixture.tick += 6;
		fixture.plugin.advanceDropEvidence();
		fixture.eventBus.post(count(103));
		DropCaptureResult resumedDrop = fixture.plugin.handleLoot(DropLootHandlerTest.loot("Vorkath", new ItemStack(21907, 1)));
		JsonObject resumed;
		do
		{
			resumed = fixture.takeUpload();
			assertNotNull(resumed);
		}
		while (!resumedDrop.event().get().eventId().equals(resumed.get("eventId").getAsString()));
		assertEquals(103, resumed.getAsJsonObject("sourceCount").get("value").getAsInt());
		assertEquals(103, resumed.getAsJsonObject("continuity").get("from").getAsInt());
	}

	@Test public void configEventStopsCollectionBeforeDeferredClientThreadWork() throws Exception
	{
		fixture.enableCounts();
		fixture.eventBus.post(count(100));
		fixture.plugin.onLootReceived(DropLootHandlerTest.loot("Vorkath", new ItemStack(21907, 1)));
		assertTrue(fixture.takeUpload().has("sourceCount"));
		fixture.drainTransport();
		assertTrue(Files.exists(continuity()));
		java.util.concurrent.atomic.AtomicReference<Runnable> deferred = new java.util.concurrent.atomic.AtomicReference<>();
		DropHandlerFixture.setField(fixture.plugin, "clientThread", new net.runelite.client.callback.ClientThread()
		{
			@Override public void invokeLater(Runnable task) { deferred.set(task); }
		});
		fixture.changeCountConsent(false);
		assertNotNull(deferred.get());
		assertFalse(fixture.dropClient.isConnected());
		assertFalse((Boolean) DropHandlerFixture.getField(fixture.plugin, "dropChatSubscribed"));
		fixture.plugin.onChatMessage(null);
		assertFalse(Files.exists(continuity()));
		deferred.get().run();
		fixture.drainTransport();
		assertTrue(fixture.dropClient.isConnected());
	}

	@Test public void quickOffOnCannotRestoreEvidenceFromARevokedBufferedDrop() throws Exception
	{
		fixture.enableCounts();
		fixture.eventBus.post(count(100));
		DropCaptureResult buffered = fixture.plugin.handleLoot(DropLootHandlerTest.loot("Vorkath", new ItemStack(21907, 1)));
		fixture.eventBus.post(newItem());
		java.util.List<Runnable> deferred = new java.util.ArrayList<>();
		DropHandlerFixture.setField(fixture.plugin, "clientThread", new net.runelite.client.callback.ClientThread()
		{
			@Override public void invokeLater(Runnable task) { deferred.add(task); }
		});
		fixture.changeCountConsent(false);
		fixture.changeCountConsent(true);
		assertFalse(fixture.dropClient.isConnected());
		deferred.forEach(Runnable::run);
		fixture.drainTransport();
		JsonObject uploaded = fixture.takeUpload();
		assertEquals(buffered.event().get().eventId(), uploaded.get("eventId").getAsString());
		assertLegacy(uploaded);
		assertFalse(Files.exists(continuity()));
	}

	static void assertLegacy(JsonObject event)
	{
		assertNotNull(event);
		assertEquals(Set.of("eventId", "sessionId", "occurredAt", "source", "rollCount", "items"), event.keySet());
		assertEquals(Set.of("type", "name"), event.getAsJsonObject("source").keySet());
		event.getAsJsonArray("items").forEach(item -> assertFalse(item.getAsJsonObject().has("newCollectionLogSlot")));
	}

	private Path continuity() { return root.resolve("drops-v1/connection/" + DropContinuityStore.FILE); }
	private static ChatMessage count(int value)
	{
		return new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", "Your Vorkath kill count is: " + value + ".", null, 0);
	}
	private static ChatMessage newItem()
	{
		return new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", "New item added to your collection log: Fixture item", null, 0);
	}
}

package com.runeglass.runelite;

import org.junit.Test;
import static org.junit.Assert.*;

public class DropCountParserTest
{
	@Test public void upstreamFormatsNormalizeMarkupCommasAndPunctuation()
	{
		assertCount("Your <col=ff0000>Kree'arra</col> kill count is:<col=ff0000>1,130</col>.", "kreearra", 1130, "kill");
		assertCount("Your K'ril Tsutsaroth kill count is: @mes_hl_red@2</col>.", "kril-tsutsaroth", 2, "kill");
		assertCount("Your Nightmare kill count is: 12", "nightmare", 12, "kill");
		assertCount("Your Barrows chest count is: 277.", "barrows-chests", 277, "chest");
		assertCount("Your Corrupted Gauntlet completion count is: 4729.", "the-corrupted-gauntlet", 4729, "completion");
		assertCount("Your subdued Wintertodt count is: 4.", "wintertodt", 4, "completion");
		assertCount("Your Tempoross kill count is: 60.", "tempoross", 60, "completion");
	}

	@Test public void everyRegisteredCounterHasAParserPathWithoutDependingOnRatedItems()
	{
		for (DropCounterRegistry.Counter counter : DropCounterRegistry.COUNTERS)
		{
			String source = counter.aliases.get(0);
			assertCount("Your completion count for " + source + " is: 123.", counter.key, 123, counter.unit);
		}
	}

	@Test public void modeAndTierStayDistinct()
	{
		assertCount("Your completed Chambers of Xeric Challenge Mode count is: 13.", "chambers-of-xeric-challenge-mode", 13, "completion");
		assertCount("Your completed Theatre of Blood: Entry Mode count is: 73.", "theatre-of-blood-entry-mode", 73, "completion");
		assertCount("Your completed Theatre of Blood: Hard Mode count is: 23.", "theatre-of-blood-hard-mode", 23, "completion");
		for (String mode : new String[]{"", ": Entry Mode", ": Expert Mode"})
			assertCount("Your completed Tombs of Amascut" + mode + " count is: 3.", DropCounterRegistry.normalize("Tombs of Amascut" + mode), 3, "completion");
		for (String tier : new String[]{"beginner", "easy", "medium", "hard", "elite", "master"})
		{
			assertCount("You have completed 1 " + tier + " Treasure Trail.", "clue-scrolls-" + tier, 1, "casket");
			assertCount("You have completed 1,234 " + tier + " Treasure Trails.", "clue-scrolls-" + tier, 1234, "casket");
		}
	}

	@Test public void rejectsUnknownSeasonalAndMalformedMessages()
	{
		for (String message : new String[]{
			"Your Vorkath count is: 4.", "Your loot is worth 4 coins.", "Other player: Your Vorkath kill count is: 4.",
			"Your Corrupted Hunllef (Echo) kill count is: 4.", "Your completed Theatre of Blood: Story Mode count is: 4.",
			"Your Vorkath kill count is: 1,23.", "Your Vorkath kill count is: -4.", "Your Vorkath kill count is: 2.5.",
			"Your Vorkath kill count is: 0.", "Your Vorkath kill count is: 2147483648.", "Your mystery kill count is: 4.",
			"You have completed 2 all Treasure Trails."}) assertNull(message, DropCountParser.parse(message));
	}

	@Test public void collectionLogSettingAndItemAreFactsOnly()
	{
		assertEquals("Skeletal visage", DropCountParser.collectionItem("<col=ff0000>New item added to your collection log: Skeletal visage</col>"));
		assertNull(DropCountParser.collectionItem("Other player received Skeletal visage"));
		for (int value : new int[]{1, 3}) assertEquals("enabled", DropGameContext.collectionLogSetting(value));
		for (int value : new int[]{0, 2}) assertEquals("disabled", DropGameContext.collectionLogSetting(value));
		assertEquals("unknown", DropGameContext.collectionLogSetting(-1));
		assertEquals("unknown", DropGameContext.collectionLogSetting(4));
	}

	private static void assertCount(String message, String key, int value, String unit)
	{
		DropCountParser.Count count = DropCountParser.parse(message);
		assertNotNull(message, count);
		assertEquals(key, count.counter.key); assertEquals(value, count.value); assertEquals(unit, count.counter.unit);
	}
}

package com.runeglass.runelite;

import org.junit.Test;
import static org.junit.Assert.*;

public class DropGameContextTest
{
	@Test public void raidTokensRequireBothKnownRegionAndGameState()
	{
		assertEquals("Chambers of Xeric", DropGameContext.raidFamily(12889, 1, 1, 0, 0));
		assertEquals("Theatre of Blood", DropGameContext.raidFamily(12867, 0, 0, 2, 0));
		assertEquals("Tombs of Amascut", DropGameContext.raidFamily(14160, 0, 0, 0, 2));
		assertNull(DropGameContext.raidFamily(12889, 1, 0, 0, 0));
		assertNull(DropGameContext.raidFamily(12867, 0, 0, 1, 0));
		assertNull(DropGameContext.raidFamily(9999, 1, 1, 2, 2));
		assertNull(DropGameContext.raidFamily(14642, 0, 0, 2, 0));
	}

	@Test public void changingRegionFamilyOrLeavingRaidInvalidatesEncounterIdentity()
	{
		DropGameContext context = new DropGameContext();
		String first = context.update("Chambers of Xeric");
		assertEquals(first, context.update("Chambers of Xeric"));
		assertNull(context.update(null));
		assertNotEquals(first, context.update("Chambers of Xeric"));
		context.clear();
		assertNotEquals(first, context.update("Chambers of Xeric"));
		assertTrue(context.update("Tombs of Amascut").startsWith("Tombs of Amascut:"));
	}
}

