import net.runelite.api.WorldType;
import net.runelite.client.account.SessionManager;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigClient;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ProfileManager;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.game.ItemClient;
import net.runelite.client.game.ItemManager;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.Dispatcher;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;

final class DropHandlerFixture implements AutoCloseable
{
	static final PairingClient.Credentials CREDENTIALS = new PairingClient.Credentials("connection", "r".repeat(43));
	static final UUID SESSION = DropCaptureTest.SESSION;

	final RuneGlassPlugin plugin = new RuneGlassPlugin();
	final MockWebServer server = new MockWebServer();
	final ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();
	final BlockingQueue<JsonObject> uploads = new LinkedBlockingQueue<>();
	final List<String> statuses = new CopyOnWriteArrayList<>();
	final AtomicInteger definitionReads = new AtomicInteger();
	final Map<Integer, ItemComposition> definitions = new ConcurrentHashMap<>();
	final DropClient dropClient;
	final ConfigManager configManager;
	volatile int tick = 100;
	volatile int collectionLogSetting = 1;
	volatile boolean syncEnabled = true;
	volatile boolean dropSyncEnabled = true;
	volatile boolean dropCountSyncEnabled;
	final EventBus eventBus = new EventBus();
	final AtomicInteger evidenceReads = new AtomicInteger();
	volatile GameState gameState = GameState.LOGGED_IN;
	volatile EnumSet<WorldType> worldTypes = EnumSet.noneOf(WorldType.class);

	DropHandlerFixture(Path root) throws Exception
	{
		Gson gson = new Gson();
		server.setDispatcher(new Dispatcher()
		{
			@Override public MockResponse dispatch(RecordedRequest request)
			{
				JsonObject body = gson.fromJson(request.getBody().readUtf8(), JsonObject.class);
				JsonArray ids = new JsonArray();
				for (JsonElement event : body.getAsJsonArray("events"))
				{
					uploads.add(event.getAsJsonObject());
					ids.add(event.getAsJsonObject().get("eventId"));
				}
				JsonObject result = new JsonObject();
				result.addProperty("protocolVersion", 1);
				result.addProperty("status", "accepted");
				result.add("acceptedEventIds", ids);
				result.addProperty("serverTime", "2026-10-13T12:00:00Z");
				result.addProperty("nextUploadAfterSeconds", 1);
				return new MockResponse().setBody(gson.toJson(result));
			}
		});
		server.start();
		definitions.put(995, DropCaptureTest.definition(995, true, -1, -1));
		definitions.put(4151, DropCaptureTest.definition(4151, true, -1, -1));
		definitions.put(1127, DropCaptureTest.definition(1127, true, -1, -1));
		definitions.put(21907, DropCaptureTest.definition(21907, false, -1, -1));
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			switch (method.getName())
			{
				case "getGameState": return gameState;
				case "getWorldType": return worldTypes;
				case "isClientThread": return true;
				case "getTopLevelWorldView": return null;
				case "getTickCount": return tick;
				case "getVarbitValue":
					if ((Integer) args[0] == net.runelite.api.gameval.VarbitID.IRONMAN) return 0;
					evidenceReads.incrementAndGet(); return collectionLogSetting;
				case "getRevision": return 231;
				case "getLocalPlayer":
					return Proxy.newProxyInstance(net.runelite.api.Player.class.getClassLoader(),
						new Class<?>[]{net.runelite.api.Player.class}, (player, getter, arguments) ->
						{
							if (getter.getName().equals("getName")) return "Fixture";
							throw new AssertionError("Unexpected player read " + getter.getName());
						});
				case "getItemDefinition":
					definitionReads.incrementAndGet();
					return definitions.get((Integer) args[0]);
				default: throw new AssertionError("Unexpected client read " + method.getName());
			}
		});
		RuneGlassConfig config = new RuneGlassConfig()
		{
			@Override public boolean syncEnabled() { return syncEnabled; }
			@Override public boolean dropSyncEnabled() { return dropSyncEnabled; }
			@Override public boolean dropCountSyncEnabled() { return dropCountSyncEnabled; }
		};
		Constructor<ConfigManager> configConstructor = ConfigManager.class.getDeclaredConstructor(String.class,
			ScheduledExecutorService.class, EventBus.class, Client.class, Gson.class,
			ConfigClient.class, ProfileManager.class, SessionManager.class);
		configConstructor.setAccessible(true);
		configManager = configConstructor.newInstance(null, executor, new EventBus(), client, gson, null, null, null);
		setField(configManager, "rsProfileKey", "fixture-profile");
		ScheduledExecutorService inert = (ScheduledExecutorService) Proxy.newProxyInstance(
			ScheduledExecutorService.class.getClassLoader(), new Class<?>[]{ScheduledExecutorService.class}, (proxy, method, args) -> null);
		Constructor<ItemManager> itemConstructor = ItemManager.class.getDeclaredConstructor(Client.class,
			ScheduledExecutorService.class, ClientThread.class, EventBus.class, ItemClient.class, RuneLiteConfig.class);
		itemConstructor.setAccessible(true);
		ItemManager itemManager = itemConstructor.newInstance(client, inert, null, new EventBus(), null, null);
		dropClient = new DropClient(new OkHttpClient(), gson, executor, server.url("/runelite/v1/drops"),
			TestStorage.rooted(root).joinSegment("drops-v1"), new DropClient.Listener()
		{
			@Override public void onStatus(String status) { statuses.add(status); }
			@Override public void onInvalidConnection(PairingClient.Credentials credentials, boolean bindingMismatch) { }
		});
		setField(plugin, "client", client);
		setField(plugin, "eventBus", eventBus);
		setField(plugin, "clientThread", new ClientThread()
		{
			@Override public void invokeLater(Runnable task) { task.run(); }
		});
		setField(plugin, "config", config);
		setField(plugin, "configManager", configManager);
		setField(plugin, "itemManager", itemManager);
		setField(plugin, "dropClient", dropClient);
		setField(plugin, "activeCredentials", CREDENTIALS);
		setField(plugin, "activeProfileKey", "fixture-profile");
		setField(plugin, "syncSessionId", SESSION);
		setField(plugin, "lootTrackerRunning", true);
		((SkillsSyncSession) getField(plugin, "session")).start();
		dropClient.connect(CREDENTIALS, DropCaptureTest.CONTEXT);
		drainTransport();
		plugin.advanceDropEvidence();
		tick += 6;
		plugin.advanceDropEvidence();
	}

	void changeCountConsent(boolean enabled) throws Exception
	{
		dropCountSyncEnabled = enabled;
		net.runelite.client.events.ConfigChanged event = new net.runelite.client.events.ConfigChanged();
		event.setGroup(RuneGlassConfig.GROUP);
		event.setKey("dropCountSyncEnabled");
		event.setNewValue(Boolean.toString(enabled));
		plugin.onConfigChanged(event);
		drainTransport();
	}

	void enableCounts() throws Exception
	{
		dropCountSyncEnabled = true;
		dropClient.connect(CREDENTIALS, DropCaptureTest.CONTEXT, "fixture-profile", true);
		drainTransport();
		plugin.advanceDropEvidence();
		tick += 6;
		plugin.advanceDropEvidence();
	}

	void drainTransport() throws Exception
	{
		executor.submit(() -> { }).get(10, TimeUnit.SECONDS);
	}

	JsonObject takeUpload() throws InterruptedException
	{
		tick += 11;
		plugin.advanceDropEvidence();
		return uploads.poll(3, TimeUnit.SECONDS);
	}

	@Override
	public void close() throws java.io.IOException
	{
		dropClient.pause();
		executor.shutdownNow();
		server.shutdown();
	}

	static void setField(Object target, String name, Object value) throws Exception
	{
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}

	static Object getField(Object target, String name) throws Exception
	{
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		return field.get(target);
	}
}

package com.runeglass.runelite;

import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.concurrent.TimeUnit;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;

public class DropLootHandlerTest
{
	@Rule public TemporaryFolder temporary = new TemporaryFolder();
	private DropHandlerFixture fixture;

	@Before public void setUp() throws Exception
	{
		fixture = new DropHandlerFixture(temporary.newFolder().toPath());
	}

	@After public void tearDown() throws Exception
	{
		fixture.close();
	}

	@Test public void actualChatHandlerIgnoresPlayersAndCorrelatesGameFactsBeforeLocalSave() throws Exception
	{
		fixture.enableCounts();
		fixture.eventBus.post(new net.runelite.api.events.ChatMessage(null, net.runelite.api.ChatMessageType.PUBLICCHAT,
			"Other player", "Your Vorkath kill count is: 999.", null, 0));
		fixture.eventBus.post(new net.runelite.api.events.ChatMessage(null, net.runelite.api.ChatMessageType.GAMEMESSAGE,
			"", "Your Vorkath kill count is: 100.", null, 0));
		LootReceived loot = loot("Vorkath", new ItemStack(21907, 1));
		fixture.plugin.onLootReceived(loot);
		fixture.plugin.onLootReceived(loot);
		fixture.eventBus.post(new net.runelite.api.events.ChatMessage(null, net.runelite.api.ChatMessageType.GAMEMESSAGE,
			"", "New item added to your collection log: Fixture item", null, 0));
		fixture.drainTransport();
		assertNull(fixture.uploads.poll(100, TimeUnit.MILLISECONDS));
		JsonObject saved = fixture.takeUpload();
		assertNotNull(saved);
		assertEquals(100, saved.getAsJsonObject("sourceCount").get("value").getAsInt());
		assertEquals("enabled", saved.get("collectionLog").getAsString());
		assertTrue(saved.getAsJsonArray("items").get(0).getAsJsonObject().get("newCollectionLogSlot").getAsBoolean());
		assertNull(fixture.uploads.poll(100, TimeUnit.MILLISECONDS));
	}

	@Test public void everyGuardReportsItsReasonWithoutReadingTheLoot() throws Exception
	{
		assertBlocked(DropCaptureResult.Reason.SYNC_OFF, () -> fixture.syncEnabled = false, () -> fixture.syncEnabled = true);
		assertBlocked(DropCaptureResult.Reason.DROP_SYNC_OFF, () -> fixture.dropSyncEnabled = false, () -> fixture.dropSyncEnabled = true);
		assertBlocked(DropCaptureResult.Reason.LOOT_TRACKER_OFF, () -> set("lootTrackerRunning", false), () -> set("lootTrackerRunning", true));
		assertBlocked(DropCaptureResult.Reason.LOGGED_OUT, () -> fixture.gameState = GameState.LOGIN_SCREEN, () -> fixture.gameState = GameState.LOGGED_IN);
		assertBlocked(DropCaptureResult.Reason.SESSION_INACTIVE, () -> set("syncSessionId", null), () -> set("syncSessionId", DropHandlerFixture.SESSION));
		LoginBaselineGate gate = (LoginBaselineGate) DropHandlerFixture.getField(fixture.plugin, "baselineGate");
		assertBlocked(DropCaptureResult.Reason.BASELINE_PENDING, gate::arm, gate::cancel);
		assertBlocked(DropCaptureResult.Reason.PROFILE_CHANGED, () -> set("activeProfileKey", "other-profile"), () -> set("activeProfileKey", "fixture-profile"));
		assertBlocked(DropCaptureResult.Reason.NOT_PAIRED, () -> set("activeCredentials", null), () -> set("activeCredentials", DropHandlerFixture.CREDENTIALS));
		assertBlocked(DropCaptureResult.Reason.UNSUPPORTED_PROFILE, () -> fixture.worldTypes = EnumSet.of(WorldType.SEASONAL),
			() -> fixture.worldTypes = EnumSet.noneOf(WorldType.class));
		assertBlocked(DropCaptureResult.Reason.TRANSPORT_NOT_READY, fixture.dropClient::pause,
			() -> { fixture.dropClient.connect(DropHandlerFixture.CREDENTIALS, DropCaptureTest.CONTEXT); fixture.drainTransport(); });
		assertBlocked(DropCaptureResult.Reason.PLUGIN_STOPPED, () -> set("dropClient", null), () -> set("dropClient", fixture.dropClient));
		assertEquals(0, fixture.definitionReads.get());
		assertNull(fixture.server.takeRequest(250, TimeUnit.MILLISECONDS));
		assertEquals(DropCaptureResult.Reason.ELIGIBLE, fixture.plugin.handleLoot(coins(50_000)).reason());
	}

	@Test public void exactCoinBoundaryIsFilteredOrSubmittedThroughTheRealHandler() throws Exception
	{
		DropCaptureResult low = fixture.plugin.handleLoot(coins(49_999));
		assertEquals(DropCaptureResult.Reason.BELOW_THRESHOLD, low.reason());
		assertEquals(Long.valueOf(49_999), low.highestStackGp().get());
		assertFalse(low.event().isPresent());

		DropCaptureResult kept = fixture.plugin.handleLoot(coins(50_000));
		assertEquals(DropCaptureResult.Stage.ELIGIBLE, kept.stage());
		JsonObject uploaded = fixture.takeUpload();
		assertEquals(kept.event().get().eventId(), uploaded.get("eventId").getAsString());
		assertEquals(50_000, uploaded.getAsJsonArray("items").get(0).getAsJsonObject().get("quantity").getAsInt());
		assertNull(fixture.uploads.poll(250, TimeUnit.MILLISECONDS));
	}

	@Test public void notableUntradeableRewardStillRequiresTheExactSource() throws Exception
	{
		DropCaptureResult exact = fixture.plugin.handleLoot(loot("Vorkath", new ItemStack(21907, 1)));
		assertEquals(DropCaptureResult.Reason.ELIGIBLE, exact.reason());
		assertTrue(exact.notable());
		assertEquals("untradeable", fixture.takeUpload().getAsJsonArray("items").get(0).getAsJsonObject()
			.getAsJsonObject("value").get("kind").getAsString());

		DropCaptureResult renamed = fixture.plugin.handleLoot(loot("RuneGlass TEST not Vorkath", new ItemStack(21907, 1)));
		assertEquals(DropCaptureResult.Reason.BELOW_THRESHOLD, renamed.reason());
		assertFalse(renamed.notable());
	}

	@Test public void observerSeesOnlyEventBusDeliveriesAndBlockedResultsCarryNoLoot() throws Exception
	{
		List<DropCaptureResult> observed = new ArrayList<>();
		fixture.plugin.setDropCaptureObserver(new RuneGlassPlugin.DropCaptureObserver()
		{
			@Override public void onLootHandled(DropCaptureResult result) { observed.add(result); }
			@Override public void onDropStatus(String status) { }
		});
		fixture.plugin.handleLoot(coins(50_000));
		assertTrue(observed.isEmpty());

		fixture.plugin.onLootReceived(coins(1));
		fixture.dropSyncEnabled = false;
		fixture.plugin.onLootReceived(coins(50_000));
		assertEquals(2, observed.size());
		assertEquals(DropCaptureResult.Reason.BELOW_THRESHOLD, observed.get(0).reason());
		DropCaptureResult blocked = observed.get(1);
		assertEquals(DropCaptureResult.Reason.DROP_SYNC_OFF, blocked.reason());
		assertFalse(blocked.sourceType().isPresent());
		assertEquals(0, blocked.itemStacks());
		assertFalse(blocked.highestStackGp().isPresent());
		assertFalse(blocked.event().isPresent());
		fixture.plugin.setDropCaptureObserver(null);
		fixture.plugin.onLootReceived(coins(1));
		assertEquals(2, observed.size());
	}

	@Test public void unsafeRewardsReportInvalidAndMarkTheGap() throws Exception
	{
		fixture.definitions.remove(4151);
		assertEquals(DropCaptureResult.Reason.INVALID_REWARD, fixture.plugin.handleLoot(loot("RuneGlass TEST", new ItemStack(4151, 1))).reason());
		fixture.drainTransport();
		assertTrue(fixture.statuses.stream().anyMatch(status -> status.contains("could not be captured safely")));
	}

	@Test public void workerRefusalIsNotReportedAsSubmitted() throws Exception
	{
		fixture.executor.shutdown();
		assertTrue(fixture.executor.awaitTermination(3, TimeUnit.SECONDS));
		DropCaptureResult refused = fixture.plugin.handleLoot(coins(50_000));
		assertEquals(DropCaptureResult.Reason.ELIGIBLE, refused.reason());
		assertTrue(refused.event().isPresent());
		assertNull(fixture.takeUpload());
		assertTrue(fixture.statuses.stream().anyMatch(status -> status.contains("background storage is unavailable")));
	}

	private void assertBlocked(DropCaptureResult.Reason reason, Step block, Step restore) throws Exception
	{
		block.run();
		DropCaptureResult result = fixture.plugin.handleLoot(coins(50_000));
		assertEquals(reason, result.reason());
		assertEquals(DropCaptureResult.Stage.BLOCKED, result.stage());
		assertFalse(result.sourceType().isPresent());
		assertFalse(result.event().isPresent());
		restore.run();
	}

	private void set(String field, Object value) throws Exception
	{
		DropHandlerFixture.setField(fixture.plugin, field, value);
	}

	static LootReceived coins(int quantity)
	{
		return loot("RuneGlass TEST coins boundary", new ItemStack(995, quantity));
	}

	static LootReceived loot(String source, ItemStack... items)
	{
		return new LootReceived(source, 0, LootRecordType.NPC, List.of(items), 1, null);
	}

	private interface Step
	{
		void run() throws Exception;
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;
import static org.junit.Assume.assumeTrue;

public class DurableDropQueueTest
{
	@Rule public TemporaryFolder temporary = new TemporaryFolder();
	private final Gson gson = new Gson();

	@Test public void restartRetainsImmutableIdsContentAndCaptureSession() throws Exception
	{
		Filepath root = root();
		DurableDropQueue queue = new DurableDropQueue(root, "connection", gson);
		JsonObject first = DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection");
		JsonObject second = DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection");
		queue.append(first);
		queue.append(second);
		DurableDropQueue restored = new DurableDropQueue(root, "connection", gson);
		assertEquals(2, restored.size());
		assertEquals(first, restored.batch(false).get(0).body);
		assertEquals(second, restored.batch(false).get(1).body);
		List<DurableDropQueue.Entry> batch = restored.batch(false);
		restored.acknowledge(batch, Set.of(batch.get(1).id()));
		assertEquals(first, new DurableDropQueue(root, "connection", gson).batch(false).get(0).body);
	}

	@Test public void countEvidenceRoundTripsAlongsideLegacyEventsAndRejectsInvalidExtensions() throws Exception
	{
		Filepath root = root();
		DurableDropQueue queue = new DurableDropQueue(root, "connection", gson);
		JsonObject legacy = DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection");
		DropEvent captured = DropCorrelatorTest.drop("npc", "Vorkath", true).event().get();
		JsonObject continuity = new JsonObject(); continuity.addProperty("id", java.util.UUID.randomUUID().toString()); continuity.addProperty("from", 100);
		JsonObject current = captured.freeze(new DropCountParser.Count(DropCounterRegistry.byKey("vorkath"), 1200),
			continuity, "enabled", Set.of(22006)).envelope(DropCaptureTest.CONTEXT, "connection");
		queue.append(legacy); queue.append(current);
		DropContinuityStore state = new DropContinuityStore(root.joinSegment("connection"), gson, "profile");
		state.observe(new DropCountParser.Count(DropCounterRegistry.byKey("vorkath"), 1200)); state.save();
		DurableDropQueue restored = new DurableDropQueue(root, "connection", gson);
		assertFalse(restored.hasDamagedRecords()); assertEquals(2, restored.size());
		assertEquals(legacy, restored.batch(false).get(0).body); assertEquals(current, restored.batch(false).get(1).body);
		for (String field : List.of("sourceCount", "continuity", "collectionLog"))
		{
			JsonObject bad = current.deepCopy(); DropCaptureTest.event(bad).add(field, com.google.gson.JsonNull.INSTANCE);
			assertThrows(Exception.class, () -> queue.append(bad));
		}
		for (String field : List.of("computedLuck", "waitingInterval", "firstCopy", "rawChat"))
		{
			JsonObject bad = current.deepCopy(); DropCaptureTest.event(bad).addProperty(field, true);
			assertThrows(java.io.IOException.class, () -> queue.append(bad));
		}
		JsonObject mismatch = current.deepCopy(); DropCaptureTest.event(mismatch).getAsJsonObject("sourceCount").addProperty("counterKey", "zulrah");
		assertThrows(java.io.IOException.class, () -> queue.append(mismatch));
		JsonObject invalidFrom = current.deepCopy(); DropCaptureTest.event(invalidFrom).getAsJsonObject("continuity").addProperty("from", 1201);
		assertThrows(java.io.IOException.class, () -> queue.append(invalidFrom));
		JsonObject invalidFlag = current.deepCopy(); DropCaptureTest.event(invalidFlag).getAsJsonArray("items").get(0).getAsJsonObject().addProperty("newCollectionLogSlot", "true");
		assertThrows(java.io.IOException.class, () -> queue.append(invalidFlag));
		assertEquals(2, queue.size());
	}

	@Test public void countRevocationLeavesLegacyPayloadAndDiskBytesIdentical() throws Exception
	{
		Filepath root = root().joinSegment("drops-v1");
		DurableDropQueue queue = new DurableDropQueue(root, "connection", gson);
		DropEvent event = DropCaptureTest.notedDrop(123);
		JsonObject original = event.envelope(DropCaptureTest.CONTEXT, "connection");
		assertEquals(gson.toJson(original), gson.toJson(event.withoutCountEvidence().envelope(DropCaptureTest.CONTEXT, "connection")));
		queue.append(original);
		Path path = TestStorage.path(queue.batch(false).get(0).path);
		String unusualWhitespace = "\n " + Files.readString(path) + "\n";
		Files.writeString(path, unusualWhitespace);
		DurableDropQueue.stripCountEvidence(root, gson);
		assertEquals(unusualWhitespace, Files.readString(path));
		assertEquals(original, new DurableDropQueue(root, "connection", gson).batch(false).get(0).body);
		assertFalse(root.joinSegment("connection").joinSegment(DropContinuityStore.FILE).exists());
	}

	@Test public void damagedRecordDoesNotDestroyOrBlockHealthyRecords() throws Exception
	{
		Filepath root = root();
		DurableDropQueue queue = new DurableDropQueue(root, "connection", gson);
		queue.append(DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection"));
		Path corrupted = TestStorage.path(root).resolve("connection").resolve("bad.json");
		Files.writeString(corrupted, "broken");
		DurableDropQueue restored = new DurableDropQueue(root, "connection", gson);
		assertTrue(restored.hasDamagedRecords());
		assertEquals(1, restored.size());
		assertTrue(Files.exists(corrupted));
		restored.block(restored.batch(false).get(0));
		assertEquals(0, new DurableDropQueue(root, "connection", gson).size());
		assertEquals(2, names(TestStorage.path(root).resolve("connection")).size());
	}

	@Test public void marketIdSurvivesCapturePersistenceRestartBatchAndAcknowledgementWithLegacyItems() throws Exception
	{
		Filepath root = root();
		DurableDropQueue queue = new DurableDropQueue(root, "connection", gson);
		JsonObject coins = DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection");
		JsonObject legacy = DropCaptureTest.notedDrop(123).envelope(DropCaptureTest.CONTEXT, "connection");
		DropCaptureTest.event(legacy).getAsJsonArray("items").get(0).getAsJsonObject().remove("marketItemId");
		JsonObject current = DropCaptureTest.notedDrop(0).envelope(DropCaptureTest.CONTEXT, "connection");
		List<JsonObject> bodies = List.of(coins, legacy, current);
		for (JsonObject body : bodies) queue.append(body);
		DurableDropQueue restored = new DurableDropQueue(root, "connection", gson);
		assertFalse(restored.hasDamagedRecords());
		assertEquals(3, restored.size());
		List<DurableDropQueue.Entry> batch = restored.batch(false);
		JsonObject payload = gson.fromJson(gson.toJson(DurableDropQueue.payload(batch)), JsonObject.class);
		for (int index = 0; index < bodies.size(); index++)
		{
			assertEquals(bodies.get(index).toString(), batch.get(index).body.toString());
			assertEquals(DropCaptureTest.event(bodies.get(index)), payload.getAsJsonArray("events").get(index));
		}
		restored.acknowledge(batch, Set.of(batch.get(2).id()));
		DurableDropQueue remaining = new DurableDropQueue(root, "connection", gson);
		assertEquals(2, remaining.size());
		assertEquals(legacy, remaining.batch(false).get(1).body);
	}

	@Test public void rejectsInvalidMarketIdsAndUnexpectedFieldsBeforePersistence() throws Exception
	{
		DurableDropQueue queue = new DurableDropQueue(root(), "connection", gson);
		for (String raw : List.of("0", "-1", "995", "2147483648", "1.5", "null", "true", "\"22124\"", "{}", "[]"))
		{
			JsonObject body = DropCaptureTest.notedDrop(0).envelope(DropCaptureTest.CONTEXT, "connection");
			DropCaptureTest.event(body).getAsJsonArray("items").get(0).getAsJsonObject()
				.add("marketItemId", gson.fromJson(raw, com.google.gson.JsonElement.class));
			assertThrows(raw, java.io.IOException.class, () -> queue.append(body));
		}
		for (String kind : List.of("coins", "untradeable"))
		{
			JsonObject body = DropCaptureTest.notedDrop(0).envelope(DropCaptureTest.CONTEXT, "connection");
			JsonObject item = DropCaptureTest.event(body).getAsJsonArray("items").get(0).getAsJsonObject();
			item.addProperty("itemId", "coins".equals(kind) ? 995 : 22125);
			item.getAsJsonObject("value").addProperty("kind", kind);
			assertThrows(java.io.IOException.class, () -> queue.append(body));
		}
		for (boolean withMarketId : List.of(false, true))
		{
			JsonObject body = DropCaptureTest.notedDrop(0).envelope(DropCaptureTest.CONTEXT, "connection");
			JsonObject item = DropCaptureTest.event(body).getAsJsonArray("items").get(0).getAsJsonObject();
			if (!withMarketId) item.remove("marketItemId");
			item.addProperty("unexpected", 1);
			assertThrows(java.io.IOException.class, () -> queue.append(body));
		}
		assertEquals(0, queue.size());
		JsonObject maximum = DropCaptureTest.notedDrop(0).envelope(DropCaptureTest.CONTEXT, "connection");
		DropCaptureTest.event(maximum).getAsJsonArray("items").get(0).getAsJsonObject().addProperty("marketItemId", Integer.MAX_VALUE);
		queue.append(maximum);
		assertEquals(maximum, queue.batch(false).get(0).body);
	}

	@Test public void boundedBatchSplitsByCountAndUtf8BytesWithoutDroppingEvents() throws Exception
	{
		Filepath root = root();
		DurableDropQueue queue = new DurableDropQueue(root, "connection", gson);
		for (int i = 0; i < 23; i++) queue.append(DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection"));
		assertEquals(20, queue.batch(false).size());
		Set<String> ids = new HashSet<>();
		queue.batch(false).forEach(entry -> ids.add(entry.id()));
		queue.acknowledge(queue.batch(false), ids);
		assertEquals(3, queue.size());
		JsonObject large = DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection");
		JsonArray items = DropCaptureTest.event(large).getAsJsonArray("items");
		items.remove(0);
		for (int i = 1; i <= 64; i++)
		{
			JsonObject item = new JsonObject();
			item.addProperty("itemId", i);
			item.addProperty("itemName", "界".repeat(120));
			item.addProperty("quantity", 1);
			JsonObject value = new JsonObject(); value.addProperty("kind", "unknown"); item.add("value", value);
			items.add(item);
		}
		for (int i = 0; i < 4; i++)
		{
			DropCaptureTest.event(large).addProperty("eventId", java.util.UUID.randomUUID().toString());
			queue.append(large);
		}
		List<DurableDropQueue.Entry> batch = queue.batch(false);
		assertTrue(batch.size() < queue.size());
		assertTrue(gson.toJson(DurableDropQueue.payload(batch)).getBytes(java.nio.charset.StandardCharsets.UTF_8).length <= 64 * 1024);
		assertEquals(7, queue.size());
	}

	@Test public void queueCapacityKeepsPreviouslySavedEvents() throws Exception
	{
		Filepath root = root();
		DurableDropQueue queue = new DurableDropQueue(root, "connection", gson);
		queue.append(DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection"));
		Files.write(TestStorage.path(root).resolve("connection").resolve("blocked.bin"), new byte[(int) DurableDropQueue.MAX_BYTES]);
		DurableDropQueue full = new DurableDropQueue(root, "connection", gson);
		try { full.append(DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection")); fail(); }
		catch (DurableDropQueue.CapacityException expected) { assertEquals(1, full.size()); }
		assertEquals(1, new DurableDropQueue(root, "connection", gson).size());
	}
	@Test public void failedAtomicWritePreservesPreviouslyCommittedDrop() throws Exception
	{
		Filepath root = root();
		DurableDropQueue queue = new DurableDropQueue(root, "connection", gson);
		queue.append(DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection"));
		JsonObject next = DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection");
		String nextId = DropCaptureTest.event(next).get("eventId").getAsString();
		Path directory = TestStorage.path(root).resolve("connection");
		Path blocker = directory.resolve("00000000000000000002-" + nextId + ".json");
		Files.createDirectories(blocker.resolve("occupied"));
		try { queue.append(next); fail(); }
		catch (java.io.IOException expected) { assertEquals(1, queue.size()); }
		assertTrue(names(directory).stream().noneMatch(name -> name.endsWith(".tmp")));
		TestStorage.rooted(blocker).deleteRecursively();
		DurableDropQueue restored = new DurableDropQueue(root, "connection", gson);
		assertEquals(1, restored.size());
		assertFalse(restored.hasDamagedRecords());
	}

	@Test public void committedRecordsAreOwnerOnlyAndInterruptedWritesStayVisibleAsDamage() throws Exception
	{
		Filepath root = root();
		DurableDropQueue queue = new DurableDropQueue(root, "connection", gson);
		JsonObject body = DropCaptureTest.drop().envelope(DropCaptureTest.CONTEXT, "connection");
		queue.append(body);
		Path directory = TestStorage.path(root).resolve("connection");
		List<String> committed = names(directory);
		assertEquals(1, committed.size());
		assertTrue(committed.get(0).matches("[0-9]{20}-[a-f0-9-]{36}\\.json"));
		assertEquals(List.of("connection"), names(TestStorage.path(root)));
		Files.writeString(directory.resolve(committed.get(0) + ".4812.tmp"), "partial");
		DurableDropQueue restored = new DurableDropQueue(root, "connection", gson);
		assertTrue(restored.hasDamagedRecords());
		assertEquals(body, restored.batch(false).get(0).body);
		assumeTrue(TestStorage.posix());
		assertEquals("rw-------", TestStorage.permissions(directory.resolve(committed.get(0))));
		assertEquals("rwx------", TestStorage.permissions(directory));
	}

	private Filepath root() throws Exception
	{
		return TestStorage.rooted(temporary.newFolder().toPath());
	}

	private static List<String> names(Path directory) throws Exception
	{
		try (Stream<Path> files = Files.list(directory))
		{
			return files.map(file -> file.getFileName().toString()).sorted().collect(Collectors.toList());
		}
	}

}

package com.runeglass.runelite;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;

public class DurableSnapshotQueueTest
{
	private static final Instant STARTED_AT = Instant.parse("2026-08-25T08:00:00Z");

	@Rule
	public TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void persistsSyntheticRecordsInOrderAndDeduplicatesAcrossRestart() throws Exception
	{
		Path directory = temporaryFolder.newFolder("ordered").toPath();
		MutableClock clock = new MutableClock(STARTED_AT);
		DurableSnapshotQueue queue = queue(directory, clock);

		assertTrue(queue.enqueue("record-1", "{\"synthetic\":1}").wasAdded());
		clock.advance(Duration.ofSeconds(1));
		assertTrue(queue.enqueue("record-2", "{\"synthetic\":2}").wasAdded());
		assertFalse(queue.enqueue("record-1", "{\"synthetic\":1}").wasAdded());

		DurableSnapshotQueue restored = queue(directory, clock);
		assertEquals(2, restored.size());
		assertEquals("record-1", restored.peek().orElseThrow(AssertionError::new).getRecordId());
		assertThrows(IllegalStateException.class, () -> restored.acknowledge("record-2"));
		restored.acknowledge("record-1");
		assertEquals("record-2", restored.peek().orElseThrow(AssertionError::new).getRecordId());
	}

	@Test
	public void discardsTheWholeQueueWhenRetentionWouldCreateASequenceGap() throws Exception
	{
		Path directory = temporaryFolder.newFolder("expiry").toPath();
		MutableClock clock = new MutableClock(STARTED_AT);
		DurableSnapshotQueue queue = queue(directory, clock);
		queue.enqueue("expired", "{\"synthetic\":true}");

		clock.advance(DurableSnapshotQueue.MAX_AGE.plusSeconds(1));
		assertThrows(
			IOException.class,
			() -> queue.enqueue("fresh", "{\"synthetic\":true}"));
		assertEquals(0, queue.size());
		assertFalse(Files.exists(directory.resolve(DurableSnapshotQueue.FILE_NAME)));
	}

	@Test
	public void rejectsCapacityOverflowWithoutEvictingQueuedEntries() throws Exception
	{
		Path directory = temporaryFolder.newFolder("capacity").toPath();
		MutableClock clock = new MutableClock(STARTED_AT);
		DurableSnapshotQueue queue = queue(directory, clock);
		String payload = "x".repeat(220_000);
		int accepted = 0;
		while (true)
		{
			try
			{
				queue.enqueue("record-" + accepted, payload);
				accepted++;
			}
			catch (IOException exception)
			{
				break;
			}
			clock.advance(Duration.ofMillis(1));
		}

		assertTrue(accepted > 0);
		assertEquals(accepted, queue.size());
		assertEquals("record-0", queue.peek().orElseThrow(AssertionError::new).getRecordId());
		assertTrue(Files.size(directory.resolve(DurableSnapshotQueue.FILE_NAME))
			<= DurableSnapshotQueue.MAX_FILE_BYTES);
	}

	@Test
	public void deletesCorruptStateWithoutLoggingOrRetainingItsPayload() throws Exception
	{
		Path directory = temporaryFolder.newFolder("corrupt").toPath();
		Path queueFile = directory.resolve(DurableSnapshotQueue.FILE_NAME);
		Files.write(queueFile, "not-json-private-data".getBytes(StandardCharsets.UTF_8));

		DurableSnapshotQueue queue = queue(directory, new MutableClock(STARTED_AT));

		assertEquals(DurableSnapshotQueue.LoadStatus.RECOVERED_CORRUPTION, queue.getLoadStatus());
		assertEquals(0, queue.size());
		assertFalse(Files.exists(queueFile));
	}

	@Test
	public void consentRevocationDeletesEveryUnsentQueueFileImmediately() throws Exception
	{
		Path directory = temporaryFolder.newFolder("clear").toPath();
		DurableSnapshotQueue queue = queue(directory, new MutableClock(STARTED_AT));
		queue.enqueue("record-1", "{\"synthetic\":true}");
		writeOrphans(directory);

		queue.clear();

		assertEquals(0, queue.size());
		assertEquals(List.of("unrelated.tmp"), names(directory));
	}

	@Test
	public void restartRemovesInterruptedWritesAndKeepsTheCommittedQueuePrivate() throws Exception
	{
		Path directory = temporaryFolder.getRoot().toPath().resolve("private");
		MutableClock clock = new MutableClock(STARTED_AT);
		queue(directory, clock).enqueue("record-1", "{\"synthetic\":1}");
		writeOrphans(directory);

		DurableSnapshotQueue restored = queue(directory, clock);

		assertEquals(DurableSnapshotQueue.LoadStatus.READY, restored.getLoadStatus());
		assertEquals("record-1", restored.peek().orElseThrow(AssertionError::new).getRecordId());
		assertEquals(List.of(DurableSnapshotQueue.FILE_NAME, "unrelated.tmp"), names(directory));
		assertEquals(List.of("private"), names(directory.getParent()));
		assumeTrue(TestStorage.posix());
		assertEquals("rw-------", TestStorage.permissions(directory.resolve(DurableSnapshotQueue.FILE_NAME)));
		assertEquals("rwx------", TestStorage.permissions(directory));
	}

	@Test
	public void failedEnqueueDoesNotBecomeAnInMemoryDuplicate() throws Exception
	{
		Path directory = temporaryFolder.getRoot().toPath().resolve("failed-enqueue");
		DurableSnapshotQueue queue = queue(directory, new MutableClock(STARTED_AT));
		Files.write(directory, "blocks-directory-creation".getBytes(StandardCharsets.UTF_8));

		assertThrows(
			IOException.class,
			() -> queue.enqueue("record-1", "{\"synthetic\":true}"));
		assertEquals(0, queue.size());

		Files.delete(directory);
		assertTrue(queue.enqueue("record-1", "{\"synthetic\":true}").wasAdded());
		assertEquals(1, queue.size());
	}

	@Test
	public void failedAcknowledgementKeepsMemoryAndDiskInFifoAgreement() throws Exception
	{
		Path directory = temporaryFolder.newFolder("failed-acknowledge").toPath();
		MutableClock clock = new MutableClock(STARTED_AT);
		DurableSnapshotQueue queue = queue(directory, clock);
		queue.enqueue("record-1", "{\"synthetic\":1}");
		queue.enqueue("record-2", "{\"synthetic\":2}");

		Path preservedDirectory = directory.resolveSibling("failed-acknowledge-preserved");
		Files.move(directory, preservedDirectory);
		Files.write(directory, "blocks-directory-creation".getBytes(StandardCharsets.UTF_8));

		assertThrows(IOException.class, () -> queue.acknowledge("record-1"));
		assertEquals(2, queue.size());
		assertEquals("record-1", queue.peek().orElseThrow(AssertionError::new).getRecordId());

		Files.delete(directory);
		Files.move(preservedDirectory, directory);
		DurableSnapshotQueue restored = queue(directory, clock);
		assertEquals(2, restored.size());
		assertEquals("record-1", restored.peek().orElseThrow(AssertionError::new).getRecordId());
		queue.acknowledge("record-1");
		assertEquals("record-2", queue.peek().orElseThrow(AssertionError::new).getRecordId());
	}

	private static DurableSnapshotQueue queue(Path directory, Clock clock) throws IOException
	{
		return new DurableSnapshotQueue(
			TestStorage.rooted(directory.getParent()).joinSegment(directory.getFileName().toString()),
			new Gson(),
			clock);
	}

	private static void writeOrphans(Path directory) throws IOException
	{
		byte[] partial = "partial".getBytes(StandardCharsets.UTF_8);
		Files.write(directory.resolve("snapshot-queue-v1.tmp"), partial);
		Files.write(directory.resolve("snapshot-queue-v1.6012893.tmp"), partial);
		Files.write(directory.resolve("unrelated.tmp"), partial);
	}

	private static List<String> names(Path directory) throws IOException
	{
		try (Stream<Path> files = Files.list(directory))
		{
			return files.map(file -> file.getFileName().toString()).sorted().collect(Collectors.toList());
		}
	}

	private static final class MutableClock extends Clock
	{
		private Instant now;

		private MutableClock(Instant now)
		{
			this.now = now;
		}

		private void advance(Duration duration)
		{
			now = now.plus(duration);
		}

		@Override
		public ZoneId getZone()
		{
			return ZoneOffset.UTC;
		}

		@Override
		public Clock withZone(ZoneId zone)
		{
			return this;
		}

		@Override
		public Instant instant()
		{
			return now;
		}
	}
}

