		BlockingQueue<BigInteger> savedSequences = new LinkedBlockingQueue<>();
		CountDownLatch incomingAccepted = new CountDownLatch(2);
		SnapshotClient incoming = snapshotClient(clock);
		assertTrue(incoming.connect(state.getCredentials(), context(INCOMING_SESSION), state.getNextSequence(), queue,
			listener(incomingAccepted, sequence ->
			{
				assertTrue(store.save(CREDENTIALS, sequence));
				savedSequences.add(sequence);
			})));

		assertEquals(outgoingBody, takeBatch().getBody().clone().readUtf8());
		assertTrue(incoming.publishImmediately(snapshot(SnapshotReason.MANUAL_SYNC)));
		JsonObject nextBatch = body(takeBatch().getBody().clone().readUtf8());
		assertEquals("8", nextBatch.get("sequence").getAsString());
		assertEquals(INCOMING_SESSION, nextBatch.get("sessionId").getAsString());
		assertNotEquals(outgoingBatch.get("batchId"), nextBatch.get("batchId"));
		assertTrue(incomingAccepted.await(5, TimeUnit.SECONDS));
		assertEquals(BigInteger.valueOf(9), savedSequences.poll(5, TimeUnit.SECONDS));
		assertEquals(BigInteger.valueOf(9), store.load().orElseThrow(AssertionError::new).getNextSequence());
		assertEquals(3, server.getRequestCount());
		incoming.cancel();
	}

	private RuneGlassPlugin plugin(boolean dropSyncEnabled) throws Exception
	{
		RuneGlassPlugin plugin = new RuneGlassPlugin();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			if ("getGameState".equals(method.getName()))
			{
				return gameState.get();
			}
			throw new AssertionError("Unexpected client read " + method.getName());
		});
		RuneGlassConfig config = new RuneGlassConfig()
		{
			@Override public boolean syncEnabled() { return true; }
			@Override public boolean dropSyncEnabled() { return dropSyncEnabled; }
		};
		ClientThread clientThread = new ClientThread()
		{
			@Override public void invokeLater(Runnable runnable) { clientThreadTasks.add(runnable); }
		};
		DropHandlerFixture.setField(plugin, "client", client);
		DropHandlerFixture.setField(plugin, "config", config);
		DropHandlerFixture.setField(plugin, "executor", executor);
		DropHandlerFixture.setField(plugin, "clientThread", clientThread);
		DropHandlerFixture.setField(plugin, "httpClient", new OkHttpClient());
		DropHandlerFixture.setField(plugin, "gson", gson);
		return plugin;
	}

	private SnapshotClient snapshotClient(Clock clock)
	{
		return new SnapshotClient(new OkHttpClient(), gson, executor, server.url("/"), clock, 1, () -> 0L);
	}

	private void runClientThreadTask() throws Exception
	{
		Runnable task = clientThreadTasks.poll(5, TimeUnit.SECONDS);
		assertNotNull("Storage did not report back to the client thread", task);
		task.run();
	}

	private void drainExecutor() throws Exception
	{
		executor.submit(() -> { }).get(5, TimeUnit.SECONDS);
	}

	private RecordedRequest takeBatch() throws Exception
	{
		RecordedRequest request = server.takeRequest(5, TimeUnit.SECONDS);
		assertNotNull(request);
		assertEquals("/runelite/v1/batches", request.getPath());
		return request;
	}

	private byte[] seedLegacyState() throws Exception
	{
		ConnectionStateStore store = new ConnectionStateStore(TestStorage.rooted(legacy).joinSegment("profiles"), PROFILE, gson);
		assertTrue(store.save(CREDENTIALS, BigInteger.valueOf(3)));
		return Files.readAllBytes(TestStorage.path(store.getStateFile()));
	}

	private static SnapshotClient.Listener listener(CountDownLatch accepted, Consumer<BigInteger> sequences)
	{
		return new SnapshotClient.Listener()
		{
			@Override public void onUploading(int recordCount) { }
			@Override public void onAccepted(Instant serverTime) { accepted.countDown(); }
			@Override public void onRetryScheduled() { throw new AssertionError("Unexpected retry"); }
			@Override public void onFailure(SnapshotClient.Failure failure) { throw new AssertionError("Unexpected failure " + failure); }
			@Override public void onNextSequenceChanged(BigInteger nextSequence) { sequences.accept(nextSequence); }
		};
	}

	private static MockResponse accepted(String status, String sequence)
	{
		return new MockResponse().setResponseCode(200).setHeader("Content-Type", "application/json")
			.setBody("{\"protocolVersion\":1,\"status\":\"" + status + "\",\"acceptedSequence\":\"" + sequence
				+ "\",\"serverTime\":\"2026-10-13T12:00:01Z\",\"nextUploadAfterSeconds\":1}");
	}

	private static JsonObject body(String text)
	{
		return new JsonParser().parse(text).getAsJsonObject();
	}

	private static SyncContext context(String sessionId)
	{
		return new SyncContext(sessionId, "Iron Jeromey", "ironman", "standard", "1.2.0", "1.13.1", 231);
	}

	private static SkillsSnapshot snapshot(SnapshotReason reason)
	{
		long[] experience = new long[SkillCatalog.VECTOR_SIZE];
		int[] levels = new int[SkillCatalog.VECTOR_SIZE];
		int[] boostedLevels = new int[SkillCatalog.VECTOR_SIZE];
		for (int index = 1; index < SkillCatalog.VECTOR_SIZE; index++)
		{
			experience[index] = index * 1_000L;
			levels[index] = 1;
			boostedLevels[index] = 1;
			experience[0] += experience[index];
			levels[0] += levels[index];
			boostedLevels[0] += boostedLevels[index];
		}
		return new SkillsSnapshot(CAPTURED_AT, reason, experience, levels, boostedLevels);
	}

	private static String profileHash(String profileKey) throws Exception
	{
		byte[] hash = MessageDigest.getInstance("SHA-256")
			.digest(("runeglass-profile-state-v1:" + profileKey).getBytes(StandardCharsets.UTF_8));
		return Base64.getUrlEncoder().withoutPadding().encodeToString(hash);
	}

	private static void write(Path file, String contents) throws IOException
	{
		Files.write(file, contents.getBytes(StandardCharsets.UTF_8));
	}

	private static List<String> names(Path directory) throws IOException
	{
		try (Stream<Path> files = Files.list(directory))
		{
			return files.map(file -> file.getFileName().toString()).sorted().collect(Collectors.toList());
		}
	}

	private static String text(Container container)
	{
		StringBuilder text = new StringBuilder();
		for (Component component : container.getComponents())
		{
			if (component instanceof JTextArea)
			{
				text.append(((JTextArea) component).getText()).append('\n');
			}
			if (component instanceof Container)
			{
				text.append(text((Container) component));
			}
		}
		return text.toString();
	}
}

package com.runeglass.runelite;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeTrue;

public class PrivateFilesTest
{
	@Rule
	public final TemporaryFolder temporaryFolder = new TemporaryFolder();

	@Test
	public void writesReplacementsAtomicallyWithOwnerOnlyFiles() throws Exception
	{
		assumeTrue(TestStorage.posix());
		Path rootPath = temporaryFolder.newFolder("plugin").toPath();
		Filepath target = TestStorage.rooted(rootPath).joinSegment("state.json");
		byte[] first = "{\"value\":1}".getBytes(StandardCharsets.UTF_8);
		byte[] second = "{\"value\":22}".getBytes(StandardCharsets.UTF_8);

		PrivateFiles.write(target, "state.", first);
		assertArrayEquals(first, Files.readAllBytes(TestStorage.path(target)));
		assertEquals("rw-------", TestStorage.permissions(TestStorage.path(target)));

		PrivateFiles.write(target, "state.", second);
		assertArrayEquals(second, Files.readAllBytes(TestStorage.path(target)));
		assertEquals("rw-------", TestStorage.permissions(TestStorage.path(target)));
		assertEquals(List.of("state.json"), names(rootPath));
	}

	@Test
	public void createsPrivateChildDirectoriesIdempotentlyAndConcurrently() throws Exception
	{
		ExecutorService threads = Executors.newFixedThreadPool(4);
		try
		{
			for (int round = 0; round < 50; round++)
			{
				Path rootPath = temporaryFolder.getRoot().toPath().resolve("absent-plugin-" + round);
				Filepath nested = TestStorage.rooted(rootPath).joinSegment("profiles").joinSegment("hash");
				CountDownLatch start = new CountDownLatch(1);
				List<Future<Boolean>> results = new ArrayList<>();
				for (int index = 0; index < 4; index++)
				{
					String name = "state-" + index + ".json";
					results.add(threads.submit((Callable<Boolean>) () ->
					{
						assertTrue(start.await(5, TimeUnit.SECONDS));
						PrivateFiles.createDirectory(nested);
						PrivateFiles.write(nested.joinSegment(name), "state.", new byte[]{1});
						return true;
					}));
				}
				start.countDown();
				for (Future<Boolean> result : results)
				{
					assertTrue(result.get(5, TimeUnit.SECONDS));
				}
				PrivateFiles.createDirectory(nested);

				assertEquals(List.of("profiles"), names(rootPath));
				assertEquals(List.of("hash"), names(rootPath.resolve("profiles")));
				assertEquals(List.of("state-0.json", "state-1.json", "state-2.json", "state-3.json"),
					names(rootPath.resolve("profiles").resolve("hash")));
				if (TestStorage.posix())
				{
					assertEquals("rwx------", TestStorage.permissions(rootPath.resolve("profiles")));
					assertEquals("rwx------", TestStorage.permissions(rootPath.resolve("profiles").resolve("hash")));
				}
			}
		}
		finally
		{
			threads.shutdownNow();
		}
	}

	@Test
	public void failedReplacementKeepsTheTargetAndRemovesItsTemporaryFile() throws Exception
	{
		Path rootPath = temporaryFolder.newFolder("plugin").toPath();
		Files.createDirectories(rootPath.resolve("state.json").resolve("occupied"));
		Filepath target = TestStorage.rooted(rootPath).joinSegment("state.json");

		assertThrows(IOException.class, () -> PrivateFiles.write(
			target,
			"state.",
			"{}".getBytes(StandardCharsets.UTF_8)));

		assertEquals(List.of("state.json"), names(rootPath));
		assertEquals(List.of("occupied"), names(rootPath.resolve("state.json")));
	}

	@Test
	public void deletesOnlyMatchingLegacyAndRandomTemporaryFiles() throws Exception
	{
		Path rootPath = temporaryFolder.newFolder("queue").toPath();
		for (String name : List.of(
			"snapshot-queue-v1.tmp",
			"snapshot-queue-v1.123456.tmp",
			"snapshot-queue-v1.json",
			"connection-state-v1.tmp",
			"other.tmp"))
		{
			Files.write(rootPath.resolve(name), new byte[]{1});
		}
		Files.createDirectory(rootPath.resolve("snapshot-queue-v1.dir.tmp"));

		PrivateFiles.deleteTemporaryFiles(TestStorage.rooted(rootPath), "snapshot-queue-v1.");
		PrivateFiles.deleteTemporaryFiles(TestStorage.rooted(rootPath).joinSegment("absent"), "snapshot-queue-v1.");

		assertEquals(
			List.of("connection-state-v1.tmp", "other.tmp", "snapshot-queue-v1.dir.tmp", "snapshot-queue-v1.json"),
			names(rootPath));
	}

	@Test
	public void readsStrictUtf8() throws Exception
	{
		Path rootPath = temporaryFolder.newFolder("plugin").toPath();
		Files.write(rootPath.resolve("valid.json"), "{\"name\":\"界\"}".getBytes(StandardCharsets.UTF_8));
		Files.write(rootPath.resolve("invalid.json"), new byte[]{'"', (byte) 0xC3, (byte) 0x28, '"'});
		Filepath root = TestStorage.rooted(rootPath);

		assertEquals("{\"name\":\"界\"}", PrivateFiles.readUtf8(root.joinSegment("valid.json")));
		assertThrows(IOException.class, () -> PrivateFiles.readUtf8(root.joinSegment("invalid.json")));
	}

	private static List<String> names(Path directory) throws IOException
	{
		try (Stream<Path> files = Files.list(directory))
		{
			return files.map(file -> file.getFileName().toString()).sorted().collect(Collectors.toList());
		}
	}
}

package com.runeglass.runelite;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class QuestCaptureLifecycleTest
{
	private static final Instant NOW = Instant.parse("2026-10-07T12:00:00Z");
	private MockWebServer server;
	private ScheduledExecutorService executor;
	private SemanticSnapshotClient<QuestSnapshot> transport;
	private RuneGlassPlugin plugin;
	private boolean masterEnabled;
	private boolean questEnabled;
	private CountDownLatch retryScheduled;

	@Before
	public void setUp() throws Exception
	{
		server = new MockWebServer();
		server.start();
		executor = Executors.newSingleThreadScheduledExecutor();
		OkHttpClient http = new OkHttpClient();
		Gson gson = new Gson();
		Clock clock = Clock.fixed(NOW, ZoneOffset.UTC);
		transport = new SemanticSnapshotClient<>(http, gson, executor, server.url("/"), clock, 1, () -> 0L,
			"runelite/v1/quests", (context, connectionId, snapshot) -> SemanticSnapshotPayload.create(
				context, connectionId, snapshot.getSnapshotId(), snapshot.getObservedAt(), "progress", snapshot.getProgress()));
		plugin = new RuneGlassPlugin();
		masterEnabled = true;
		questEnabled = true;
		RuneGlassConfig config = (RuneGlassConfig) Proxy.newProxyInstance(RuneGlassConfig.class.getClassLoader(), new Class<?>[]{RuneGlassConfig.class}, (proxy, method, args) ->
		{
			if ("syncEnabled".equals(method.getName())) return masterEnabled;
			if ("questSyncEnabled".equals(method.getName())) return questEnabled;
			throw new AssertionError("Unexpected config read " + method.getName());
		});
		setField("config", config);
		setField("questClient", transport);
		setField("pairingClient", new PairingClient(http, gson, executor, server.url("/"), clock));
		setField("snapshotClient", new SnapshotClient(http, gson, executor, server.url("/"), clock, 1, () -> 0L));
		retryScheduled = new CountDownLatch(1);
		transport.connect(new PairingClient.Credentials("pcn_" + "c".repeat(43), "r".repeat(43)),
			new SyncContext("0b54873e-c169-4de7-9bd0-abc879f84d2f", "Fixture", "regular", "standard", "1.2.0", "1.13.1", 231),
			new SemanticSnapshotClient.Listener()
			{
				@Override public void onAccepted(Instant serverTime) {}
				@Override public void onRetryScheduled() { retryScheduled.countDown(); }
				@Override public void onFailure(SemanticSnapshotClient.Failure failure) {}
			});
	}

	@After
	public void tearDown() throws Exception
	{
		transport.discard();
		executor.shutdownNow();
		server.shutdown();
	}

	@Test
	public void questOptOutDiscardsAnAlreadyQueuedRetry() throws Exception
	{
		queueRetry();
		questEnabled = false;
		invoke("handleConfigChanged", String.class, "questSyncEnabled");
		assertDiscarded();
	}

	@Test
	public void masterOffDiscardsAnAlreadyQueuedRetry() throws Exception
	{
		queueRetry();
		masterEnabled = false;
		invoke("handleConfigChanged", String.class, "syncEnabled");
		assertDiscarded();
	}

	@Test
	public void profileSwitchDiscardsAnAlreadyQueuedRetry() throws Exception
	{
		queueRetry();
		invoke("finishSession", SnapshotReason.class, SnapshotReason.PROFILE_SWITCH);
		assertDiscarded();
	}

	@Test
	public void profileBecomingReadyRestartsThePreviouslyUnboundSession() throws Exception
	{
		assertFalse(plugin.needsProfileRestart(null));
		assertTrue(plugin.needsProfileRestart("ready-profile"));
		setField("activeProfileKey", "ready-profile");
		assertFalse(plugin.needsProfileRestart("ready-profile"));
		assertTrue(plugin.needsProfileRestart("other-profile"));
		assertTrue(plugin.needsProfileRestart(null));
	}

	private void queueRetry() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(429).setHeader("Retry-After", "1"));
		assertTrue(transport.publish(snapshot()));
		assertTrue(server.takeRequest(3, TimeUnit.SECONDS) != null);
		assertTrue(retryScheduled.await(3, TimeUnit.SECONDS));
		QuestSnapshotReducer reducer = (QuestSnapshotReducer) getField("questReducer");
		assertTrue(reducer.observe(NOW, 1, Map.of(17, "completed")).isPresent());
		assertFalse(reducer.observe(NOW, 1, Map.of(17, "completed")).isPresent());
	}

	private void assertDiscarded() throws Exception
	{
		assertFalse(transport.publish(snapshot()));
		assertNull(server.takeRequest(1200, TimeUnit.MILLISECONDS));
		QuestSnapshotReducer reducer = (QuestSnapshotReducer) getField("questReducer");
		assertTrue(reducer.observe(NOW, 1, Map.of(17, "completed")).isPresent());
	}

	private QuestSnapshot snapshot()
	{
		return new QuestSnapshot(NOW, 1, Map.of(17, "completed"));
	}

	private void invoke(String name, Class<?> type, Object argument) throws Exception
	{
		Method method = RuneGlassPlugin.class.getDeclaredMethod(name, type);
		method.setAccessible(true);
		method.invoke(plugin, argument);
	}

	private void setField(String name, Object value) throws Exception
	{
		Field field = RuneGlassPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		field.set(plugin, value);
	}

	private Object getField(String name) throws Exception
	{
		Field field = RuneGlassPlugin.class.getDeclaredField(name);
		field.setAccessible(true);
		return field.get(plugin);
	}
}

package com.runeglass.runelite;

import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.VarPlayerID;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

public class QuestSnapshotReaderTest
{
	@Test
	public void readsExplicitIdsMapsStatusSemanticsAndLeavesUnrecognizedEntriesUnknown()
	{
		AtomicInteger currentId = new AtomicInteger();
		List<Integer> seenIds = new ArrayList<>();
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			if ("runScript".equals(method.getName()))
			{
				Object[] script = (Object[]) args[0];
				assertEquals(ScriptID.QUEST_STATUS_GET, script[0]);
				currentId.set((Integer) script[1]);
				seenIds.add(currentId.get());
				if (currentId.get() == 3) throw new IllegalStateException("Unreadable fixture");
				return null;
			}
			if ("getIntStack".equals(method.getName()))
			{
				if (currentId.get() == 0) return new int[]{2};
				if (currentId.get() == 1) return new int[]{1};
				if (currentId.get() == 17) return new int[]{0};
				if (currentId.get() == 4) return new int[0];
				return new int[]{-1};
			}
			throw new AssertionError("Unexpected client read " + method.getName());
		});
		Map<Integer, String> states = QuestSnapshotReader.readStates(client);
		assertEquals(213, seenIds.size());
		assertEquals("completed", states.get(0));
		assertEquals("not_started", states.get(1));
		assertEquals("in_progress", states.get(17));
		assertEquals(3, states.size());
		assertFalse(states.containsKey(3));
		assertFalse(states.containsKey(4));
		assertFalse(seenIds.contains(2));
	}

	@Test
	public void readsCurrentQuestPointsFromThePinnedModernConstant()
	{
		Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class}, (proxy, method, args) ->
		{
			assertEquals("getVarpValue", method.getName());
			assertEquals(101, VarPlayerID.QP);
			assertEquals(VarPlayerID.QP, args[0]);
			return 343;
		});
		assertEquals(343, QuestSnapshotReader.readQuestPoints(client));
	}
}

package com.runeglass.runelite;

import java.time.Instant;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.Quest;
import org.junit.Test;
import static org.junit.Assert.*;

public class QuestSnapshotReducerTest
{
	@Test
	public void explicitCatalogMatchesPinnedRuneLiteApiIncludingNewQuests()
	{
		Set<Integer> ids = Arrays.stream(Quest.values()).map(Quest::getId).collect(Collectors.toSet());
		assertEquals(213, QuestCatalog.ids().length);
		for (int id : QuestCatalog.ids()) assertTrue("Missing Quest ID " + id, ids.contains(id));
		assertTrue(ids.contains(16971));
		assertTrue(ids.contains(16972));
	}

	@Test
	public void capturesStableBaselineThenOnlyDebouncedDirtyChangesAtBoundedFrequency()
	{
		QuestSnapshotReducer reducer = new QuestSnapshotReducer();
		assertFalse(reducer.shouldCapture()); assertFalse(reducer.shouldCapture());
		assertTrue(reducer.shouldCapture());
		for (int i = 0; i < 100; i++) assertFalse(reducer.shouldCapture());
		reducer.markDirty();
		assertFalse(reducer.shouldCapture()); assertFalse(reducer.shouldCapture());
		assertTrue(reducer.shouldCapture());
		int captures = 0;
		for (int i = 0; i < 200; i++) { reducer.markDirty(); if (reducer.shouldCapture()) captures++; }
		assertEquals(4, captures);
		reducer.reset();
		assertFalse(reducer.shouldCapture()); assertFalse(reducer.shouldCapture()); assertTrue(reducer.shouldCapture());
	}

	@Test
	public void unchangedSemanticBodyIsNotPublishedAndPartialMissingEntriesStayAbsent()
	{
		QuestSnapshotReducer reducer = new QuestSnapshotReducer();
		Map<Integer, String> states = new LinkedHashMap<>();
		states.put(17, "not_started");
		Instant now = Instant.parse("2026-10-07T12:00:00Z");
		QuestSnapshot initial = reducer.observe(now, 0, states).get();
		assertEquals("partial", initial.getProgress().get("coverage"));
		assertFalse(reducer.observe(now.plusSeconds(1), 0, states).isPresent());
		states.put(17, "completed");
		assertTrue(reducer.observe(now.plusSeconds(2), 1, states).isPresent());
		reducer.reset();
		assertTrue(reducer.observe(now.plusSeconds(3), 1, states).isPresent());
	}

	@Test
	public void manualRefreshEmitsUnchangedProgressWithANewIdentityAndObservationTime()
	{
		QuestSnapshotReducer reducer = new QuestSnapshotReducer();
		Instant now = Instant.parse("2026-10-07T12:00:00Z");
		Map<Integer, String> states = Map.of(17, "completed");
		QuestSnapshot initial = reducer.observe(now, 1, states).get();
		QuestSnapshot manual = reducer.observeManual(now.plusSeconds(30), 1, states);
		assertEquals(initial.getProgress(), manual.getProgress());
		assertNotEquals(initial.getSnapshotId(), manual.getSnapshotId());
		assertEquals(now.plusSeconds(30).toString(), manual.getObservedAt());
		assertFalse(reducer.observe(now.plusSeconds(31), 1, states).isPresent());
	}

	@Test
	public void manualChangesUpdateAutomaticDedupeAndChangedQuestPointsStillEmit()
	{
		QuestSnapshotReducer reducer = new QuestSnapshotReducer();
		Instant now = Instant.parse("2026-10-07T12:00:00Z");
		assertTrue(reducer.observe(now, 0, Map.of(17, "not_started")).isPresent());
		reducer.observeManual(now.plusSeconds(1), 1, Map.of(17, "completed"));
		assertFalse(reducer.observe(now.plusSeconds(2), 1, Map.of(17, "completed")).isPresent());
		QuestSnapshot changed = reducer.observe(now.plusSeconds(3), 2, Map.of(17, "completed")).get();
		assertEquals(2, changed.getProgress().get("questPoints"));
	}

	@Test
	public void rejectsUnknownIdsAndMalformedState()
	{
		assertThrows(IllegalArgumentException.class, () -> new QuestSnapshot(Instant.now(), 0, Map.of(999999, "completed")));
		assertThrows(IllegalArgumentException.class, () -> new QuestSnapshot(Instant.now(), 0, Map.of(17, "unknown")));
		assertThrows(IllegalArgumentException.class, () -> new QuestSnapshot(Instant.now(), -1, Map.of(17, "not_started")));
	}
}

package com.runeglass.runelite;

import java.lang.reflect.Method;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RuneGlassConfigTest
{
	@Test
	public void synchronizationIsExplicitlyOptIn()
	{
		RuneGlassConfig config = new RuneGlassConfig()
		{
		};

		assertFalse(config.syncEnabled());
		assertFalse(config.birdHouseSyncEnabled());
		assertFalse(config.farmingPatchSyncEnabled());
		assertFalse(config.appearanceSyncEnabled());
		assertFalse(config.questSyncEnabled());
		assertFalse(config.dropSyncEnabled());
		assertFalse(config.dropCountSyncEnabled());
	}

	@Test
	public void masterAndNewDropConsentShowTheirSharingWarnings() throws Exception
	{
		int warningCount = 0;
		for (Method method : RuneGlassConfig.class.getDeclaredMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item != null && !item.warning().isEmpty())
			{
				assertTrue(item.keyName().equals("syncEnabled") || item.keyName().equals("dropSyncEnabled") || item.keyName().equals("dropCountSyncEnabled"));
				assertEquals(item.keyName().equals("syncEnabled")
					? RuneGlassConfig.THIRD_PARTY_WARNING : item.keyName().equals("dropSyncEnabled")
					? RuneGlassConfig.DROP_SHARING_WARNING : RuneGlassConfig.DROP_COUNT_SHARING_WARNING, item.warning());
				warningCount++;
			}
		}
		assertEquals(3, warningCount);

		String warning = RuneGlassConfig.THIRD_PARTY_WARNING;
		assertTrue(warning.length() <= 300);
		for (String line : warning.split("\n"))
		{
			assertTrue(line.length() <= 80);
		}
		assertTrue(warning.contains("character name/type"));
		assertTrue(warning.contains("skills/XP"));
		assertTrue(warning.contains("enabled timers, quests"));
		assertTrue(warning.contains("3D appearance"));
		assertTrue(warning.contains("version information and IP address"));
		assertTrue(warning.contains("RuneGlass,"));
		assertTrue(warning.contains("a third-party service"));
		assertTrue(warning.contains("not controlled or verified by RuneLite developers"));

		String description = RuneGlassConfig.class.getMethod("syncEnabled").getAnnotation(ConfigItem.class).description();
		assertTrue(description.contains("Enable sharing"));
		assertTrue(description.contains("Timers, quests, appearance and drops require their separate toggles"));
	}

	@Test
	public void timerDescriptionsRetainTheirDataBoundaries() throws Exception
	{
		String birdHouses = RuneGlassConfig.class.getMethod("birdHouseSyncEnabled").getAnnotation(ConfigItem.class).description();
		assertTrue(birdHouses.contains("semantic bird house states observed on Fossil Island"));
		assertTrue(birdHouses.contains("No raw varps or location history are sent"));

		String farming = RuneGlassConfig.class.getMethod("farmingPatchSyncEnabled").getAnnotation(ConfigItem.class).description();
		assertTrue(farming.contains("semantic crop and tree states observed at supported farming locations"));
		assertTrue(farming.contains("Compost bins are excluded"));
		assertTrue(farming.contains("No raw varbits or location history are sent"));
	}

	@Test
	public void dropConsentDisclosesCapturedStackThresholdAndWholeRewardRetention() throws Exception
	{
		ConfigItem item = RuneGlassConfig.class.getMethod("dropSyncEnabled").getAnnotation(ConfigItem.class);
		assertTrue(item.warning().contains("drop sources, items, quantities, times and value estimates"));
		assertTrue(item.warning().contains("not controlled or verified by"));
		assertTrue(item.warning().contains("Saved history remains until you delete it"));
		assertTrue(item.warning().length() <= 300);
		for (String line : item.warning().split("\n"))
		{
			assertTrue(line.length() <= 80);
		}
		String description = item.description();
		assertTrue(description.contains("item stack worth at least 50,000 GP at capture"));
		assertTrue(description.contains("curated notable reward, including all accompanying items"));
		assertTrue(description.contains("Loot Tracker must be enabled"));
		assertTrue(description.contains("History remains until deletion"));
		assertTrue(description.contains("deletes unsent drops across local profiles"));
	}

	@Test
	public void existingUsersMustSeparatelyEnableCountSharingWithItsOwnWarning() throws Exception
	{
		RuneGlassConfig existing = new RuneGlassConfig()
		{
			@Override public boolean syncEnabled() { return true; }
			@Override public boolean dropSyncEnabled() { return true; }
		};
		assertFalse(existing.dropCountSyncEnabled());
		ConfigItem item = RuneGlassConfig.class.getMethod("dropCountSyncEnabled").getAnnotation(ConfigItem.class);
		assertEquals("Share kill counts with drops", item.name());
		assertEquals(6, item.position());
		assertEquals(RuneGlassConfig.DROP_COUNT_SHARING_WARNING, item.warning());
		assertTrue(item.warning().length() <= 300);
		for (String line : item.warning().split("\n")) assertTrue(line.length() <= 80);
		for (String disclosure : new String[]{"boss kill counts", "raid completions including mode", "Barrows chests",
			"clue caskets", "notification settings", "reported an item as new", "counts were missed", "never uploaded or stored",
			"Only works while Sync drop history is on", "the drops are kept"})
			assertTrue(disclosure, item.description().contains(disclosure));
		assertTrue(RuneGlassConfig.class.getMethod("dropSyncEnabled").getAnnotation(ConfigItem.class).description()
			.contains("only when Share kill counts with drops is on"));
	}

	@Test
	public void appearanceConsentDisclosesRenderMetadataAndRetention() throws Exception
	{
		ConfigItem item = RuneGlassConfig.class.getMethod("appearanceSyncEnabled").getAnnotation(ConfigItem.class);
		String description = item.description();
		assertTrue(description.contains("equipped item identifiers"));
		assertTrue(description.contains("body colours"));
		assertTrue(description.contains("gender presentation"));
		assertTrue(description.contains("model geometry"));
		assertTrue(description.contains("render attributes (including texture identifiers)"));
		assertTrue(description.contains("No other players, animations, screenshots or texture assets are sent"));
		assertTrue(description.contains("pauses uploads; delete stored data in RuneGlass settings"));
	}
}

package com.runeglass.runelite;

import java.awt.Component;
import java.awt.Container;
import java.awt.FontMetrics;
import java.awt.Insets;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RuneGlassPanelLayoutTest
{
	@Test
	public void allSyncStatesFitTheStandardRuneLiteSidebarWidth() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			RuneGlassPanel panel = new RuneGlassPanel(() -> { }, () -> { }, () -> { });
			panel.setSize(PluginPanel.PANEL_WIDTH, 700);

			List<Runnable> states = new ArrayList<>();
			states.add(panel::showReady);
			states.add(panel::showConnected);
			states.add(() -> panel.showUploading(8));
			states.add(() -> panel.showSynced(Instant.parse("2026-08-24T14:15:00Z")));
			states.add(panel::showRetrying);
			states.add(() -> panel.showDropStatus("Drops waiting to retry. 10000 drop events saved locally, waiting to sync. Some local records need attention and have not been uploaded. Some drops in this session could not be saved."));
			states.add(() -> panel.showFailure(PairingClient.Failure.CONNECTION_LIMIT));
			states.add(() -> panel.showSnapshotFailure(
				SnapshotClient.Failure.BINDING_MISMATCH));

			for (Runnable state : states)
			{
				state.run();
				layoutTree(panel);
				assertReadable(panel);
			}
		});
	}

	@Test
	public void connectionLimitExplainsHowToRecover() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			RuneGlassPanel panel = new RuneGlassPanel(() -> { }, () -> { }, () -> { });
			panel.showFailure(PairingClient.Failure.CONNECTION_LIMIT);
			String detail = descendants(panel, JTextArea.class).stream()
				.map(JTextArea::getText)
				.reduce("", (left, right) -> left + " " + right);
			assertTrue(detail.contains("connection limit"));
			assertTrue(detail.contains("disconnect an unused client"));
			assertTrue(detail.contains("generate a new code"));
			assertFalse(detail.contains("Check your connection"));
		});
	}

	private static void assertReadable(RuneGlassPanel panel)
	{
		List<JTextArea> textAreas = descendants(panel, JTextArea.class);
		assertEquals(3, textAreas.size());
		for (JTextArea textArea : textAreas)
		{
			assertTrue("Text must use the sidebar width", textArea.getWidth() >= 190);
			assertTrue(
				"Text must not be vertically clipped",
				textArea.getHeight() >= textArea.getPreferredSize().height);
		}

		for (JButton button : descendants(panel, JButton.class))
		{
			if (!button.isVisible())
			{
				continue;
			}
			FontMetrics metrics = button.getFontMetrics(button.getFont());
			Insets insets = button.getInsets();
			int requiredButtonWidth = metrics.stringWidth(button.getText())
				+ insets.left
				+ insets.right;
			assertTrue("Button label must fit", button.getWidth() >= requiredButtonWidth);
		}

		List<JLabel> labels = descendants(panel, JLabel.class);
		assertFalse(labels.isEmpty());
		JLabel title = labels.stream()
			.filter(label -> "RuneGlass".equals(label.getText()))
			.findFirst()
			.orElseThrow(AssertionError::new);
		assertTrue(
			"Title must fit without ellipsis",
			title.getWidth() >= title.getPreferredSize().width);
	}

	private static void layoutTree(Container container)
	{
		container.doLayout();
		for (Component component : container.getComponents())
		{
			if (component instanceof Container)
			{
				layoutTree((Container) component);
			}
		}
	}

	private static <T extends Component> List<T> descendants(Container root, Class<T> type)
	{
		List<T> matches = new ArrayList<>();
		for (Component component : root.getComponents())
		{
			if (type.isInstance(component))
			{
				matches.add(type.cast(component));
			}
			if (component instanceof Container)
			{
				matches.addAll(descendants((Container) component, type));
			}
		}
		return matches;
	}
}

